// Original lesson material. Scope was checked against the supplied V4 microtopic audit.
const P = (label, command, actor, target, pre, expected, verify, rollback) => ({ label, command, actor, target, pre, expected, verify, rollback });
const L = x => ({ ...x,
  quick: x.quick || `Use this lesson to make a bounded DBA decision about ${x.scope.slice(0,3).join(', ')}. The key is to identify the failing layer and scope before changing state.`,
  first: x.first || 'Capture the current target, timestamp, release, and read-only state before acting.',
  concept: x.concept || `The useful mental model is to follow ${x.scope.join('; ')} from the service boundary inward. Record who owns each boundary and which evidence is authoritative there.`,
  model: x.model || `Scope: ${x.scope.join(' → ')}. The arrows represent dependency, not proof of a fault. Confirm each hop independently.`,
  stopRule: x.stopRule || 'Stop if the target identity, current state, authority, or rollback dependency is uncertain; preserve evidence and escalate.',
  checks: x.checks || ['Compare the post-state with the captured pre-state.', 'Confirm the intended service or data outcome independently of the command return code.'],
  checklist: x.checklist || ['Name the target and scope.', 'Collect a baseline and confirm prerequisites.', 'Choose the least disruptive supported branch.', 'Verify state and service behavior.', 'Record evidence and recovery limits.']
});
