export const lessons = [];

lessons.push(
L({id:'A-01',title:'Host, server, virtualization, capacity, and failure domains',scope:['physical or virtual host sizing','CPU topology, SMT, NUMA and steal time','memory reservation and ballooning','virtual storage/network and noisy neighbors','capacity and failure-domain placement'],quick:'Use host evidence to decide whether a Db2 symptom is local, shared, or caused by an undersized virtual resource. A VM dashboard is not a substitute for guest and Db2 measurements.',branches:[['Bare metal','Use when the guest owns the hardware counters and device paths.','NUMA locality and firmware still matter.'],['VM/cloud VM','Compare guest metrics with hypervisor reservation, ready/steal and storage latency.','Do not infer host headroom from vCPU count alone.'],['Failure-domain review','Map instance, storage, network, power and site dependencies.','A second VM in one rack or zone is not an independent DR site.']],lifecycle:['Define workload target and observation window.','Inventory host topology and guest limits.','Collect aligned OS, hypervisor and Db2 samples.','Compare measured peak and failover demand with usable headroom.','Document a placement or capacity decision and remeasure after change.'],precheck:['Record host, VM, clock, workload window, and Db2 member.','Obtain read-only hypervisor and cloud telemetry; note unit and interval.','Do not change vCPU or memory live without the platform change plan.'],commands:[P('Guest CPU and NUMA inventory','lscpu; numactl --hardware','Linux DBA/host administrator','Db2 server host','Tools installed; read-only host access.','CPU model, logical/physical topology, and node memory are printed.','Compare socket/node counts with Db2 process placement and hypervisor allocation.','No state changes; install missing tools only through host change management.'),P('Linux CPU sample','mpstat -P ALL 1 5','Linux host operator','Target host over five one-second intervals','sysstat package available; record the exact incident window.','Per-CPU user/system/iowait/steal values appear.','Correlate steal time and saturation with hypervisor ready time and Db2 EDU CPU.','Sampling is read-only; widen the window before a capacity change.')],example:'At 09:10 a report query slows while guest CPU shows 35% idle and 18% steal. The guest has spare scheduled CPU, but the hypervisor is delaying vCPU execution. Treat this as a placement/contention problem until host telemetry disproves it; adding Db2 agents would increase runnable demand.',expected:'Decision record distinguishes Db2 CPU demand from VM scheduling and records the actual peak/failover capacity.',checks:['Align guest and hypervisor samples to the same clock and interval.','Re-run the same workload after a placement change; compare throughput and latency percentiles.'],issues:[{symptom:'Db2 latency rises while guest CPU appears idle.',evidence:'mpstat steal, hypervisor CPU ready, and Db2 per-EDU deltas.',cause:'vCPU descheduling or contention on an oversubscribed host.',fix:'Move or resize through the virtualization change process, then repeat the measured workload.',avoid:'Increasing Db2 parallelism before confirming guest scheduling delay.'},{symptom:'Failover host is nominally large but runs out of headroom.',evidence:'Peak CPU/memory demand plus all-active and failover topology.',cause:'Capacity counted from installed size instead of usable post-failure capacity.',fix:'Recalculate with one failure domain removed and realistic concurrency.',avoid:'Counting standby capacity as spare for unrelated workloads.'}],lab:'Build a host inventory for a fictional four-vCPU Db2 VM. Add CPU model, NUMA nodes, guest memory limit, storage latency, and host failure domain. Create two timelines, one CPU-bound and one steal-bound. Explain which owner receives each incident. Cleanup: keep the report as lab evidence; make no VM changes.',question:'Guest CPU has 40% idle, but steal is 20% and Db2 service time grows. What is your first escalation?',answer:'Ask the virtualization/cloud owner to inspect ready/steal and noisy-neighbor placement using the same interval; the guest cannot explain scheduler delay alone. Keep a Db2 baseline so a simultaneous engine bottleneck is not missed.',diagram:'flowchart LR\nW[Workload SLO] --> G[Guest CPU memory I/O]\nG --> H[Hypervisor or cloud telemetry]\nG --> D[Db2 EDU and member evidence]\nH --> X{Shared failure domain?}\nD --> X',refs:[['IBM system requirements','https://www.ibm.com/docs/en/db2/12.1.x?topic=servers-db2-installation-methods'],['Linux mpstat manual','https://man7.org/linux/man-pages/man1/mpstat.1.html']],related:['A-03','A-04','I-06'] }),
L({id:'A-02',title:'Linux identity, filesystems, permissions, limits, and services',scope:['user, group and supplementary-group resolution','instance owner and profile environment','directory traversal, ACL, umask and mount ownership','open files and process limits','systemd startup and service identity','Linux versus AIX/Windows service differences'],branches:[['Instance owner','Use the dedicated OS account for Db2 CLP and instance operations.','Do not run routine Db2 work as root.'],['Root/service administrator','Use only for install, OS service, ownership, or approved host work.','Root cannot replace correct instance identity.'],['Windows/AIX host','Use native service manager, groups, registry/environment and limit tools.','Do not transpose Linux paths or systemd behavior.']],lifecycle:['Resolve account and groups from the host name service.','Confirm the instance profile and effective environment.','Walk every parent directory and inspect mount, ACL and limits.','Check service definition, run-as account and boot ordering.','Test a controlled read-only access as the service identity.'],precheck:['Confirm the target instance name, owner UID/GID, home and profile.','Check name-service consistency on each cluster node.','Record current permissions and service startup configuration before edits.'],commands:[P('Identity resolution','id db2inst1; getent passwd db2inst1; getent group db2iadm1','Linux host operator','Server account and groups','Read access to NSS; names are lab examples.','UID, primary/supplementary groups and account mapping are returned.','Compare across every host; verify actual process UID with ps -eo user,pid,args.','Do not chown broad trees to fix a mismatch; correct the single named owner/group with host approval.'),P('Path traversal and modes','namei -l /db2data/SAMPLE; getfacl -p /db2data/SAMPLE','Instance owner and host administrator','Database path chain','ACL tool available; inspect parent directories as well as leaf.','Each component permission and any ACL mask is visible.','Run a minimal read/write test as the instance owner in a disposable directory.','Restore captured ACL/mode only through a scoped change; do not use chmod -R 777.')],example:'A backup target exists and has free space, but a backup utility reports a path permission failure. `namei -l` shows the Db2 owner can write the final folder but cannot traverse its parent. Repair the narrow parent execute permission for the intended group, then validate access as the instance owner.',expected:'Instance services start as the configured owner, and only intended service identities can traverse/write data and diagnostic paths.',issues:[{symptom:'A Db2 path returns permission denied despite write permission on the leaf.',evidence:'id, namei -l, getfacl, mount flags, and process UID.',cause:'A parent directory lacks execute/traverse permission or an ACL mask removes rights.',fix:'Correct the specific directory/group ACL and repeat the access test under the Db2 UID.',avoid:'Changing every file to world-writable.'},{symptom:'Service starts manually but not after reboot.',evidence:'systemd unit, journal, environment/profile, dependency ordering, and account lookup.',cause:'Service manager does not load the interactive instance profile or starts before a required mount.',fix:'Use the supported Db2 service integration and declare the correct mount/service dependency.',avoid:'Embedding a password or ad hoc `source` command into an unrelated global unit.'}],lab:'Compare account resolution and path permissions on two lab hosts. Write a service-start checklist that identifies which steps belong to root, the instance owner, and systemd. Do not change production ownership. Cleanup: remove only the disposable test directory.',question:'Why can `db2inst1` write a directory but fail to open a file in it?',answer:'A missing execute bit on a parent, ACL mask, read-only mount, security policy, or process identity mismatch can block access. Inspect the whole path and actual service UID before changing the leaf mode.',diagram:'flowchart TD\nN[NSS identity and groups] --> P[Db2 process UID and environment]\nP --> D[Parent directory traversal]\nD --> A[ACL mode and mount]\nA --> F[Database log backup diagnostic files]',refs:[['IBM installation methods','https://www.ibm.com/docs/en/db2/12.1.x?topic=servers-db2-installation-methods'],['Linux namei manual','https://man7.org/linux/man-pages/man1/namei.1.html']],related:['A-04','B-02','J-01'] }),
L({id:'A-03',title:'CPU, memory, process, paging, and Db2 EDU diagnosis',scope:['runnable versus blocked processes','load average versus CPU saturation','user/system/steal/iowait','process and thread samples','cgroup limits','memory pressure, paging, swap and OOM','Db2 EDU attribution'],branches:[['CPU saturation','High non-idle CPU and runnable queue persists through the workload window.','One snapshot or load average is insufficient.'],['Blocked work','High load may coexist with idle CPU when work waits on locks or I/O.','Do not tune CPU parameters to treat a wait.'],['Memory pressure','Use reclaim, paging, cgroup and Db2 memory evidence together.','RSS alone does not prove an allocation leak.']],lifecycle:['Capture a time-aligned interval baseline.','Separate runnable, sleeping and blocked Db2 processes/EDUs.','Check guest/cgroup memory limits, reclaim, paging and OOM evidence.','Map the symptom to SQL, lock, storage or engine work.','Repeat after the narrow corrective action.'],precheck:['Record sample interval and host timezone.','Use non-invasive tools; avoid attaching debuggers to a production engine.','Resolve PID/member mapping with Db2 before interpreting a thread.'],commands:[P('OS scheduler and paging sample','vmstat 1 5','Linux host operator','Server during incident window','Read-only access; first line is since boot on common procps versions.','Five interval rows show run queue, swap, I/O wait, and CPU fields.','Interpret interval rows, then compare with pidstat and Db2 EDU CPU deltas.','Sampling is read-only; no service restart based on one row.'),P('Db2 EDU view','db2pd -db SAMPLE -edus','Instance owner','Connected instance and active SAMPLE database','Instance is running; choose the correct member for DPF/pureScale.','EDU IDs, names, status and CPU data are displayed.','Take a second sample after a bounded interval; correlate EDU with application/statement evidence.','Read-only; use a support collection if engine responsiveness is compromised.')],example:'`vmstat` shows a high run queue with sustained user CPU, while steal and iowait remain low; `db2pd -edus` shows several database agents consuming CPU. That supports a CPU-demand hypothesis; identify statements and parallelism before adding cores.',expected:'Diagnosis names the dominant resource and interval; it does not infer a cause from a single counter.',issues:[{symptom:'Load average is high but CPU idle and iowait is elevated.',evidence:'vmstat blocked queue, iostat latency, `db2pd -wlocks`, and `-applications`.',cause:'Tasks are blocked on I/O or locks, not runnable CPU demand.',fix:'Follow the blocked chain to device or transaction evidence and correct that layer.',avoid:'Increasing CPU or agent limits as the first response.'},{symptom:'Db2 process is killed or host swaps during a busy period.',evidence:'kernel journal OOM records, cgroup memory.events, Db2 memory sets, and process RSS.',cause:'Host/cgroup limit or concurrent memory consumers exceed headroom.',fix:'Restore host headroom and isolate the consumer; lower concurrency only with workload-owner agreement.',avoid:'Raising Db2 memory caps above the host/cgroup limit.'}],lab:'Collect a five-interval vmstat sample and two Db2 EDU samples against a disposable database. Label each signal as demand, wait, or capacity. For a safe failure drill, use a CPU-only bounded test process in a container with a low CPU quota; compare guest CPU with throttling counters. Stop the test process and verify normal scheduler values.',question:'Which additional evidence separates CPU saturation from many lock-waiting connections?',answer:'Pair interval CPU/run-queue data with Db2 application/EDU and lock-wait evidence. CPU saturation shows runnable work consuming processor; lock waits show waiting activities and a blocker chain even if host CPU is idle.',diagram:'flowchart LR\nS[Symptom interval] --> O[OS CPU run queue paging cgroup]\nS --> D[Db2 EDU applications transactions]\nD --> W{Runnable or waiting?}\nW -->|Runnable| C[CPU demand path]\nW -->|Waiting| L[Lock I/O or network path]',refs:[['IBM db2pd reference','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-db2pd-monitor-troubleshoot-db2-engine-activities'],['Linux vmstat manual','https://man7.org/linux/man-pages/man8/vmstat.8.html']],related:['A-01','A-04','E-03','E-04'] }),
L({id:'A-04',title:'Storage, filesystems, multipath, capacity, and I/O diagnosis',scope:['device-to-filesystem-to-Db2 path','block and inode capacity','deleted-open-file space','mount flags and ownership','latency throughput queue depth','multipath and storage failure','safe df du lsblk iostat interpretation'],branches:[['No space blocks','Check blocks and inodes independently at the mount point.','A table-space high-water mark is not the same as full filesystem.'],['High latency','Measure device service time and queue depth over the affected interval.','A high I/O rate alone does not prove saturation.'],['Path failure','Inspect multipath and kernel/storage events before failover.','Do not remove a live path or force filesystem repair.']],lifecycle:['Map Db2 path and container to mount and block device.','Check free blocks, inodes, quotas and open-deleted files.','Sample latency and queue depth; check multipath and kernel events.','Determine whether pressure is table space, log, backup or diagnostics.','Add capacity or remediate the failed path under storage ownership; verify.'],precheck:['Capture `df`, `df -i`, mount, device and Db2 container evidence.','Do not run destructive fsck, multipath flush, or device rescan during active I/O without platform owner.','Confirm free capacity on all paths and failure-safe redundancy.'],commands:[P('Capacity and inode check','df -hP /db2data; df -iP /db2data; lsblk -f','Linux host operator','Filesystem hosting Db2 data','Read-only tools; use the actual mount path.','Block, inode, filesystem and device mapping are reported.','Map Db2 containers with `db2pd -db SAMPLE -tablespaces` and confirm exact mount path.','Read-only; do not extend the wrong volume.'),P('Device latency sample','iostat -xz 1 5','Linux host operator','Server storage devices','sysstat installed; capture during the service symptom.','Interval IOPS, throughput, queue and latency fields are emitted.','Compare with the same workload baseline and SAN/cloud metrics; include multipath state.','Read-only; storage path changes require a planned owner-led action.')],example:'`df -h` shows 38% free, but `df -i` shows zero free inodes on the archive-log filesystem. Db2 cannot create the next archive file. Add inode capacity or clean only identified non-Db2 files under retention rules; then force a controlled archive and verify the log path.',expected:'The measured problem is classified as filesystem blocks, inodes, latency, path health, or Db2 tablespace capacity.',issues:[{symptom:'Archive creation fails although `df -h` reports free space.',evidence:'`df -i`, archive destination permissions, mount events, and db2diag archive message.',cause:'Inode exhaustion or unusable mount/permission, rather than block capacity.',fix:'Restore the mount or free approved non-Db2 files; repeat a controlled archive and verify the chain.',avoid:'Deleting active/archive logs outside Db2 retention and recovery procedures.'},{symptom:'Filesystem remains full after a large file is removed.',evidence:'`lsof +L1`, process FD list, and filesystem usage.',cause:'A process still holds a deleted file open.',fix:'Identify owner and rotate/reopen through the supported service procedure; recheck freed blocks.',avoid:'Killing the Db2 process that owns an open log without recovery assessment.'}],lab:'On a disposable filesystem, create a small file and keep it open while unlinking it; observe that `df` and `du` differ, then close the handle and verify free space returns. Do not use Db2 log paths for this drill.',question:'When should `du` and `df` disagree?',answer:'Deleted-but-open files, reserved filesystem blocks, snapshots, or different mount visibility can explain it. Find open deleted files and mount accounting before removing data.',diagram:'flowchart TD\nD[Db2 container or log path] --> M[Mount and filesystem]\nM --> B[Blocks and inodes]\nM --> V[Volume or device]\nV --> P[Multipath and SAN cloud]\nP --> L[Latency throughput queue and errors]',refs:[['IBM table-space monitor','https://www.ibm.com/docs/en/db2/12.1.x?topic=functions-monitor-mon-routines'],['Linux iostat manual','https://man7.org/linux/man-pages/man1/iostat.1.html']],related:['A-02','A-03','C-04','F-01'] }),
L({id:'A-05',title:'Networking, DNS, ports, firewalls, time, and client/server evidence',scope:['forward and reverse DNS','routes, interfaces, firewall and NAT','Db2 listener and service-name/port mapping','TLS trust and hostname validation','timeout versus refusal','keepalive and client/server evidence','clock synchronization'],branches:[['Name resolution','Check resolver output from the same client context as the app.','A successful ping is not a Db2 connection test.'],['Transport port','Compare listener and firewall state on both endpoints.','Refusal suggests reachable host/no listener; timeout may be path filtering.'],['TLS/session','Validate trust, certificate name, expiry and protocol after TCP succeeds.','Do not disable certificate validation to make a connection work.']],lifecycle:['Resolve the hostname and expected endpoint from the application host.','Confirm route/interface and listener/port on server.','Test TCP without credentials, then TLS trust, then authentication and Db2 alias.','Capture paired client and server timestamps and diagnostics.','Fix the earliest failing layer and repeat the complete connection test.'],precheck:['Identify exact client driver and Db2 server levels.','Record server name, resolved IP, service/port and expected TLS mode.','Use a safe test account; never place a password in shell history or traces.'],commands:[P('DNS resolution','getent ahosts db2host.example.net','Client OS operator','Application client resolver','Use the exact hostname configured by the application.','Resolver addresses and address families are returned.','Compare with server-side DNS records and certificate subject/SAN.','Read-only; correct the authoritative DNS record through network owners.'),P('Listener and TCP probe','ss -ltnp; nc -vz db2host.example.net 50000','Server operator, then client operator','Server listening sockets and client route','`ss` runs on server; `nc` runs on client; listener port is lab example.','Server shows bound listener; client probe succeeds or reports refusal/timeout.','Verify service mapping and test Db2 auth only after transport passes.','Read-only; firewall changes require scoped network change.'),P('Clock and certificate window','timedatectl status','Host operator','Client and Db2 server clocks','Read-only; repeat on each endpoint.','NTP synchronization and offset are displayed.','Compare certificate validity dates and incident timestamps in UTC.','No state change; fix NTP through platform management, not manual clock jumps.')],example:'Client resolves the alias to the expected server, but TCP to the configured port times out. Server `ss` has no listener on that port. Check DBM SVCENAME/service resolution and `DB2COMM` before changing firewall rules.',expected:'A tested path identifies DNS, route/firewall, listener, TLS, authentication, catalog alias, or application driver as the earliest failing layer.',issues:[{symptom:'TCP connection is refused immediately.',evidence:'server `ss -ltnp`, service mapping, Db2 instance status and db2diag startup record.',cause:'No listener on the port or service not started/bound.',fix:'Correct the configured service/listener and restart only if the parameter requires it; retest port then Db2.',avoid:'Opening every firewall port.'},{symptom:'TLS client rejects a valid server certificate.',evidence:'client trust chain, certificate SAN/expiry, system time, client driver and TLS trace.',cause:'Trust store/name mismatch or clock skew.',fix:'Install the approved CA chain and connect using the certificate name; recheck TLS handshake.',avoid:'Disabling hostname or certificate validation.'}],lab:'Use a disposable client/server pair. Break one layer at a time: wrong DNS name, closed test port, then untrusted test CA. Record the client result, server evidence, and the smallest fix. Restore original config and prove the successful authenticated connection.',question:'What does a successful TCP probe prove?',answer:'Only that a TCP path to that endpoint/port accepted the probe at that moment. It says nothing about TLS, Db2 cataloging, authentication, authorization, driver compatibility, or application SQL.',diagram:'flowchart LR\nA[Application driver] --> N[DNS and route]\nN --> F[Firewall NAT]\nF --> L[Db2 listener port]\nL --> T[TLS trust and name]\nT --> U[Authentication]\nU --> Z[Database alias authorization]',refs:[['IBM Db2 TCP/IP setup','https://www.ibm.com/docs/en/db2/12.1.x?topic=tcpip-setting-communication-protocols-db2-instance'],['IBM TLS server configuration','https://www.ibm.com/docs/en/db2/12.1?topic=ctcsc-configure-tls-db2-server']],related:['D-03','D-04','D-06','E-01'] })
);

lessons.push(
L({id:'H-01',title:'Baselines, workload measurement, service objectives, and bottleneck isolation',scope:['workload mix and service objective','response time throughput concurrency','known-good baselines and interval','host vs Db2 vs client attribution','CPU I/O lock log network categories','one change at a time and rollback threshold','replay/representative workload'],branches:[['Latency SLO','Track request percentile and tail by transaction class.','Average hides p95/p99 impact.'],['Throughput SLO','Track completed commits/queries at stated concurrency.','A faster single query can reduce total capacity.'],['Diagnostic window','Use consistent duration and workload mix before/after.','Comparisons with different concurrency are not causal.']],lifecycle:['Define transaction class and acceptance target.','Collect known-good workload and resource samples.','Isolate client, network, Db2 and storage waits.','Change one variable or SQL shape under controlled load.','Compare percentiles/throughput/error rate and restore baseline on regression.'],precheck:['Capture SQL/parameter distribution, concurrency and application version.','Record host, member and storage baseline; use same time window.','Set stop criteria before performance experiment.'],commands:[P('Capture interval database metrics','SELECT member, total_cpu_time, total_app_rqsts, rows_read, rows_returned FROM TABLE(mon_get_database(-2)) AS d','Monitor-authorized DBA','SAMPLE members at a point in time','Confirm exact metric names/units on installed level; sample twice for deltas.','Database counters by member are returned.','Compute deltas by elapsed time, align with app p95 and host device samples.','Read-only; no tuning is performed from a single sample.'),P('Measure representative statement','db2batch -d SAMPLE -f /secure/lab/queries.sql -r /secure/lab/run.out','Instance owner/benchmark operator','Disposable database and fixed query file','Use synthetic data, fixed bind values, warm/cold cache protocol and bounded concurrency.','Elapsed times and query output are written to result file.','Compare result correctness, p50/p95, throughput and resource deltas across repetitions.','Stop test if shared resource threshold is reached; restore baseline after any tuning.')],example:'One report’s average latency drops after increasing sort memory, but concurrent OLTP p99 doubles due to memory pressure. Accept only if workload objectives and total resource cost meet the change criterion.',expected:'Performance conclusion includes workload, objective, interval, units, sample size and measurable before/after change.',issues:[{symptom:'Query timing improves only in first run.',evidence:'cache/warmup state, repeated trials, concurrency and statement cache.',cause:'Cache warm-up or compilation excluded from later/first run inconsistently.',fix:'Use consistent repetitions and report warm/cold results separately.',avoid:'Claiming a change based on one run.'},{symptom:'Host CPU looks low but app latency high.',evidence:'wait categories, lock/log/network/client timing, queue delay and storage latency.',cause:'Work blocked outside CPU service time.',fix:'Use end-to-end tracing and isolate waits by layer.',avoid:'Increasing CPU just because query is slow.'}],lab:'Create a fixed synthetic query mix at two concurrency levels. Record throughput, p95 and Db2/OS counters before and after a controlled index or memory experiment. Roll back if any service class breaches its objective.',question:'What makes a before/after benchmark fair?',answer:'Same data, query/parameter distribution, concurrency, cache protocol, time window, endpoint, and measurement units; repeated trials and correctness checks are required.',diagram:'flowchart TD\nS[SLO and workload class] --> B[Known-good baseline]\nB --> W[Locate wait/resource layer]\nW --> C[One controlled change]\nC --> M[Same workload measurement]\nM --> A{SLO improvement without regression?}\nA -->|yes| Accept[Document and monitor]\nA -->|no| Rollback[Restore captured baseline]',refs:[R.mon,['IBM query tuning guidance','https://www.ibm.com/docs/en/db2/12.1.0?topic=design-writing-tuning-queries-optimal-performance']],related:['E-03','E-06','H-02','H-06','I-01'] }),
L({id:'H-02',title:'Compilation, access plans, EXPLAIN tables, db2exfmt, and plan interpretation',scope:['explain table setup and identity','EXPLAIN PLAN FOR and explain special registers','db2exfmt output','access operators joins/sorts/temp/prefetch/parallelism','estimated rows vs observed workload','dynamic/static SQL and package','wrong query/package/plan matching','missing explain tables'],branches:[['EXPLAIN current SQL','Capture potential optimizer plan without executing query.','It does not prove actual runtime rows/timing.'],['Package explain','Inspect bound static package/section and binder identity.','Dynamic explain of a similar statement may not match package plan.'],['Runtime observation','Correlate plan with actual activity/metrics.','Explain cost is an estimate, not elapsed time.']],lifecycle:['Identify exact statement text, package/section, parameter class and current schema.','Create explain tables under correct authorization identity.','Capture plan and format with db2exfmt.','Read cardinality, access, join, sort, spill and parallelism.','Compare estimates with actual metrics and keep plan identifier with benchmark.'],precheck:['Confirm explain tables exist in the current user/schema or SYSTOOLS.','Record query tag/queryno and statement/package identifier.','Protect SQL text if it includes sensitive literals.'],commands:[P('Capture a dynamic plan','EXPLAIN PLAN FOR SELECT order_id, total FROM APP.ORDERS WHERE customer_id = 7012;','Explain authority/user with required privileges','Current SAMPLE connection','EXPLAIN stores optimizer information but does not execute statement; explain tables must exist.','Plan rows are written to explain tables.','Run `db2exfmt -d SAMPLE -1 -o /tmp/orders.plan`; confirm exact statement/queryno and estimates.','Drop only lab explain tables after storing intended plan evidence.'),P('Format latest explain instance','db2exfmt -d SAMPLE -1 -o /tmp/orders.plan -w -1','Instance owner/DBA','Explain tables in SAMPLE and current explain requester','Exact options should be checked against installed db2exfmt help; output file private.','Plan is formatted with operators, estimates and object names.','Inspect table/index stats and compare rows/elapsed with a workload run.','No database change beyond explain rows; retain/clean output according to privacy rules.')],example:'Plan shows a table scan estimated at 10 rows but measured table contains millions. Check statistics and predicate type/parameter marker before creating an index. An explain plan alone does not prove the table scan is the slow stage.',expected:'The exact statement/package plan is interpreted alongside stats, runtime rows, waits and actual duration.',issues:[{symptom:'EXPLAIN fails because explain tables are absent.',evidence:'current schema, SYSCAT.EXPLAIN tables and SQLSTATE.',cause:'Explain objects were not created for this identity/database.',fix:'Run supported EXPLAIN table creation procedure for the intended schema and retry.',avoid:'Granting DBADM to plan reviewers.'},{symptom:'Formatted plan is for a different statement or parameter value.',evidence:'QUERYNO/QUERYTAG, statement text, package section and explain timestamp.',cause:'Matching by “latest plan” alone is ambiguous or plan was captured under different context.',fix:'Tag/capture correct statement and parameter environment; explain package section if static.',avoid:'Tuning from a plan with mismatched SQL.'}],lab:'Explain a selective lookup and a broad scan on synthetic APP.ORDERS. Compare estimated rows, joins and index use; alter statistics in a disposable schema and observe plan changes. Cleanup explain rows after saving relevant plan text.',question:'What is the difference between an EXPLAIN plan and execution evidence?',answer:'EXPLAIN records the chosen estimated access strategy without running the query. Runtime evidence shows actual time, rows, waits and resource usage.',diagram:'flowchart LR\nQ[Exact SQL package section parameters] --> E[EXPLAIN tables]\nE --> F[db2exfmt operators estimates]\nF --> S[Statistics and cardinality]\nQ --> R[Runtime metrics rows waits]\nS --> D[Decision and measured plan change]\nR --> D',refs:[['IBM EXPLAIN statement','https://www.ibm.com/docs/en/db2/12.1.x?topic=statements-explain'],['IBM Explain facility','https://www.ibm.com/docs/en/db2/12.1.x?topic=optimization-explain-facility'],['IBM db2exfmt command','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-db2exfmt'],R.mon],related:['H-01','H-03','H-04','C-03'] }),
L({id:'H-03',title:'Statistics, cardinality, skew, parameter markers, optimizer choices, and rebind',scope:['RUNSTATS scope and profiles','distribution/column-group/statistical-view stats','skew and correlation','parameter marker estimates and REOPT NONE/ONCE/ALWAYS','BIND/REBIND package choice','dynamic statement/package cache','plan stability and regression','statistics/rebind rollback limits'],branches:[['Statistics refresh','Use after data distribution/volume changes.','Statistics can be stale at table, index, column or group level.'],['REOPT NONE/ONCE/ALWAYS','Choose based on parameter sensitivity and compile cost.','REOPT can change plans and per-execution CPU.'],['REBIND','Use for identified package after stats/schema/change.','It may block on in-use package and change static plan.']],lifecycle:['Inspect current stats timestamps/cardinality and query estimates.','Collect needed table/index/distribution/column-group statistics.','Explain representative skewed and common parameter values.','Choose REOPT/package rebind only for identified statements.','Measure each parameter class and preserve prior plan/perf evidence.'],precheck:['Record RUNSTATS profile, package options, SQL text and common/rare bind values.','Identify dependent apps and package use; plan rebind lock window.','Do not run full catalog statistics solely to fix one query without evidence.'],commands:[P('Collect skew-aware statistics','RUNSTATS ON TABLE APP.ORDERS WITH DISTRIBUTION ON COLUMNS (REGION, STATUS) AND DETAILED INDEXES ALL','DBA/table control authority','APP.ORDERS and relevant indexes','Choose columns from workload predicates; schedule utility resource window.','Catalog histograms/index stats refreshed.','Check stats timestamps and compare estimated cardinality for common/rare values.','Statistics update is not automatically reverted; restore data/profile and rerun if a tested what-if rollback is needed.'),P('Rebind a specific static package','REBIND PACKAGE APP.ORDERQ REOPT ONCE','Package BIND privilege/DBA','APP.ORDERQ package and version','Capture current plan/performance; verify package identity and parameter sensitivity.','Package is recreated using selected reoptimization semantics.','Check SYSCAT.PACKAGES validity/options, explain package section and run application test for common/rare binds.','REBIND with prior options and preserve plan test; package change is not data rollback.')],example:'A parameterized query is fast for region WEST and slow for region EAST because distributions differ sharply. Gather distribution stats and compare REOPT NONE with ONCE/ALWAYS using both binds; a single value cannot represent workload mix.',expected:'Statistics support estimated cardinality, and package reoptimization choice is tied to measured parameter classes and compile/resource tradeoff.',issues:[{symptom:'RUNSTATS completes but plan still estimates uniformly.',evidence:'column group/distribution stats, statistics profile, EXPLAIN and predicate correlation.',cause:'Relevant skew/correlation not captured or query form prevents estimate use.',fix:'Collect targeted distribution/column-group stats and verify query expression/cardinality.',avoid:'Running broad RUNSTATS repeatedly without checking collected columns.'},{symptom:'REBIND improves one bind but regresses others.',evidence:'REOPT choice, bind distribution, execution latency and package cache observations.',cause:'Parameter-sensitive predicates and one plan no longer suit all values.',fix:'Evaluate REOPT options or application strategy under realistic mix; roll back prior options if needed.',avoid:'Global REBIND ALL on a production fleet.'}],lab:'Create skewed synthetic statuses, run baseline explain with representative values, collect distribution stats, and compare estimates. Rebind one lab package with REOPT NONE/ONCE, measure compilation and execution. Cleanup package/test data.',question:'What does REOPT ALWAYS trade?',answer:'It can use current parameter values to choose more appropriate plans but adds compile/reoptimization cost on executions; measure both CPU and response tail.',diagram:'flowchart TD\nD[Table data distribution] --> S[RUNSTATS column index group stats]\nS --> C[Optimizer cardinality estimate]\nP[Parameter marker values] --> R[REOPT NONE ONCE ALWAYS]\nC --> A[Access plan]\nR --> A\nA --> M[Measure representative bind classes]\nM --> B[REBIND or restore options]',refs:[R.runstats,['IBM REBIND command','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-rebind'],['IBM access plan optimization','https://www.ibm.com/docs/en/db2/12.1.x?topic=optimization-optimizing-access-plans'],['IBM query tuning guidance','https://www.ibm.com/docs/en/db2/12.1.0?topic=design-writing-tuning-queries-optimal-performance']],related:['C-06','H-01','H-02','H-04'] }),
L({id:'H-04',title:'Index and query design, read/write costs, and measured plan changes',scope:['predicate/join/order shape','composite key order','unique/covering/include/clustered index supported options','index-only access and table fetch','partitioned/XML indexes','redundant indexes and write cost','SQL rewrite/type compatibility','index creation/rebuild and workload measurement'],branches:[['Composite B-tree','Choose key order from selective predicates and joins.','One wide index can increase storage and DML cost.'],['Covering index','Use when it removes costly table fetches for valuable query.','Include columns increase page size and write maintenance.'],['Rewrite SQL','Fix non-sargable predicates/type mismatch/unneeded joins first.','A rewrite must preserve NULL, duplicate and transactional semantics.']],lifecycle:['Collect exact query and workload frequency.','Review EXPLAIN estimates, predicate types, stats and existing indexes.','Design one candidate key/order/include.','Build in a lab or approved online utility/window.','Replay representative read/write mix and retain or remove with measured criteria.'],precheck:['List index definitions, clustering and usage stats.','Calculate storage and DML/log/reorg/backup impact.','Confirm exact 12.1 syntax/support for index type and table organization.'],commands:[P('Candidate composite index','CREATE INDEX APP.IX_ORDERS_REGION_DATE ON APP.ORDERS (region, created_at DESC) INCLUDE (order_id, total);','Schema owner/authorized DBA','APP.ORDERS synthetic workload','Candidate syntax and INCLUDE support checked for target table/release; plan space and utility impact.','Index is created and cataloged.','Explain the target query and compare read count/latency plus insert/update throughput.','Drop the candidate index if measured workload regresses; do not drop existing production index without dependency review.'),P('Sargable date predicate','SELECT order_id, total FROM APP.ORDERS WHERE created_at >= TIMESTAMP(\'2026-10-01-00.00.00\') AND created_at < TIMESTAMP(\'2026-11-01-00.00.00\')','Application developer/DBA','APP.ORDERS','Use typed boundary values and inclusive-start/exclusive-end semantics; compare with function-on-column form.','Rows for October are returned without applying a function to every key.','EXPLAIN and benchmark both SQL forms; verify result equality including timestamp precision.','Read-only; no DDL change unless plan evidence shows index is needed.')],example:'An index on `(region, created_at)` can support a query filtering by region and time, but may not serve a date-only query as effectively. Measure query mix and write amplification rather than “indexing every predicate.”',expected:'SQL result remains equivalent and the complete workload improves within storage/maintenance budget.',issues:[{symptom:'Index added but query still scans table.',evidence:'EXPLAIN predicate matching, data types, statistics, leading key and selectivity.',cause:'Non-sargable expression/type mismatch or optimizer cost says scan cheaper.',fix:'Rewrite predicate or collect stats; compare one alternative key in replay.',avoid:'Forcing access path before checking semantics and estimates.'},{symptom:'Read query improves while batch writes slow down.',evidence:'insert/update latency, log bytes, index pages, reorg and CPU.',cause:'Additional index maintenance cost outweighs read gain.',fix:'Keep only indexes justified by total service objectives; remove candidate with dependency check.',avoid:'Measuring only the targeted SELECT.'}],lab:'Build APP.ORDERS with existing primary key, compare date-only and region/date query plans, create one candidate index and replay mixed reads/inserts. Remove only lab index/table after results recorded.',question:'Why does the leading column matter in a composite index?',answer:'The index is ordered first by its leading key; predicates that constrain that prefix can navigate it efficiently. A later-column-only predicate may not get the same access.',diagram:'flowchart TD\nQ[Predicate join order and result columns] --> S[SQL shape and type compatibility]\nS --> P[Selectivity and statistics]\nP --> I[Candidate key order and coverage]\nI --> E[EXPLAIN and table fetches]\nE --> M[Read write storage replay]\nM --> D[Keep or drop candidate]',refs:[['IBM index design','https://www.ibm.com/docs/en/db2/12.1.x?topic=design-designing-indexes'],['IBM query tuning guidance','https://www.ibm.com/docs/en/db2/12.1.0?topic=design-writing-tuning-queries-optimal-performance'],R.reorg],related:['C-02','H-01','H-02','H-03'] }),
L({id:'H-05',title:'Locks, deadlocks, isolation, transaction design, and safe intervention',scope:['lock modes/conversions and escalation','deadlock versus timeout','wait-for graph/root blocker','deadlock/lock-wait event data','transaction length and commit frequency','lock timeout/escalation configuration','cancel/force rollback cost','SQL0911N reason interpretation','correctness tests'],branches:[['Wait','A transaction awaits incompatible lock.','Find owner/root blocker before canceling waiter.'],['Deadlock','Wait-for cycle; Db2 chooses a victim and rolls it back.','Not the same as a long wait timeout.'],['Timeout/escalation','Wait limit or lock-list pressure changes behavior/scope.','Increasing timeout can worsen queues; raising lock list can consume memory.']],lifecycle:['Identify SQL0911N reason and application handle.','Inspect lock wait, owner, UOW age and transaction boundaries.','Capture lock event details if current evidence is insufficient.','Coordinate cancel/commit/rollback/force with owner.','Validate rollback, released locks, application consistency and retry outcome.'],precheck:['Use db2pd -wlocks/-transactions and MON_GET_APPL_LOCKWAIT.','Check whether blocker is a batch or user transaction and its log usage.','Before LOCKTIMEOUT/lock-list change, estimate queue impact and test.'],commands:[P('Inspect current wait graph','db2pd -db SAMPLE -wlocks -transactions; SELECT agent_id, lock_name, lock_wait_start_time FROM TABLE(mon_get_appl_lockwait(NULL,-2)) AS w','Instance owner/monitor user','SAMPLE active member','Read-only; correlate waiter to owner and application handle.','Lock wait rows or no-wait result are returned with current timestamps.','Capture deadlock/lock event monitor and current transaction before intervention.','Read-only; no FORCE APPLICATION yet.'),P('Set bounded lock wait timeout in lab','UPDATE DATABASE CONFIGURATION FOR SAMPLE USING LOCKTIMEOUT 30','DBA configuration authority','Disposable database SAMPLE','Parameter online behavior and application retry contract reviewed; capture previous value.','Future lock waits time out after configured interval when active.','GET DB CFG and induce a bounded lab conflict; verify SQL0911N reason and app retry behavior.','Restore captured value and verify; rollback cannot restore already failed transactions.')],example:'Two sessions lock rows in opposite order. Db2 detects a deadlock cycle and returns SQL0911N to one transaction; a separate long wait may time out later. Fix transaction lock ordering and short UOWs rather than simply raising timeout.',expected:'Root blocker/cycle is identified, response is specific to deadlock or timeout, and transaction/business outcomes are verified.',issues:[{symptom:'SQL0911N reason code reports deadlock victim.',evidence:'lock event, participants, statement order and transaction boundary.',cause:'Opposite lock acquisition order creates cycle.',fix:'Apply consistent lock ordering or reduce UOW scope, then verify no deadlock under concurrency.',avoid:'Retrying just the final statement without re-evaluating transaction outcome.'},{symptom:'Timeout count increases after raising LOCKTIMEOUT.',evidence:'wait queue length, arrival rate, blocker duration and service latency.',cause:'Longer wait retains more queued work and memory/agents.',fix:'Resolve root blocker and restore service-aware timeout; enforce app transaction limits.',avoid:'Setting timeout infinite to suppress SQL0911N.'}],lab:'Open two disposable sessions, acquire row locks in opposing order, create a deadlock, capture event output and identify victim. Separate run: create a lock wait and time out. Verify rollback and no lingering locks; cleanup test rows.',question:'Why might forcing a blocker be more harmful than canceling a waiter?',answer:'A blocker can have a large uncommitted unit of work whose rollback consumes log/I/O time and affects many waiters; identify owner, business state and rollback cost first.',diagram:'flowchart TD\nW[Waiter receives SQL0911N or waits] --> G[Lock graph and UOW age]\nG --> C{Cycle or single blocker?}\nC -->|cycle| D[Deadlock victim and ordering fix]\nC -->|wait| B[Root blocker and owner]\nB --> I{Safe cancel approved?}\nI -->|yes| X[Targeted cancel or force]\nX --> R[Rollback locks and app outcome]',refs:[R.locks,R.mon,['IBM lock timeout parameter','https://www.ibm.com/docs/en/db2/12.1.x?topic=parameters-locktimeout-lock-timeout'],['IBM FORCE APPLICATION command','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-force-application']],related:['C-01','E-04','E-05','K-01'] }),
L({id:'H-06',title:'Bufferpools, sort, package cache, memory pressure, and competing consumers',scope:['bufferpool logical/physical reads and page size','sort heap/temp spill','package cache hits/evictions/compile','lock list and statement memory','STMM and database memory','db2pd memory sets','host paging/NUMA/cgroup','parameter scope/change class','avoid starving another consumer'],branches:[['Bufferpool','Tune repeated physical reads for matched page size/table space.','Very large pool can starve sort/agents/OS.'],['Sort/package cache','Use spill/cache evidence and statement compilation metrics.','A cache hit ratio alone does not prove service improvement.'],['STMM/overall memory','Let supported automatic tuning balance eligible consumers.','Fixed component caps and host/cgroup limits still constrain engine.']],lifecycle:['Collect host memory and Db2 memory-set baseline.','Map table spaces/bufferpools and identify query spill/cache metrics.','Determine automatic/manual parameter and propagation class.','Change one consumer within host headroom and test competing workloads.','Revert or adjust if paging, tail latency or another component regresses.'],precheck:['Read GET DB CFG SHOW DETAIL and `db2pd -db SAMPLE -memsets`.','Check page sizes, bufferpool mapping and temporary table spaces.','Set maximum memory budget including OS, filesystem cache and non-Db2 process.'],commands:[P('Inspect memory sets','db2pd -db SAMPLE -memsets; db2pd -db SAMPLE -bufferpools','Instance owner','SAMPLE active database and local member','Read-only; check options on current release/topology.','Memory component and bufferpool state are displayed.','Compare to MON_GET_BUFFERPOOL, sort activity and OS paging/cgroup over interval.','Read-only.'),P('Change one lab consumer','UPDATE DATABASE CONFIGURATION FOR SAMPLE USING sortheap 4096','DBA config authority','Disposable SAMPLE database','Only after spill evidence; check unit/page semantics, online class, database memory and host headroom.','Sort heap configured; current/deferred value may differ by parameter class.','GET DB CFG SHOW DETAIL; replay sort and competing OLTP workload, measure spill and memory.','Restore previous value; if parameter applies on reactivate, schedule safely and verify effective value.')],example:'A sort spills to temporary tablespace. Raising SORTHEAP may reduce spill but multiply memory per concurrent sort; compare overall database memory and concurrency. If host begins swapping, revert rather than tune package cache concurrently.',expected:'A single memory consumer is tied to measured pressure and tested without starving Db2 or host neighbors.',issues:[{symptom:'Bufferpool hit ratio improves but end-to-end latency worsens.',evidence:'physical reads, CPU, page cleaner, memory-set pressure, paging and query p95.',cause:'Larger pool uses memory needed by other components or misses are not bottleneck.',fix:'Return to tested size and identify actual wait/cost component.',avoid:'Optimizing a ratio without service-level measurement.'},{symptom:'Sort memory increase causes paging or OOM.',evidence:'concurrent sorts, sort heap, database memory, cgroup usage and OOM logs.',cause:'Per-activity allocation multiplied by concurrency beyond host budget.',fix:'Restore old parameter/limit concurrency while protecting recovery headroom.',avoid:'Setting every heap to maximum.'}],lab:'Run a sort-heavy lab query at two concurrency levels. Capture sort spill, memory sets, host paging and temporary space. Change only SORTHEAP; compare all metrics and rollback.',question:'Why can a low physical-read ratio coexist with slow SQL?',answer:'CPU, lock, network, sort, compile or logging waits may dominate. Bufferpool metrics need to be interpreted with end-to-end activity time.',diagram:'flowchart TD\nH[Host and cgroup memory budget] --> D[Db2 database memory]\nD --> B[Bufferpools]\nD --> S[Sort and statement memory]\nD --> P[Package cache and locks]\nB --> C[Competing consumers]\nS --> C\nP --> C\nC --> R[Paging pressure and service latency]',refs:[R.config,R.mon,['IBM bufferpool monitor function','https://www.ibm.com/docs/en/db2/12.1.x?topic=routines-mon-get-bufferpool']],related:['B-05','E-03','H-01','H-07'] }),
L({id:'H-07',title:'Workload management, I/O, utility contention, and maintenance tuning',scope:['workload/service/work class/work action/threshold lifecycle','admission control and concurrency','WLM collection and threshold effects','utility throttling/contention','I/O path/latency/queue depth/prefetch','maintenance window and priority','queueing versus device saturation'],branches:[['WLM routing','Map app/user/work type to service class and resources.','Test classification with actual client attributes.'],['Admission/threshold','Protect service by limiting concurrency or detecting runaway work.','Threshold action can cancel/collect and affect workloads.'],['I/O and utility','Measure device queue/latency and utility resource use.','A slower utility may be caused by contention, not utility setting.']],lifecycle:['Classify workloads and service objectives.','Measure queueing and resource saturation by class and device.','Design WLM object hierarchy and utility maintenance window.','Test work-class mapping and threshold on lab workload.','Observe queue/latency and rebalance maintenance priorities.'],precheck:['Inventory existing WLM objects and monitor collection.','Check if app attributes reliably distinguish workload.','Record I/O baseline and utility impact; ensure backup/REORG windows do not collide.'],commands:[P('Create workload mapping example','CREATE SERVICE CLASS REPORTS_SC; CREATE WORKLOAD REPORTS_WL SESSION_USER (\'REPORTS\') SERVICE CLASS REPORTS_SC','WLMADM or DBADM','Disposable database and service class REPORTS_SC','Create service class before workload; validate exact syntax and role mapping in lab.','REPORTS session identity maps to service class.','Query MON_GET_WORKLOAD/MON_GET_SERVICE_SUBCLASS to verify app classification and resource metrics.','Drop workload then service class only after lab sessions disconnect.'),P('Measure device and utility impact','iostat -xz 1 5; LIST UTILITIES SHOW DETAIL','Linux host operator and Db2 instance owner','Storage device plus current database utilities','Align interval; read-only collection; identify device/container mapping.','Device latency/queue and Db2 utility phase are visible.','Compare with baseline and service latency; change utility priority only in controlled window.','Stop/reschedule utility only through its supported pause/resume/terminate lifecycle.')],example:'A RUNSTATS utility overlaps a latency-sensitive checkout service. WLM may control query work but cannot fix a saturated disk. Compare checkout class wait/latency, device queue and utility phase; shift maintenance window or throttle only after bottleneck evidence.',expected:'User workload, utility and storage queues are separated; WLM classification and action are verified with monitoring.',issues:[{symptom:'All work lands in default service subclass.',evidence:'client attributes, workload definition, priority/sequence and `MON_GET_WORKLOAD`.',cause:'Classifier does not match real application identity/connection attributes.',fix:'Correct narrow workload predicate and test with actual application driver.',avoid:'Creating more service classes without classification evidence.'},{symptom:'Utility slows but user latency remains high.',evidence:'device latency, queue depth, utility progress/phase and tablespace path.',cause:'Storage saturation or utility competing for shared device.',fix:'Reschedule/throttle utility or isolate storage after storage-owner review.',avoid:'Changing WLM threshold to cancel user work without business approval.'}],lab:'Create one service class and a workload for synthetic reporting identity. Verify classification; run a low-volume maintenance utility and inspect device/Db2 metrics. Do not tune thresholds under actual service load.',question:'Can WLM fix storage saturation?',answer:'WLM can route/admit/control eligible work but does not add device capacity. Identify I/O queue/latency and utility sharing before choosing workload controls.',diagram:'flowchart TD\nI[Application identity] --> W[Workload classifier]\nW --> S[Service class and work class]\nS --> A[Work action threshold admission]\nM[Maintenance utility] --> D[Shared storage device]\nA --> D\nD --> Q[Queue latency and SLO impact]\nQ --> T[Schedule throttle or capacity decision]',refs:[['IBM workload service classes','https://www.ibm.com/docs/en/db2/12.1.x?topic=environment-using-workload-types-simplify-service-class-creation'],['IBM work action sets','https://www.ibm.com/docs/en/db2/12.1.0?topic=sets-creating-work-action'],R.mon,['Linux iostat manual','https://man7.org/linux/man-pages/man1/iostat.1.html']],related:['C-06','E-06','H-01','H-06','J-05'] })
);

lessons.push(
L({id:'G-01',title:'HA versus DR versus backup, failure domains, and service restoration objectives',scope:['HA local service continuity','DR site/region recovery','backup for point-in-time and corruption','host storage network site dependency graph','RPO/RTO and service restoration','fencing/split-brain','client entry points','failure matrix and test evidence'],branches:[['HA','Automate or shorten recovery from component/local failures.','Does not protect against all logical corruption or regional loss.'],['DR','Recover service/data at alternate site or failure domain.','A standby with shared dependencies may not survive site loss.'],['Backup','Return to historical recovery point after corruption/deletion.','A copy is not a DR service endpoint without restore, keys and routing.']],lifecycle:['Identify business service and data-loss/recovery objectives.','Map independent failure domains and shared dependencies.','Select HADR/cluster/backup/client routing layers.','Test host, storage, network, site and logical-error scenarios.','Measure restore-to-service time and revise design.'],precheck:['Name source and alternate domains; verify power, identity, DNS and storage independence.','Include application tier, secrets, firewall, certificates and external services.','Agree RPO/RTO and acceptable consistency point with business owner.'],commands:[P('Topology evidence inventory','db2pd -db SAMPLE -hadr; db2pd -db SAMPLE -members; db2 list history backup all for SAMPLE','DBA/architect','SAMPLE primary/standby and backup history','Use only the relevant topology option; inventory is read-only.','HADR role/state, member view and backup history appear.','Map each host/storage/network/client entry point and backup copy to failure domain.','No state change; architecture action requires a reviewed change.'),P('Failure objective worksheet','RPO = incident time minus latest recoverable commit\nRTO = detect + decide + recover + validate + route','Service owner and DBA','Named critical service','The symbols are planning measures, not Db2 commands; record evidence timestamps.','Each scenario has a measurable target.','Run a failover and restore exercise; compare actual data loss and service-ready time.','If targets fail, adjust architecture and repeat controlled exercise.')],example:'HADR can restore an online database after a host loss, but if primary and standby share the same storage fabric or DNS dependency, the single failure can take both offline. A backup in another region handles other scenarios but has restore RTO.',expected:'Failure matrix shows which control handles each event, what it cannot protect against and measured RPO/RTO.',issues:[{symptom:'HADR peer is healthy but both sites lose service during network/storage outage.',evidence:'dependency map, common network/fabric/DNS and backup copy location.',cause:'Failure domains were assumed independent but share critical dependencies.',fix:'Separate/duplicate dependencies and test isolation/fencing at alternate site.',avoid:'Counting two databases as resilience without topology evidence.'},{symptom:'DR test passes database takeover but app remains down.',evidence:'DNS/VIP/client reroute, certificates, secrets, firewall, pools and external service state.',cause:'Database role recovery was mistaken for full service restoration.',fix:'Include app routing and end-user transaction in acceptance test.',avoid:'Stopping the stopwatch when `TAKEOVER` returns.'}],lab:'Create a failure matrix for host, disk, site, logical delete and key-manager outage. Map each to HADR, backup, service routing and data validation. Tabletop a DR takeover and time every stage.',question:'Why can neither HADR nor backup alone satisfy every resilience need?',answer:'HADR maintains a standby data stream and quick role transition, while backup provides historical recovery points; they have different failure coverage and do not automatically restore application routing or prevent logical errors.',diagram:'flowchart TD\nF[Failure class] --> H[Host or component HA]\nF --> D[Site or region DR]\nF --> C[Logical corruption or deletion]\nH --> R[HADR cluster routing]\nD --> R\nC --> B[Backup restore and PIT]\nR --> V[App and data verification]\nB --> V',refs:[['IBM HADR overview','https://www.ibm.com/docs/en/db2/12.1.x?topic=server-high-availability-disaster-recovery-hadr'],R.backup,R.takeover],related:['F-02','G-02','G-03','G-06','I-06','K-03'] }),
L({id:'G-02',title:'HADR roles, states, synchronization modes, queues, and guarantees',scope:['primary/principal/auxiliary standby roles','LOCAL/REMOTE catchup, PEER and disconnected states','SYNC/NEARSYNC/ASYNC/SUPERASYNC guarantees','peer window and timeout','send/receive/replay positions and queues','log spooling and delayed replay','multiple standbys and reads on standby','member/state scope'],branches:[['SYNC','Wait for standby disk acknowledgement before log write succeeds.','Network latency can affect commit response; failover safety still needs fencing.'],['NEARSYNC','Wait for standby receive to memory, not disk persistence.','Standby crash timing matters.'],['ASYNC','Primary does not wait for acknowledgement.','Transactions can be lost at failover.'],['SUPERASYNC','Primary does not wait; HADR never enters peer/disconnected peer.','Highest data-loss exposure, shortest commit wait.']],lifecycle:['Initialize primary and standby from compatible image.','Set local/remote host/service/instance and synchronization parameters.','Start standby then primary and observe catchup to peer/disconnected state as configured.','Monitor log generation, send/receive/replay positions and queue sizes.','Act only on role and state with commit-loss guarantee understood.'],precheck:['Verify log chain, unique hosts/ports, target list and compatible release.','Read actual configured/effective mode from `db2pd -hadr`/MON_GET_HADR.','Confirm peer-window restrictions by mode and topology.'],commands:[P('Observe HADR roles and queues','db2pd -db SAMPLE -hadr; SELECT hadr_role, hadr_state, hadr_syncmode, log_gap, standby_log_receive_queue_size, standby_log_replay_queue_size FROM TABLE(mon_get_hadr(NULL)) AS h','Instance owner/monitor user','Primary and selected standby member','Use current exact output columns and one-member/pureScale scope; query from primary for standbys.','Role, state, synchronization mode and send/receive/replay lag are shown.','Compare primary log position with standby receive/replay position and queue trend across time.','Read-only; a single state label is not takeover approval.'),P('Start HADR in correct order','START HADR ON DB SAMPLE AS STANDBY; START HADR ON DB SAMPLE AS PRIMARY','HADR administrator','One standby then its primary database','HADR config and restore/image baseline complete; execute each on its correct host.','Standby starts awaiting primary; primary starts connecting/shipping logs.','Check `db2pd -hadr` role/state on both sides until expected state and queue behavior.','STOP HADR is not a generic retry; use only after understanding database shutdown/state consequences.')],example:'PEER with SYNC and stable zero receive queue gives strong commit protection under documented conditions; a growing replay queue still signals standby disk/CPU workload risk. In ASYNC a connected state does not mean every primary commit reached standby.',expected:'State, mode, roles, queue trends and failover loss guarantees are recorded per member/standby.',issues:[{symptom:'Standby remains in REMOTE_CATCHUP.',evidence:'send/receive/replay positions, archive fetch, network throughput and log generation.',cause:'Standby is behind and transport or replay cannot catch up to generation rate.',fix:'Find whether sender/network/receiver/replay is limiting; reduce workload or improve bottleneck, then trend queues.',avoid:'Taking over based solely on a connected/catchup state.'},{symptom:'HADR mode or peer window cannot be configured as requested.',evidence:'DB CFG, mode compatibility and `db2pd -hadr` actual state.',cause:'Mode/peer-window combination unsupported or parameters not loaded until START HADR.','fix':'Choose documented mode/objective combination; apply and restart HADR through planned path.',avoid:'Assuming configured parameter equals active runtime value.'}],lab:'Build a state table from fictional HADR samples covering LOCAL_CATCHUP, REMOTE_CATCHUP, PEER, DISCONNECTED_PEER and DISCONNECTED. For each mode, list what a commit acknowledgement means and what can be lost. No HADR pair is available here.',question:'Why do send, receive and replay queues need separate interpretation?',answer:'Send delay indicates primary shipping; receive queue indicates standby has logs not yet replayed; replay lag indicates standby apply capacity. Different fixes target network, buffering or standby CPU/I/O.',diagram:'flowchart LR\nP[Primary log generation] --> S[Send queue and transport]\nS --> R[Standby receive position]\nR --> Q[Receive spool/queue]\nQ --> L[Replay engine and disk]\nL --> C[Replay position and consistency]\nP -. mode acknowledgement .-> C',refs:[R.hadr,['IBM HADR synchronization modes','https://www.ibm.com/docs/en/db2/12.1.x?topic=parameters-hadr-syncmode-high-availability-disaster-recovery-synchronization-mode'],R.takeover,R.reorgMon],related:['G-01','G-03','G-04','D-04','E-03'] }),
L({id:'G-03',title:'HADR setup, planned takeover, forced takeover gates, reintegration, and failback',scope:['HADR init/backup restore and parameter setup','start/stop primary and standby','planned takeover','forced takeover gates and fencing','role/client reroute verification','old primary reintegration eligibility','reinitialize after divergent log streams','cluster manager/manual control','failback and app/data proof'],branches:[['Planned takeover','Use while both databases communicate and are synchronized.','Do not call a planned takeover during unexplained lag.'],['Forced takeover','Emergency action only after primary is fenced/known stopped.','Possible data loss and split-brain if old primary remains writable.'],['Reintegration','Restart old primary as standby if logs have not diverged.','If reintegration fails due divergence, reinitialize from new primary.']],lifecycle:['Confirm pair and cluster manager status; compare log positions.','For planned: run takeover on current standby and observe role transition.','For forced: fence old primary, record last durable receive point and owner’s data-loss decision.','Verify new primary role, DB accessibility, application route and data.','Reintegrate old primary as standby or reinitialize; plan failback separately.'],precheck:['Confirm primary/standby identities, sync mode, peer state/lag and client route.','Disable/coordinate independent fault monitors or cluster automation as documented.','Obtain incident/change authorization and record RPO exposure before BY FORCE.'],commands:[P('Planned takeover','TAKEOVER HADR ON DB SAMPLE','HADR administrator','Current synchronized standby','Both sides healthy and in peer or allowed state; agree application drain and route action.','Standby becomes primary after orderly transition; existing connections may be interrupted.','Use db2pd -hadr on both hosts, check new role, client alias/reroute and test committed data.','Planned role change can be reversed only through a second planned takeover after pair is healthy.'),P('Forced takeover after fencing','TAKEOVER HADR ON DB SAMPLE BY FORCE','HADR administrator on standby','Standby database only','Old primary host/database confirmed stopped or fenced from clients and peers; business accepts potential lost commits.','Standby takes primary role and opens for connections after replaying received logs.','Verify one primary only, role/state, last received log, client route and application data/transaction reconciliation.','Forced takeover cannot be rolled back by command; do not restart old primary as primary. Reintegration or reinitialization is next.'),P('Old primary reintegration','START HADR ON DB SAMPLE AS STANDBY','HADR administrator on old primary host','Former primary, now to be standby','Only if log streams did not diverge and new primary target list includes former primary.','Former primary joins as standby and catches up.','Check connected state and peer/remote catchup; verify no duplicate primary.','If reintegration fails from divergence, stop and reinitialize from a fresh new-primary backup; do not force old database into pair.')],example:'Planned takeover proceeds while both sides are connected and synchronized. Forced takeover follows a different gate: fence the former primary first, record standby receive/replay point, accept potential loss, then take over and verify one writable primary before routing clients.',expected:'One primary is writable, app points to it, data-loss gap is documented, and former primary is either a healthy standby or deliberately reinitialized.',issues:[{symptom:'Both sites appear to accept writes after forced takeover.',evidence:'cluster manager, host fencing, HADR role on each host and application routes.',cause:'Old primary was not fully disabled or fault monitor restarted it.',fix:'Fence/isolate the old primary immediately; preserve both data sets and follow split-brain recovery with IBM/support.',avoid:'Merging divergent database files or restarting one as primary.'},{symptom:'Old primary cannot reintegrate.',evidence:'db2diag consistency/LSN messages and new-primary log chain.',cause:'Log streams diverged; automatic reintegration impossible.',fix:'Reinitialize old primary as standby from a fresh backup of current primary.',avoid:'Repeated START HADR or issuing BY FORCE on old primary.'}],lab:'Tabletop planned takeover with zero loss and forced takeover after three different sync modes. In the forced case, identify fencing evidence, possible gap and owner acceptance. Follow old-primary reintegration/reinitialize branches. Do not execute failover without a disposable pair.',question:'What is the minimum safe gate before `TAKEOVER ... BY FORCE`?',answer:'Positive evidence that the former primary cannot write/serve clients (fenced), correct standby target/state and data-gap review, plus explicit incident decision accepting possible loss.',diagram:'flowchart TD\nS[Verify pair and role] --> P{Both healthy and synchronized?}\nP -->|yes planned| T[TAKEOVER planned]\nP -->|no emergency| F[Fence old primary and accept gap]\nF --> X[TAKEOVER BY FORCE on standby]\nT --> V[Verify one primary and app route]\nX --> V\nV --> R{Old primary log streams align?}\nR -->|yes| I[Reintegrate as standby]\nR -->|no| N[Reinitialize from new primary]\nI --> B[Plan failback]\nN --> B',refs:[R.takeover,['IBM HADR failover procedure','https://www.ibm.com/docs/en/db2/12.1.x?topic=outage-performing-hadr-failover-operation'],R.hadr,['IBM cluster managers and HADR','https://www.ibm.com/docs/en/db2/12.1.x?topic=hadr-cluster-managers']],related:['G-01','G-02','G-04','I-02','K-03'] }),
L({id:'G-04',title:'HADR delay, log transport/replay diagnosis, and safe remediation',scope:['log generation versus sender','network throughput/latency','standby receive/spool capacity','log replay workload and disk','gap/archive retrieval','disconnect/state transitions','SQL1770N takeover eligibility','safe remediation and recheck'],branches:[['Send lag','Primary log production outpaces send/network.','Do not tune replay heap for a network bottleneck.'],['Receive/spool block','Standby cannot receive due queue/spool/full space.','Increasing spool without capacity and replay analysis can defer failure.'],['Replay lag','Standby disk/CPU/recovery workload cannot apply received logs.','Lowering source workload may not solve saturated standby device.']],lifecycle:['Capture primary and standby `db2pd -hadr` at multiple intervals.','Compare log positions, queue sizes, flags, network and disk latency.','Identify first diverging stage: generation/send, transport, receive/spool, replay.','Correct only the diagnosed limit and check state/takeover eligibility.','Reassess RPO and planned maintenance/failover risk.'],precheck:['Record current role/state/mode and incident impact.','Use matching timestamped samples; note member scope in pureScale.','Do not trigger takeover or stop HADR based on one queue sample.'],commands:[P('HADR queue and state sample','db2pd -db SAMPLE -hadr; sleep 10; db2pd -db SAMPLE -hadr','Instance owner','Primary and standby hosts separately','Bounded 10-second interval; command runs on each server; use native wait syntax.','Two snapshots show role/state/positions/queues and movement.','Compute log position and queue deltas; compare network and standby disk samples.','Read-only; do not modify HADR config until failure stage is localized.'),P('HADR monitor query','SELECT hadr_role, hadr_state, hadr_syncmode, log_gap, standby_log_receive_queue_size, standby_log_replay_queue_size FROM TABLE(mon_get_hadr(NULL)) AS h','Monitor-authorized DBA','Primary database, member-aware output','Name columns and sample on primary; pureScale output is local member stream.','HADR state and receive/replay queue fields are returned.','Trend over intervals; compare queue movement to primary log generation rate.', 'Read-only.')],example:'Receive queue stays near zero while replay queue grows and standby device write latency is high. Improve replay capacity/storage path or reduce replay contention; changing network buffer does not address the measured stage.',expected:'Delay is localized by stage, queues trend in right direction after action and RPO is measured against last applied/received commit.',issues:[{symptom:'Standby receive queue stalls at capacity.',evidence:'HADR flags, spool percentage/limit, standby log path free space and replay progress.',cause:'Replay is stalled or log spool reached configured limit.',fix:'Restore replay/disk capacity, clear only safe competing workload and recheck receive progress.',avoid:'Deleting standby spool/log files manually.'},{symptom:'HADR disconnects intermittently while both hosts appear healthy.',evidence:'TCP retransmits/latency, heartbeat timeout, firewall/NAT idle behavior and Db2 diagnostics.',cause:'Network interruption, timeout too low or path changes.',fix:'Network owner repairs path; tune timeouts only from measured outage and failure objectives.',avoid:'Setting huge timeout to hide recurring path loss.'},{symptom:'Operator proposes forced takeover because replay lag increased.',evidence:'sync mode, last received/replayed log, exact state and primary health/fencing.',cause:'Queue interpreted as permission to fail over; takeover has RPO and split-brain risk.',fix:'Use G-03 gate; if no outage, repair lag or planned maintenance instead.',avoid:'Takeover based on a single metric.'}],lab:'Analyze three 10-second HADR snapshots: send backlog, receive backlog and replay backlog. For each locate stage, owner, safest action and recheck. Include one SQL1770N scenario: state does not meet takeover eligibility. No HADR lab exists.',question:'Which queue matters for data received but not yet query-ready at standby?',answer:'Replay queue/position: logs arrived but still await application. Receive queue reflects shipped logs not yet received; send lag is earlier.',diagram:'flowchart LR\nG[Primary log generation] --> S[Send queue]\nS --> N[Network transport]\nN --> R[Standby receive queue and spool]\nR --> P[Log replay]\nP --> D[Standby disk and data point]\nG -. observe rate .-> S\nP -. observe lag .-> D',refs:[R.hadr,R.reorgMon,['IBM HADR state monitoring','https://www.ibm.com/docs/en/db2/12.1.0?topic=management-determining-hadr-standby-database-state'],['IBM SQL0964C guidance','https://www.ibm.com/docs/en/db2/12.1.x?topic=servers-troubleshooting-full-transaction-log-error']],related:['A-04','E-03','F-01','G-02','G-03'] }),
L({id:'G-05',title:'Q Replication and SQL Replication operations; keep CDC as a distinct product track',scope:['Q Capture/Apply control tables and queue maps','SQL Replication Capture/Apply control tables and CD tables','CDC product engine/subscription lifecycle distinct from Q/SQL','latency stages and commit sequence','conflict/exception handling','bulk utility resync/refresh','security/network and target reconciliation'],branches:[['Q Replication','Log-based Capture to MQ queues to Apply; queue maps and Q subscriptions.','Requires IBM IDR product, queue manager and control tables.'],['SQL Replication','Capture to change-data tables; Apply reads CD tables/subscription sets.','Distinct control tables, latency and pruning behavior.'],['CDC Replication','Separate replication product with subscriptions/mirroring/refresh and datastore services.','Do not use Q/SQL Replication commands or assume identical states.']],lifecycle:['Identify product/version/source/target and topology.','Verify Capture/Apply/CDC engines, control tables, queue/storage and subscription.','Start capture, establish snapshot/refresh baseline, then start apply/mirroring.','Monitor capture/queue/apply lag, errors and target keys.','After bulk change, run product-specific resync/refresh and reconcile target.'],precheck:['Read applicable IDR product release docs and supported source/target matrix.','Confirm source log retention, MQ queue depth or SQL CD table capacity.','Record last commit sequence, table maps, conflicts and trigger/constraint semantics.'],commands:[P('Start Q subscription from ASNCLP','ASNCLP SESSION SET TO Q REPLICATION; SET SERVER CAPTURE TO DB SAMPLE; SET CAPTURE SCHEMA SOURCE ASN1; START QSUB SUBNAME ORDERS_QSUB;','Replication operator with source/target privileges','Q Replication source SAMPLE and configured MQ queue map','Q Capture/Apply control tables, subscription and MQ queues already configured; command is product-specific.','Q subscription start is requested; Capture/Apply processes consume signals.','Check `asnqccmd`/`asnqacmd` status, queue depth, commit sequence and target reconciliation.','Stop the subscription through product command before altering control tables or dropping schema.'),P('SQL Replication start/monitor boundary','ASNCLP SESSION SET TO SQL REPLICATION; SET SERVER CAPTURE TO DB SAMPLE; SET CAPTURE SCHEMA ASN1;','Replication operator','SQL Replication Capture server','Build a complete ASNCLP script from current IDR docs; the snippet selects product context, it does not start a full subscription by itself.','ASNCLP context is set for SQL Replication; control definitions are product-specific.','Check Capture/Apply status, IBMSNAP_REGISTER/CD tables, subscription set and target keys.','Stop Capture/Apply by product lifecycle and preserve control tables until subscriptions removed.'),P('CDC subscription monitoring and refresh','CDC Replication: stop mirroring for selected subscription, flag table for refresh, run product Start Refresh, then restart mirroring','CDC administrator','Named CDC subscription/table through CDC Management Console/API','Use only CDC engine 11.4 documentation and approved consistency window; do not issue as SQL Replication command.','Refresh synchronizes source/target then resumes mirroring according to subscription method.','Check subscription state, refresh row counts/events and compare source-target keys/checksum.','Do not restart mirroring until refresh completes and target state is accepted.')],example:'A bulk LOAD affects a source table. Q Replication requires queue/subscription resynchronization choices; SQL Replication must reconcile capture/Apply and CD tables; CDC uses its own subscription refresh/mirroring states. Pick the product path from installed product, not the generic word “replication.”',expected:'Product-specific control planes are healthy, commit sequence/latency are understood, and source/target data is reconciled after baseline or resync.',issues:[{symptom:'Q Capture is running but Q Apply lag grows.',evidence:'Q Capture log position, send/receive queue depth, Apply status/errors and target locks.',cause:'Queue bottleneck, Apply error/target constraint or target workload contention.',fix:'Resolve earliest stage and restart only failed product process/subscription as documented.',avoid:'Dropping queue/control tables to clear latency.'},{symptom:'SQL Replication CD tables grow without pruning.',evidence:'Apply prune position, subscriptions, Capture status and CD table volume.',cause:'Apply not advancing/prune set missing or subscription stopped.',fix:'Restore Apply and verify commit sequence before controlled prune.',avoid:'Truncating CD tables before confirming applied point.'},{symptom:'CDC target diverges after bulk operation.',evidence:'subscription state, refresh/mirror point, event logs and source/target reconciliation.',cause:'Bulk change was not mirrored or refresh was skipped.',fix:'Stop selected mirroring, perform CDC refresh with workload controls and restart after validation.',avoid:'Using ASNCLP Q subscription operations for CDC.'}],lab:'Draw three independent sequence diagrams for Q, SQL Replication and CDC. Use official docs to write a start/stop/resync checklist and compare where backlog resides: MQ, CD table, or CDC engine. No replication product is installed here.',question:'Why keep CDC distinct from Q and SQL Replication?',answer:'It is a separate product engine with its own service, subscription states, refresh/mirroring control and tooling. Similar outcomes do not mean shared commands or lifecycle.',diagram:'flowchart LR\nS[Db2 source logs] --> Q[Q Capture queue map MQ Q Apply]\nS --> SQL[SQL Capture CD tables SQL Apply]\nS --> CDC[CDC engine subscriptions refresh mirror]\nQ --> T1[Q target reconciliation]\nSQL --> T2[SQL Rep target reconciliation]\nCDC --> T3[CDC target reconciliation]',refs:[['IBM Q Replication system commands','https://www.ibm.com/docs/en/idr/11.4.0?topic=reference-system-commands-q-replication-event-publishing'],['IBM Q subscription start','https://www.ibm.com/docs/en/idr/11.4.0?topic=program-starting-q-subscriptions'],['IBM SQL Replication Capture/Apply','https://www.ibm.com/docs/en/idr/11.4.0?topic=communicate-capture-program-apply-program'],['IBM CDC refresh','https://www.ibm.com/docs/en/idr/11.4.0?topic=replication-starting-refresh-subscription'],['IBM CDC replication states','https://www.ibm.com/docs/en/idr/11.3.3?topic=subscriptions-understanding-subscription-states']],related:['C-05','E-05','I-04','K-04'] }),
L({id:'G-06',title:'Separate DPF and pureScale architecture, command scope, failures, and labs',scope:['DPF partition layout/catalog partition/partition groups','distribution keys/maps and rebalance/redistribute','DPF node failure utilities and recovery','pureScale members/CF/cluster FS/interconnect','member and CF failover/restart/recovery','cluster manager and maintenance','HADR on DPF vs pureScale','separate topology diagrams and validation'],branches:[['DPF','Shared-nothing database partitions and data distribution.','Partition is not a pureScale member.'],['pureScale','Multiple members with CF coordination/shared cluster filesystem.','No DPF-style distribution key or db2nodes.cfg partition semantics.'],['HADR overlay','Creates cross-site recovery on supported topology.','pureScale HADR failover/cluster-manager rules differ.']],lifecycle:['Discover topology with supported commands and inventory.','Map all data locations and member/partition ownership.','Plan maintenance, utility, backup and recovery at topology scope.','Inject one controlled host/member/partition failure in a lab.','Verify all partitions/members, application route and data distribution.'],precheck:['Use `db2nodes.cfg` only for DPF; do not edit running instance.','Check CF, cluster filesystem and cluster-manager state on pureScale.','Plan interconnect and shared storage dependencies separately from HADR site.'],commands:[P('DPF partition inventory','cat $HOME/sqllib/db2nodes.cfg; db2_all "hostname; db2pd -inst"','DPF instance owner','All database partitions','DPF only; command fan-out must be bounded and outputs tagged by partition.','Node map and instance evidence from each partition are returned.','Run member-aware DB2 utilities/status and distribution-map validation.','Read-only; add/drop/change partition via supported utilities and planned rebalance, never edit live file.'),P('DPF rebalance/redistribution monitoring','db2pd -db SAMPLE -rebal; SELECT * FROM TABLE(mon_get_rebalance_status(NULL,-2)) AS r','DPF DBA/monitor user','DPF table-space/database partition movement','Use after an approved data redistribution or storage change; monitor all affected partitions.','Rebalance status/progress is visible.','Check completion, data distribution and application latency per partition.','Do not stop redistribution ad hoc; use documented utility control.'),P('pureScale cluster inventory','db2instance -list','pureScale instance owner','Members and CFs in cluster','pureScale only; check cluster manager and CF health first.','Member/CF roles and state are shown.','Compare with cluster manager, cluster filesystem and interconnect monitoring.','Read-only; cluster resource repair follows supported cluster manager procedures.'),P('pureScale member failure behavior','db2pd -db SAMPLE -members; db2diag -H 1d','pureScale DBA with host admin partner','Affected member and local cluster','Read-only evidence before asking cluster services to restart resources.','Member recovery/failover and logs are visible.','Verify restart light/member recovery, lock release, CF health and application continuation.','Never manually restart/kill CF or edit cluster profile outside product procedure.')],example:'After a DPF node outage, partition-local data and utilities require partition-wide recovery and distribution checks. After a pureScale member host failure, cluster services can restart the member locally or elsewhere and run crash recovery; CF/cluster filesystem/interconnect remain separate health checks.',expected:'The runbook names DPF partition or pureScale member/CF as the unit of failure and validates every affected scope.',issues:[{symptom:'DPF query or utility is slow only on one partition.',evidence:'per-partition CPU/I/O, data skew, distribution map, FCM and utility state.',cause:'Uneven data placement or one host/storage bottleneck.',fix:'Correct skew/capacity through tested redistribution or host remediation; compare all partitions.',avoid:'Increasing global resources while ignoring a single hot partition.'},{symptom:'pureScale member restarts in restart light and does not serve work.',evidence:'db2instance output, member recovery state, home host and CF health.',cause:'Member is recovering elsewhere to release locks/restore consistency; restart-light instance does not accept new transactions.',fix:'Wait for documented recovery and automatic failback; verify cluster resources before intervention.',avoid:'Attempting to route new workload to restart-light member.'}],lab:'Build independent DPF and pureScale runbooks. DPF lab: inspect node map and rebalance status. pureScale tabletop: member host loss, CF loss and site loss. Mark cluster manager owner and exact recovery evidence; no clusters are available here.',question:'Which configuration file belongs to DPF and why should it not be edited manually in a running instance?',answer:'`db2nodes.cfg` defines DPF partition hosts/ports. Db2 uses it for topology; changes require supported node utilities and can break coordinated partition scope.',diagram:'flowchart TD\nD[DPF shared-nothing] --> N[Partitions and db2nodes.cfg]\nN --> K[Distribution key partition groups]\nN --> B[Per-partition backup utility recovery]\nP[pureScale clustered] --> M[Members]\nP --> C[CFs and group buffer pools]\nP --> S[Cluster filesystem and interconnect]\nP --> H[Member CF recovery and local HA]',refs:[['IBM DPF node configuration','https://www.ibm.com/docs/en/db2/12.1.0?topic=files-creating-node-configuration'],['IBM DPF node file format','https://www.ibm.com/docs/en/db2/12.1.x?topic=file-format-db2-node-configuration'],['IBM pureScale components','https://www.ibm.com/docs/en/db2/12.1.x?topic=environment-components-db2-purescale-feature'],['IBM pureScale failure handling','https://www.ibm.com/docs/en/db2/12.1.0?topic=tdpf-understanding-how-db2-purescale-feature-automatically-handles-failure'],['IBM pureScale HADR setup','https://www.ibm.com/docs/en/db2/12.1.x?topic=environments-scenario-deploying-hadr-in-db2-purescale-environment']],related:['B-06','G-01','G-02','G-03','F-03','F-05'] })
);

lessons.push(
L({id:'F-01',title:'Circular/archive logging, log paths, sizing, log chains, and log-full diagnosis',scope:['circular versus archive recovery','primary/secondary logs and LOGFILSIZ','active/archive/mirror/overflow paths','archive methods LOGRETAIN USEREXIT DISK DB2REMOTE TSM VENDOR','log chain sequence and infinite logging','log buffer and pinned logs','SQL0964C/ADM1823E log-full diagnosis','restart/backup implications'],branches:[['Circular','Suitable for simple crash recovery where roll-forward is not required.','No roll-forward recovery from backup.'],['Archive logging','Required for roll-forward recovery and online backup.','Archive destination and log chain become recovery dependencies.'],['Infinite logging','Archive logs to extend active history where designed.','Archive failure can still exhaust active log resources.']],lifecycle:['Inspect log mode, sizes, active path and archive method.','Design log/active/archive filesystems and retention.','Enable archive method if converting, take required offline backup/reactivation boundary.','Monitor log usage and archive latency.','For SQL0964C identify pinned UOW/indoubt/archive failure, resolve and recheck rollback completion.'],precheck:['Capture DB CFG log settings and current log state.','Measure log filesystem blocks/inodes and archive destination reachability.','Before enabling archive logging, plan activation and mandatory backup boundary.'],commands:[P('Inspect current log configuration','db2 get db cfg for SAMPLE show detail; db2pd -db SAMPLE -logs','Instance owner/monitor operator','SAMPLE log stream','Read-only; correct database/member.','Log mode, sizes, paths and current log use are visible.','Compare active log range with archive method, filesystem and oldest UOW.','Read-only.'),P('Configure a lab archive destination','db2 update db cfg for SAMPLE using logarchmeth1 DISK:/db2archive/SAMPLE','SYSADM, SYSCTRL or SYSMAINT','Database SAMPLE','Existing empty private path; confirm owner permissions, backup boundary and archive retrieval procedure.','DB CFG value changes; if logarchmeth2 is OFF, transition takes effect after reactivation and requires an offline backup before reactivation.','GET DB CFG, create required offline backup, reactivate, then verify archive files from a controlled log switch.','Restore captured configuration only with documented transition/backup sequence; do not manually delete logs.'),P('Diagnose a full active log','db2pd -db SAMPLE -transactions; db2 "select application_handle, uow_start_time, uow_log_space_used from table(mon_get_unit_of_work(null,-2)) as u"','Instance owner / monitor user','SAMPLE active log holders','Use exact handle/transaction evidence; query all DPF members where applicable.','Long UOW and log usage are identified; ADM1823E may identify application handle.','After transaction commit/rollback or approved force, wait for rollback completion and confirm log use clears.','Do not force an indoubt transaction; use resolution procedure. Avoid manual log deletion.')],example:'SQL0964C plus ADM1823E identifies one application holding active log space. The condition can persist while a large rollback runs. Resolve the UOW safely, monitor rollback, and only use temporary LOGSECOND growth if the documented incident procedure requires it and filesystem headroom exists.',expected:'Logging mode and archive chain are understood; a log-full incident has an identified holder/archive fault and successful post-recovery log rotation.',issues:[{symptom:'SQL0964C and ADM1823E names an application handle.',evidence:'transaction log metrics, UOW start/log use, member notification logs and rollback state.',cause:'Large/long unit of work pins active log range.',fix:'Have owner commit/rollback or approve targeted force; monitor rollback to completion.',avoid:'Increasing log space indefinitely while leaving the pinned transaction running.'},{symptom:'Archive log path stops receiving files.',evidence:'archive method, permissions, free blocks/inodes, archive utility logs and db2diag.',cause:'Destination full, inaccessible, misconfigured or failing external vendor/API.',fix:'Restore destination/archive service and verify a new archived log is retrievable.',avoid:'Switching to circular logging to clear pressure without accepting loss of roll-forward recovery.'}],lab:'In a disposable recoverable database, set a small log configuration, generate a bounded transaction, observe UOW/log usage, and commit/rollback. Demonstrate archive path capacity fault only using a controlled test directory. Re-establish log archive and test archive retrieval.',question:'Why does `LOGARCHMETH1` changing from OFF not immediately mean recoverability is ready?',answer:'Depending on `LOGARCHMETH2`, activation boundary and mandatory offline backup apply. Archive destination must work, and restore/log-chain proof is required.',diagram:'flowchart TD\nW[UOW writes log records] --> A[Active log range]\nA --> P[Primary and secondary sizing]\nA --> R[Archive method and destination]\nR --> C[Recoverable log chain]\nP --> F{SQL0964C?}\nF --> H[ADM1823E holder archive path filesystem or indoubt]',refs:[['IBM logging configuration','https://www.ibm.com/docs/en/db2/12.1.x?topic=availability-configuring-database-logging'],['IBM log file allocation','https://www.ibm.com/docs/en/db2/12.1.x?topic=management-log-file-allocation-removal'],['IBM SQL0964C troubleshooting','https://www.ibm.com/docs/en/db2/12.1.x?topic=servers-troubleshooting-full-transaction-log-error']],related:['A-04','B-03','F-03','F-07','K-01'] }),
L({id:'F-02',title:'RPO/RTO, backup design, retention, capacity, encryption, and restore rehearsal',scope:['business consistency point and RPO','service restoration target and RTO','full/incremental/delta cadence','retention and image/log capacity','off-host/off-site/immutable copies','encryption/key availability','snapshot/vendor integration','backup window and workload','measured restore rehearsal'],branches:[['RPO','Maximum tolerable data loss, measured in recoverable commit time.','A backup schedule alone does not state actual RPO.'],['RTO','Time to restore service including infrastructure, restore, rollforward, validation and routing.','Backup duration is not full RTO.'],['Backup topology','Native images, snapshot or vendor media must map to restore capability.','A second copy in the same failure domain is not independent.']],lifecycle:['Identify transaction/data consistency objective and business owner.','Choose full/incremental/delta and log retention by recovery scenarios.','Budget primary/secondary copies, staging and encryption keys.','Rehearse restore to an isolated target and measure every step.','Set acceptance thresholds, retention and renewal cadence.'],precheck:['Collect data, log and growth rates plus backup image sizes.','Include restore staging, temp space, catalog/metadata and key custody.','Measure current restore/validation/application startup; record actual timestamp.'],commands:[P('Inspect backup history','LIST HISTORY BACKUP ALL FOR SAMPLE','Instance owner/backup authority','SAMPLE database history','Read-only; history can be pruned and is not the sole copy of evidence.','Backup type/time/device/status are listed.','Compare image storage inventory and log archive chain; perform a restore rehearsal.', 'Do not prune history until retention and incremental-chain requirements are proven.'),P('RPO/RTO calculation example','RPO_actual = incident_time - latest_recoverable_commit_time\nRTO_actual = infrastructure + restore + rollforward + validation + routing','DBA with service owner','Named recovery scenario/site','Use a real drill stopwatch and business-approved consistency point; formulas are planning definitions, not Db2 commands.','Recovery design has measured values and a stated acceptance gap.','Run a restore rehearsal and compare with objective.','If targets fail, change backup frequency/capacity/topology, then retest.')],example:'A 15-minute backup interval does not guarantee 15-minute RPO if log archiving is delayed. A four-hour database restore does not meet a two-hour RTO even when the image is valid. Test log retrieval and application validation at alternate site.',expected:'One written design maps each failure scenario to recoverable point, image/log chain, keys, target capacity, measured RTO and responsible owner.',issues:[{symptom:'Backup meets daily schedule but restore exceeds RTO.',evidence:'image sizes, restore bandwidth, log replay rate, key service and app startup timeline.',cause:'Policy optimized for backup completion, not recovery throughput/validation.',fix:'Measure bottleneck and add restore capacity/parallelism or alternate method; repeat full drill.',avoid:'Estimating RTO from backup duration.'},{symptom:'Retained images exist but needed log chain is missing.',evidence:'history records, archive inventory, chain IDs and missing sequence list.',cause:'Retention pruned required base/log or copies are not independent.',fix:'Repair retention and test from surviving image to intended point; accept lost RPO if no legal chain.',avoid:'Deleting logs based only on age or filename.'}],lab:'Design backup policy for a 2 TB OLTP database with 15-minute RPO and 2-hour RTO. Estimate image, logs, staging and offsite capacity from stated rates. Run a timed lab restore and compare with objective. Cleanup: keep test evidence, delete only disposable images under retention.',question:'What proves a backup plan meets its objective?',answer:'A successful independent restore/rollforward and application/data check with measured RPO and total RTO, including keys, logs, routing and validation.',diagram:'flowchart LR\nB[Backup cadence and type] --> I[Image retention]\nL[Log archive chain] --> P[Recoverable point]\nK[Encryption keys] --> R[Restore readiness]\nI --> R\nP --> R\nR --> V[Data integrity and application validation]\nV --> T[Measured RPO RTO]',refs:[R.backup,R.restore,R.recover,R.encryption],related:['F-03','F-04','F-09','G-01','I-06'] }),
L({id:'F-03',title:'Backup types and command selection: offline, online, full, incremental, delta, database, tablespace, LOAD copy, snapshot, and vendor media',scope:['offline full versus online full','incremental cumulative versus delta noncumulative','database versus table-space image','LOAD COPY image','snapshot API path and restrictions','TSM/vendor media','online archive-log inclusion','backup target and topology selection'],branches:[['Offline database full','Use when downtime is acceptable and simple consistent image is desired.','Database must be unavailable to applications.'],['Online database full','Use for live recoverable database; archive logging is prerequisite.','Requires rollforward and log-chain plan.'],['Incremental/delta','Choose based on change since last full versus last successful backup.','Restore chain and history must be retained.'],['Tablespace','Use for granular recovery only with rest of database/log consistency planned.','A tablespace image is not a complete database backup.'],['LOAD copy','Use as utility copy material under LOAD semantics.','It is not interchangeable with normal database backup image.'],['Snapshot/vendor media','Use only with supported Db2 ACS/vendor interface and tested restore.','Snapshot restrictions differ from normal incremental options.']],lifecycle:['Verify database log mode, backup history, image path/media and workload window.','Select image scope/type and LOGS behavior.','Precheck capacity, target permissions, topology, encryption keys and concurrent utilities.','Run one backup branch and monitor utility lifecycle.','Verify image metadata, required logs and documented limitations.'],precheck:['Run `GET DB CFG` for logarchmeth1 and backup settings.','Confirm target is server path or vendor/snapshot destination according to utility type.','Use target-specific retention and key procedures; protect image metadata.'],commands:[P('Offline full database','BACKUP DATABASE SAMPLE TO /db2backup/offline COMPRESS','SYSADM/SYSCTRL/SYSMAINT or backup authority','Whole single-member SAMPLE','Schedule outage; disconnect applications; confirm no recovery conflict.','Full consistent offline image completes.','LIST HISTORY and `db2ckbkp -h`; independent restore test remains required.','No live database change; preserve image through retention.'),P('Online full with logs','BACKUP DATABASE SAMPLE ONLINE TO /db2backup/online INCLUDE LOGS COMPRESS','Backup authority','Whole recoverable SAMPLE','Archive logging configured and archive path healthy; include logs for point after backup.','Online image and required log range are written.','Check utility status/history/image header and restore+rollforward to consistent endpoint.','If failure, preserve partial media/log evidence and follow utility failure state; retry with unique target.'),P('Cumulative incremental and delta','BACKUP DATABASE SAMPLE ONLINE INCREMENTAL TO /db2backup/inc; BACKUP DATABASE SAMPLE ONLINE INCREMENTAL DELTA TO /db2backup/delta','Backup authority','Whole database','Successful full base for incremental; prior successful image for delta; log chain/cadence validated.','First image includes changes since most recent full; delta includes changes since most recent backup of any type.','Read history to build chain; test automatic/manual restore and retain every dependency.','Do not delete base/delta images until dependent chain retention expires.'),P('Tablespace image','BACKUP DATABASE SAMPLE TABLESPACE (USERSPACE1) ONLINE TO /db2backup/ts','Backup authority','USERSPACE1 within SAMPLE','Check tablespace state, archive logging, concurrent work and recovery dependency of other spaces.','Image includes selected tablespace, not complete database.','Verify image and record compatible database backup/log position; test tablespace restore.','Retain full image/logs needed to recover related objects.'),P('LOAD copy path','LOAD FROM /tmp/items.del OF DEL INSERT INTO APP.ITEMS COPY YES TO /db2backup/loadcopy MESSAGES /tmp/items.load.msg','LOAD utility authority','Target table and LOAD copy directory','COPY YES path is writable and recovery model permits it; validate load options/constraints.','Load copy is created for that utility operation.','Preserve LOAD message/copy ID; verify backup-pending/state and subsequent database backup plan.','Failed LOAD requires RESTART/TERMINATE; copy image only addresses supported LOAD recovery.'),P('Snapshot or vendor media','BACKUP DATABASE SAMPLE USE TSM OPEN 2 SESSIONS; BACKUP DATABASE SAMPLE USE SNAPSHOT','Backup authority/vendor administrator','Media manager or supported snapshot integration','Run one branch only; verify installed ACS/vendor support and command restrictions.','Media session or coordinated storage snapshot completes.','Use matching RESTORE interface/media and application-consistent snapshot validation.','Vendor/snapshot abort and cleanup are product-specific; do not treat as ordinary filesystem copy.')],example:'Choose an offline full for planned maintenance when downtime is accepted; online full when business service must stay open and archive logs are healthy; incremental/delta only when every dependency is retained. A LOAD copy is tied to LOAD table-state rules, while TSM/snapshot requires matching media integration.',expected:'Each backup branch records database/table-space scope, image type, LOGS, target/media, encryption, monitoring, history, recovery chain and restore test.',issues:[{symptom:'Online backup is refused or cannot include required logs.',evidence:'archive mode, archive destination, utility messages and log chain.',cause:'Database is not recoverable or required log retrieval is unavailable.',fix:'Enable archive logging through required backup/reactivation process or correct archive path; then retry with a unique image.',avoid:'Changing to offline and assuming rollforward logs are captured.'},{symptom:'Delta image exists but automatic restore chain fails.',evidence:'LIST HISTORY, base/full timestamp, last-successful backup and missing image inventory.',cause:'Delta restores require intervening successful backups; chain item pruned/misidentified.',fix:'Use db2ckrst/history to map exact chain and restore manually only from complete set.',avoid:'Deleting incremental base or pruning history with force.'},{symptom:'Snapshot restore fails using normal REDIRECT options.',evidence:'image type/header, backup media API and restore restrictions.',cause:'Snapshot uses ACS/vendor path and excludes many RESTORE combinations.',fix:'Restore with supported snapshot/ACS method and test integration path.',avoid:'Copying live database files as a substitute.'}],lab:'For each branch create a written command choice and recovery sequence: offline, online full, incremental, delta, database, tablespace, LOAD copy, snapshot and vendor media. In a lab, run offline/online/incremental only if authorized Db2 environment exists. This package environment has none, so all are not executed.',question:'How does a delta backup differ from a cumulative incremental?',answer:'Cumulative incremental includes changes since the last full backup; delta includes changes since the last successful backup of any type. Their restore chain differs.',diagram:'flowchart TD\nQ[Recovery target and downtime] --> T{Image path}\nT --> O[Offline or online database full]\nT --> I[Full base then cumulative incremental]\nT --> D[Delta from prior backup]\nT --> S[Tablespace scope]\nT --> L[LOAD copy]\nT --> V[Snapshot or vendor media]\nO --> R[Matching restore and logs]\nI --> R\nD --> R\nS --> R\nL --> R\nV --> R',refs:[R.backup,R.restore,['IBM LOAD overview','https://www.ibm.com/docs/en/db2/12.1.x?topic=utility-load-overview']],related:['F-01','F-04','F-05','F-06','F-08'] }),
L({id:'F-04',title:'Backup execution, progress, history, image verification, and failure handling',scope:['utility lifecycle and concurrency','progress monitoring and list utilities','history file/catalog and PRUNE','db2ckbkp image structure limits','multi-piece images and storage','backup pending and failure/retry','retention evidence and restore drill'],branches:[['Progress','Observe active utility and phase/resource.','A completed CLP process does not prove media durability.'],['History','Use history as Db2 metadata with external copy.','History pruning can break automated chain discovery.'],['Image check','Use db2ckbkp for structural validation.','Header/check does not prove full restore or application correctness.']],lifecycle:['Precheck path/media, capacity, permission, backup chain and no conflicting operation.','Start backup with unique target and selected options.','Monitor utility and output; distinguish warning, failed, complete.','Record timestamp/history/image pieces and run header/integrity checks.','Restore to isolated target and validate data to close proof.'],precheck:['Check `LIST UTILITIES SHOW DETAIL`, history and target size.','Ensure destination supports required encryption/compression/media manager.','Protect logs, image, history export and key labels together.'],commands:[P('Monitor backup utility','LIST UTILITIES SHOW DETAIL; LIST HISTORY BACKUP ALL FOR SAMPLE','Instance owner/backup authority','Current instance and SAMPLE history','Run during a backup, then after completion.','Active utility phase and backup history entry appear.','Compare output with backup process code and media inventory.','Do not terminate active backup until understanding consistency and vendor cleanup.'),P('Inspect Db2 image header','db2ckbkp -h /db2backup/online/SAMPLE.0.db2inst1.DBPART000.20261027103000.001','Instance owner/backup verifier','Specific image file as named by actual output','Image path and all pieces verified; filename shown is synthetic example.','Header shows database, timestamp, platform, level and image metadata if valid.','For multi-piece images inspect all pieces; then perform actual restore rehearsal.', 'A failed check does not authorize deleting source copy; retain and investigate.')],example:'An online backup command succeeds but one stripe is missing in object storage. Db2 history lists the backup, but full media inventory/db2ckbkp reveals incomplete package. Mark backup unfit until restore verification; retain prior good chain.',expected:'Backup acceptance requires Db2 completion, media durability, history/image evidence, needed log/key availability and restore proof.',issues:[{symptom:'Backup utility fails with destination I/O or full-media error.',evidence:'LIST UTILITIES, Db2 messages, mount/inodes, vendor session and target quota.',cause:'Filesystem/media manager capacity, permission or connection failure.',fix:'Repair destination, preserve incomplete image/messages, retry using unique target after utility is clear.',avoid:'Overwriting the only known-good image.'},{symptom:'`db2ckbkp -h` passes but restore fails.',evidence:'all image pieces, platform/version, encryption key, target capacity and restore diagnostics.',cause:'Header check is structural and does not exercise restore engine/key/recovery path.',fix:'Restore copy in isolated host and validate data; correct media/key/compatibility dependency.',avoid:'Reporting full recovery readiness from header check alone.'}],lab:'Run a backup to a disposable directory, monitor LIST UTILITIES, inspect history and `db2ckbkp -h`, then restore a copy to an isolated alias if lab exists. Deliberate safe drill: rename one copy of a multi-piece lab image and verify validation failure; restore filename and recheck.',question:'What does a passing `db2ckbkp -h` establish?',answer:'It verifies image structural/header conditions; it does not prove all required media, encryption keys, log chain, restore completion or application/data correctness.',diagram:'flowchart TD\nP[Precheck target capacity keys] --> B[Run backup utility]\nB --> U[Monitor phase and status]\nU --> H[History and media inventory]\nH --> K[db2ckbkp structural check]\nK --> R[Isolated restore rehearsal]\nR --> A[Application and data validation]',refs:[R.backup,['IBM LIST UTILITIES command','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-list-utilities'],R.restore],related:['F-02','F-03','F-05','F-09'] }),
L({id:'F-05',title:'Full and redirected restore, alternate targets, path changes, and post-restore validation',scope:['original alias versus alternate target','REPLACE EXISTING safeguards','redirected restore REDIRECT/SET/CONTINUE','automatic storage path change','DMS container/path conflicts','online image rollforward pending','encryption key retrieval','restore pending SQL1117N and validation'],branches:[['Restore to original alias','Use for full replacement only with target identity gate.','REPLACE EXISTING can overwrite existing database without interactive prompt.'],['Alternate alias','Use for isolated recovery or migration within supported platform family.','Verify database name/path and application isolation.'],['Redirected restore','Use for new host, storage path or inaccessible containers.','Same CLP session must carry REDIRECT/SET/CONTINUE; cannot convert OS platform.']],lifecycle:['Verify selected image, timestamp, platform, database name and all pieces.','Reserve target paths/capacity and key availability.','Start restore to alternate or guarded original target.','For redirect: REDIRECT, set every target path/container, CONTINUE in same session.','Roll forward if needed, then verify table spaces, data, integrity, app and routing.'],precheck:['Use history and image header plus db2ckrst to identify exact image.','Check `REPLACE EXISTING`, alias, `INTO`, `ON`, path and encryption options before execution.','Protect source production database and preserve original backup/logs.'],commands:[P('Full alternate restore from image','RESTORE DATABASE SAMPLE FROM /db2backup/offline TAKEN AT 20261027103000 INTO QA1','SYSADM/SYSCTRL/SYSMAINT; SYSCTRL/SYSMAINT/SYSADM depending target','New isolated database QA1','Confirm timestamp/image/platform, target path space and absent alias QA1.','Database is restored under QA1; online image may be rollforward pending.','List directory, connect only to QA1, inspect table-space state, roll forward if required, and run app/data checks.','Drop only isolated QA1 after confirming exact alias/path and no needed evidence.'),P('Redirected restore sequence','RESTORE DATABASE SAMPLE FROM /db2backup/offline TAKEN AT 20261027103000 INTO QA1 REDIRECT; SET STOGROUP PATHS FOR SG_HOT ON \'/db2new/fast\'; RESTORE DATABASE QA1 CONTINUE','Recovery DBA with restore authority','New alternate QA1 database and new storage group path','Precreate/measure path, use same CLP window, review every storage group/table-space mapping; no cross-OS move.','CONTINUE restores data using changed path definitions.','After completion, inspect containers/storage group associations and run integrity/application validation.','If redirect is incomplete, use documented restore abort/cleanup; never use replace-existing on source alias.'),P('Roll forward and open restored database','ROLLFORWARD DATABASE QA1 TO END OF LOGS AND STOP OVERFLOW LOG PATH (/db2archive/SAMPLE)','SYSADM/SYSCTRL/SYSMAINT','Restored QA1 in rollforward pending state','Required log sequence is available and destination key works.','Recovery reaches end-of-logs and STOP completes rollforward.','Connect, check table-space states, compare expected data counts and execute application smoke tests.','STOP is terminal for that recovery point; do not issue until target point/log completeness is confirmed.')],example:'Restore an online image to `QA1`, not the production `SAMPLE`, then roll forward only the intended logs. This isolates recovered point from active application commits and avoids accidental overwrite while validation is in progress.',expected:'Recovered database opens at the intended alias/path/time, table spaces are normal and application/data validation passes before routing.',issues:[{symptom:'SQL1117N indicates rollforward pending.',evidence:'restore message, log chain, current rollforward query and archived log retrieval.',cause:'Image was online/recoverable and restore is awaiting log application.',fix:'Supply complete correct logs and roll forward to chosen endpoint; stop only at approved target.',avoid:'Trying ordinary CONNECT or WITHOUT ROLLING FORWARD on unsupported image.'},{symptom:'Redirected restore reports container/path error or SQL2563W.',evidence:'script path mapping, table-space sizes, storage groups, device/directory container type and db2diag.',cause:'A container mapping is missing, inaccessible or too small for restored data.',fix:'Rebuild mapping with full container set and enough capacity, then continue/restart documented restore.',avoid:'Changing storage paths after data restore starts without supported flow.'},{symptom:'Restore overwrites wrong database alias.',evidence:'command echo, catalog directory, database path and ticket target.',cause:'Unsafe alias/REPLACE EXISTING option or target variable error.',fix:'Stop before start if possible; if execution began, preserve logs and activate recovery plan for overwritten target.',avoid:'Using scripts with silent REPLACE EXISTING and no target confirmation.'}],lab:'Restore an offline test image to QA1, then generate and review a redirected script for a second disposable target. Check every path and storage group before running. For online image test, supply archived logs and STOP at an agreed endpoint. Cleanup only test aliases.',question:'When does an online restore become available to applications?',answer:'After required rollforward logs are applied and recovery is stopped/completed at an approved endpoint, table-space state is normal, and application/data validation succeeds.',diagram:'flowchart TD\nI[Image and target identity verified] --> R[Restore original or alternate]\nR --> D{Paths differ?}\nD -->|yes| G[REDIRECT map containers/storage groups CONTINUE]\nD -->|no| L[Restore completes]\nG --> L\nL --> F{Rollforward pending?}\nF -->|yes| T[Apply exact logs then STOP]\nF -->|no| V[Validate state data app and route]\nT --> V',refs:[R.restore,['IBM redirected restore procedure','https://www.ibm.com/docs/en/db2/12.1.x?topic=restore-performing-redirected-operation'],['IBM generated redirected script','https://www.ibm.com/docs/en/db2/12.1.x?topic=operation-performing-redirected-restore-using-automatically-generated-script'],R.roll],related:['F-02','F-03','F-06','F-07','F-09','I-04'] }),
L({id:'F-06',title:'Automatic/manual incremental and delta restore chains',scope:['identify base and required images','automatic incremental restore/history mapping','manual cumulative restore image order','delta chain semantics','missing/misordered image recovery','alternate target and image identity','member/partition image scope','platform/version limits'],branches:[['Automatic incremental','Use when history provides a complete chain.','Requires complete history/image set; may require abort on failed chain.'],['Manual incremental','Use when chain must be explicitly supplied or automatic reconstruction fails.','Order is target image metadata, then base and successive images per documented sequence.'],['Delta series','Track every intervening successful backup since base.','Pruning history with force can remove automatic chain data.']],lifecycle:['List history and determine target image timestamp.','Run db2ckrst/history inventory to enumerate required images.','Choose automatic chain or manual one-command-per-image flow.','Restore all image pieces in documented order; handle abort if automatic fails.','Roll forward required logs and validate final state.'],precheck:['Copy complete image set to protected staging path.','Verify timestamps, database names, platform levels, image pieces and history.','Never use PRUNE HISTORY WITH FORCE during chain investigation.'],commands:[P('Automatic cumulative incremental restore','RESTORE DATABASE SAMPLE INCREMENTAL AUTOMATIC TAKEN AT 20261027120000 FROM /db2backup/inc INTO QA2','Recovery authority','New isolated QA2 database','Target timestamp is intended endpoint and history includes full base plus all incrementals.','Db2 reads target metadata, resolves chain and restores required images automatically.','Check restore completion, history and database state; roll forward as necessary.','If chain resolution fails, issue documented INCREMENTAL ABORT and cleanly choose manual path.'),P('Manual incremental sequence guide','RESTORE DATABASE SAMPLE INCREMENTAL TAKEN AT 20261027120000 FROM /db2backup/inc; RESTORE DATABASE SAMPLE INCREMENTAL TAKEN AT 20261027080000 FROM /db2backup/full; RESTORE DATABASE SAMPLE INCREMENTAL TAKEN AT 20261027100000 FROM /db2backup/inc','Recovery authority','New isolated target; each image timestamp is illustrative','Use db2ckrst-generated chain and the exact release-documented order; keep sequence/time in a recovery worksheet.','Each command applies the target/base/intermediate image as specified by manual procedure.','After every command verify return and target state; final logs/app validation close recovery.','Do not retry one step on uncertain partial state; use RESTORE INCREMENTAL ABORT if operation is pending and documented.')],example:'The target is 12:00. History shows full at 08:00 and incremental at 10:00 plus target incremental at 12:00. Automatic restore uses history; manual restore requires the set and order. A missing 10:00 image means automatic chain cannot complete; do not substitute a later delta.',expected:'The exact base/target/intermediate image set is preserved; restore reaches intended timestamp and log endpoint.',issues:[{symptom:'Automatic incremental restore cannot build chain.',evidence:'db2ckrst output, history entries, image timestamps and missing storage objects.',cause:'Image/history dependency absent or incompatible chain.',fix:'Abort automatic operation as documented, retrieve missing object or use complete manual chain.',avoid:'Pruning history or guessing filenames.'},{symptom:'Manual restore leaves target in inconsistent pending state.',evidence:'per-command restore messages, image types/order and restore-pending state.',cause:'Wrong image sequence, target/base reversed or one intermediate missing.',fix:'Use generated recovery sequence and restart cleanly only after documented abort/cleanup.',avoid:'Connecting applications to partial restore.'}],lab:'Build a chain worksheet from fictional full/incremental/delta timestamps. Resolve a missing middle image and identify whether any legal restore reaches target. In a disposable Db2 lab, test automatic restore and db2ckrst; none was available in current environment. Cleanup QA2 and media only after validation.',question:'Why should the last image timestamp not be the only item retained?',answer:'Restore needs every base/intermediate image and history/log dependency. A target image alone may contain only changed pages, not a complete database.',diagram:'flowchart LR\nF[Full base] --> I1[Incremental changes since full]\nI1 --> I2[Next cumulative or delta chain]\nI2 --> T[Target image]\nH[History and image inventory] --> A{Automatic chain available?}\nA -->|yes| X[Automatic restore]\nA -->|no| M[Manual chain and exact order]\nX --> V[Logs and validation]\nM --> V',refs:[['IBM incremental restore procedures','https://www.ibm.com/docs/en/db2/12.1.x?topic=recovery-restoring-from-incremental-backup-images'],R.restore,['IBM db2ckrst command','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-db2ckrst']],related:['F-03','F-04','F-05','F-07','K-02'] }),
L({id:'F-07',title:'Rollforward, end-of-logs, point-in-time recovery, STOP/COMPLETE decisions, and missing logs',scope:['rollforward pending after restore','end-of-logs vs PIT','archive/overflow path and log chain','database vs tablespace recovery','time zone and consistency point','STOP/COMPLETE terminal state','SQL4970N/missing/wrong logs','active-log handling','post-recovery data validation'],branches:[['END OF LOGS','Use to recover to latest complete available log point.','Only if all required logs are present and valid.'],['Point in time','Use to stop before corruption/business error timestamp.','PIT affects whole database consistency and timezone conversion.'],['STOP/COMPLETE','Stop closes rollforward and opens database at selected endpoint.','It is a terminal choice; later logs need a new recovery strategy.']],lifecycle:['Confirm image and current rollforward state.','Map exact required log sequence and archive retrieval.','Choose endpoint: end of logs or PIT in documented timestamp format/timezone.','Apply logs without stopping prematurely; inspect query status and missing sequence.','Issue STOP/COMPLETE only at approved endpoint; validate data and application.'],precheck:['Use `ROLLFORWARD QUERY STATUS` to see next log/time and pending state.','Identify cutoff from business/system timeline with UTC and timezone conversion.','Preserve current copy and all available logs before the terminal command.'],commands:[P('Inspect rollforward boundary','ROLLFORWARD DATABASE QA1 QUERY STATUS','Recovery authority','Restored QA1 in rollforward pending state','Do not connect app users; identify current log/last committed point.','Output reports log files needed and rollforward progress/status.','Compare next log/time with archive inventory and recovery worksheet.','Read-only query; preserve exact output.'),P('Recover to end of available logs','ROLLFORWARD DATABASE QA1 TO END OF LOGS OVERFLOW LOG PATH (/db2archive/SAMPLE); ROLLFORWARD DATABASE QA1 STOP','SYSADM/SYSCTRL/SYSMAINT','Isolated QA1 recovery copy','Only use after all required logs are staged and end-of-logs target is approved.','Db2 replays logs and STOP completes recovery at last available consistent point.','Check rollforward status, connect, inspect table spaces and run business integrity checks.','STOP is terminal at this point; if the endpoint is wrong, restore/recover again rather than expecting to resume forward.'),P('Point-in-time recovery','ROLLFORWARD DATABASE QA1 TO 2026-10-27-10.30.00.000000 AND STOP OVERFLOW LOG PATH (/db2archive/SAMPLE)','Recovery authority','Isolated QA1, intended PIT at 10:30 UTC after explicit timezone mapping','Confirm exact timestamp syntax for release, time zone, business point and required logs.','Logs replay through target point; database opens at target.','Query status, compare known transactions before/after boundary and run app validation.','Do not issue STOP if timestamp/zone or log completeness is unresolved.')],example:'A corruption begins at 10:33 UTC; database logs are local time UTC+5:30. Convert the selected recovery point carefully and record both timestamps. Restore to a separate alias, roll forward through the last safe commit, then stop and reconcile affected business requests.',expected:'Recovery is open at an approved and documented log point; data/transactions after PIT are understood and reconciled.',issues:[{symptom:'SQL4970N or missing log sequence during rollforward.',evidence:'query status, expected next log, chain ID, archive catalog/retrieval and filename checksum.',cause:'Archive retrieval failed, wrong chain/path, corrupt log or endpoint beyond available logs.',fix:'Retrieve the exact next log from approved archive and retry; if permanently absent, select a legal earlier point or escalate data-loss decision.',avoid:'Renaming unrelated log files to satisfy sequence.'},{symptom:'Database opens but includes unwanted late transactions.',evidence:'chosen timestamp, timezone conversion, PIT status and transaction commit time.',cause:'PIT chosen after the bad commit or clock/timezone mismatch.',fix:'Repeat recovery to earlier point on isolated target and reconcile lost work.',avoid:'Using `STOP` without verifying business cutoff.'}],lab:'Use a disposable restore and create timestamped transactions around an announced bad commit. Recover once to end-of-logs and once to an earlier PIT; compare rows and explain data loss. Practice query status before STOP. Cleanup recovered lab aliases.',question:'Why is STOP a decision gate?',answer:'It completes rollforward at a selected endpoint. If the selected point or logs are wrong, STOP can make further log application unavailable without a new restore/recovery path.',diagram:'flowchart TD\nR[Restore pending database] --> Q[QUERY STATUS and next log]\nQ --> A[Retrieve ordered logs]\nA --> D{Approved endpoint?}\nD -->|End of logs| E[TO END OF LOGS]\nD -->|Earlier target| P[TO timestamp with timezone]\nE --> S[STOP terminal]\nP --> S\nS --> V[Data integrity reconciliation and app test]',refs:[R.roll,R.recover,R.restore,['IBM rollforward command','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-rollforward-database']],related:['F-05','F-06','F-08','F-09','K-02'] }),
L({id:'F-08',title:'Tablespace backup and recovery, online/offline behavior, and consistency checks',scope:['tablespace backup vs database image','online/offline restore and rollforward state','table-space point in time vs database PIT','multiple spaces and partition scope','logging requirements and active HADR restrictions','space-state inspection','object and cross-tablespace application consistency'],branches:[['Tablespace backup','Reduce backup scope for isolated objects with tested dependency map.','It does not protect catalog, other tablespaces or application consistency by itself.'],['Tablespace restore','Use when one space is damaged and rest database is sound.','Requires appropriate database/table-space backup and logs.'],['Table-space PIT','Recover a selected space to a point while coordinating interdependent spaces.','May create inconsistent business state across objects.']],lifecycle:['Map object-to-tablespace and FK/application dependencies.','Take database/tablespace image with required logging.','Inspect state and restore pending scope after incident.','Restore selected spaces/images; roll forward correct spaces/logs.','Check integrity, cross-space consistency, application and backup status.'],precheck:['Capture `LIST TABLESPACES SHOW DETAIL` and object placement.','Identify if online backup and required log chain are available.','Coordinate all related tablespaces and HADR role before restore.'],commands:[P('Back up one online tablespace','BACKUP DATABASE SAMPLE TABLESPACE (USERSPACE1) ONLINE TO /db2backup/ts1 INCLUDE LOGS','Backup authority','USERSPACE1 in recoverable SAMPLE','Archive logging, tablespace online state and media capacity confirmed.','Selected tablespace image and required logs are stored.','History/image checks and test restore into isolated recovery copy.','Retain coordinating database backup/log chain; do not discard full recovery dependency.'),P('Restore and roll forward tablespace','RESTORE DATABASE SAMPLE TABLESPACE (USERSPACE1) FROM /db2backup/ts1 TAKEN AT 20261027103000; ROLLFORWARD DATABASE SAMPLE TO END OF LOGS AND STOP TABLESPACE (USERSPACE1)','Recovery authority','Selected USERSPACE1 and database context','Check exact image scope, state, member, table-space dependency and expected log endpoint.','Table space restore completes then selected space rollforward clears pending state.','Check `LIST TABLESPACES SHOW DETAIL`, table/object integrity, cross-space FKs and application reads.','Do not open app before space state is normal; stop point can require full coordinated recovery if wrong.')],example:'An isolated table in USERSPACE1 is damaged, while its parent rows reside in another tablespace. Recovering USERSPACE1 alone can restore Db2 physical state but still require business reconciliation across both objects.',expected:'Target tablespace is normal and its rows are valid; related application objects and transactions are consistent.',issues:[{symptom:'One tablespace remains restore-pending after restore.',evidence:'tablespace state, restore messages, container capacity and missing log range.',cause:'Data image incomplete, container too small or rollforward not completed.',fix:'Complete required image chain/logs or correct redirected path, then verify state.',avoid:'Restarting applications against partially available database.'},{symptom:'Table-space PIT yields invalid referential business state.',evidence:'cross-table constraints, related tablespaces and commit point alignment.',cause:'Related objects were recovered to different points.',fix:'Coordinate recovery points for all dependent spaces or recover whole database to common PIT.',avoid:'Assuming physical space recovery equals application consistency.'}],lab:'Place parent and child tables in separate lab tablespaces. Back up them and perform an isolated table-space restore/rollforward in a clone. Check dependencies and data time point. No lab server is available here, so command path is not executed. Cleanup the clone only after preserving evidence.',question:'When is full-database PIT safer than one-table-space PIT?',answer:'When business consistency spans objects in different table spaces or when the failure time affects multiple areas; a common database endpoint avoids mixed-time relationships.',diagram:'flowchart TD\nO[Object and dependency map] --> B[Database and tablespace backups]\nI[Incident scope] --> S[Select tablespace or whole database]\nS --> R[Restore image and containers]\nR --> L[Rollforward logs and state]\nL --> C[Cross-space integrity and business checks]',refs:[R.backup,R.restore,R.roll,['IBM table-space recovery','https://www.ibm.com/docs/en/db2/12.1.x?topic=recovery-table-space-recovery']],related:['C-04','F-03','F-05','F-07','K-02'] }),
L({id:'F-09',title:'Recovery failure drills, decision trees, legal next steps, evidence, and measured RTO',scope:['missing/corrupt image or wrong alias/member','missing archive log and earlier PIT choice','key/archive retrieval failure','path/storage exhaustion','platform/version incompatibility','restore/rollforward pending states','inspect/check utilities','stop/escalate gates','measured RTO and integrity validation'],branches:[['Missing/corrupt image','Find alternate immutable copy and verify every stripe.','Do not overwrite only known-good copy.'],['Missing log','Find alternate archive; else choose earlier consistent point with owner approval.','No legal rollforward can skip required log records.'],['Key/path/version issue','Correct dependency or stage compatible target and capacity.','Do not bypass encryption or compatibility constraints.']],lifecycle:['Freeze target/image/log/key identity and incident timeline.','Classify failure: media, chain, key, path, compatibility or state.','Choose legal recovery path and identify terminal commands.','Restore to isolated alternate target where possible.','Verify database/table-space state, keys, data/app and RTO; report accepted loss.'],precheck:['Use image headers, db2ckrst, history and query status before retry.','Record exact first failing message with SQLCODE/SQLSTATE and stack.','Agree business cutoff and data-loss decision before PIT/forced completion.'],commands:[P('Check restore prerequisites','db2ckbkp -h /db2backup/candidate.001; db2ckrst -d SAMPLE -t 20261027120000','Recovery operator','Candidate image and history chain','Use installed utility syntax; run against copies; confirm image pieces/keys/platform.','Image metadata and candidate chain are summarized.','Compare output with media catalog and archived-log inventory; then isolate restore.','No source files changed.'),P('Capture restore/rollforward state','db2 list utilities show detail; db2 rollforward db QA1 query status; db2 list tablespaces show detail','Recovery operator','Target QA1 only','Read-only and no application writes; record time/state.','Pending utility, next log and tablespace state are shown.','Compare with recovery worksheet and choose one supported next transition.','Do not issue CONTINUE/STOP until target and endpoint verified.')],example:'The image passes header check but restore fails because the target volume is too small. Legal next action is to redirect to a sufficiently large compatible path or select a smaller older image if appropriate. Repeated restore to same full path cannot solve capacity; assess alternate destination and RTO.',expected:'A decision tree identifies one legal next command or an escalation/data-loss gate without destroying source evidence.',issues:[{symptom:'Candidate backup image is corrupt or incomplete.',evidence:'db2ckbkp, all media pieces, transfer checksum and second-copy inventory.',cause:'Storage/transfer corruption, missing stripe or wrong image object.',fix:'Retrieve alternate immutable copy and validate before restore.',avoid:'Deleting or overwriting the original failed image.'},{symptom:'Required log unavailable and target cannot roll forward.',evidence:'query status next log, archive system search, retention/key and archive failover.',cause:'Log pruned, archive outage or recovery metadata mismatch.',fix:'Retrieve exact log, or seek approval to recover to earlier legal point with data-loss accounting.',avoid:'Skipping a sequence or fabricating a log name.'},{symptom:'Restore command rejects platform/version combination.',evidence:'image header level, server OS/architecture, fix pack and IBM compatibility docs.',cause:'Unsupported cross-platform restore family or release path.',fix:'Use supported migration/logical export path or intermediate compatible server.',avoid:'Forcing a restore across endian/OS restrictions.'}],lab:'Run tabletop drills for corrupt stripe, missing log, expired key, full restore volume and wrong database alias. For each, list evidence, legal next action, terminal point, business decision and elapsed time. Do not stage destructive failure in an unavailable/non-disposable system.',question:'What is the correct action if required log sequence is permanently unavailable?',answer:'No rollforward can skip it. Search all approved archives; if unrecoverable, restore/roll forward only to an earlier valid endpoint with explicit data-loss acceptance, or escalate if no acceptable point exists.',diagram:'flowchart TD\nF[Recovery failure] --> I[Image chain log key path version state]\nI --> L{Legal dependency available?}\nL -->|yes| C[Correct dependency and continue] --> V[Restore validation and RTO]\nL -->|no| P[Find earlier consistent point]\nP --> B{Business accepts data loss?}\nB -->|yes| R[Recover to approved earlier point]\nB -->|no| E[Escalate; preserve source and evidence]',refs:[R.backup,R.restore,R.roll,R.recover,['IBM cross-platform recovery guidance','https://www.ibm.com/docs/en/db2/12.1.x?topic=dbrs-backup-restore-operations-between-different-operating-systems-hardware-platforms']],related:['F-02','F-04','F-05','F-06','F-07','F-08','K-02'] })
);

lessons.push(
L({id:'D-01',title:'Authentication, operating-system identity, providers, and security plugins',scope:['server/client authentication settings','OS local identity, LDAP/Kerberos/GSS provider boundary','plugin and case mapping','service identities and trusted contexts','password/key rotation','connection identity verification','failed login evidence without secrets'],branches:[['OS authentication','Use local or directory identity that the server can resolve.','Db2 database user name is not automatically the OS service identity.'],['External provider/plugin','Use only the configured, supported server/client plugin and directory.','Changing plugin order can lock out service accounts.'],['Trusted context','Use when application identity propagation and trust attributes are explicitly designed.','It is not a bypass for authentication or authorization review.']],lifecycle:['Identify server and client authentication parameters/plugins.','Resolve user and groups from the server’s actual provider.','Connect using a controlled account.','Verify effective session identity and failed-login evidence.','Rotate provider credentials/certificates with overlap and rollback gates.'],precheck:['Record current auth/plugin configuration and Db2 release.','Verify service-account lookup and group/case mapping on all nodes.','Do not collect passwords or secret-bearing traces.'],commands:[P('Inspect server auth settings','db2 get dbm cfg | grep -i -E "authentication|srvcon_auth|group_plugin|server_plugin"; db2set -all','Instance owner','Current Db2 server instance','Read-only; use platform-appropriate filtering on Windows/AIX.','Authentication/plugin values and registry configuration are printed.','Compare with configured client provider and connection identity from SQL.','No state change; preserve existing authentication path until alternate tested.'),P('Verify authenticated identity','VALUES CURRENT SERVER, CURRENT USER, SESSION_USER;','Database test identity','Connected target database','Connect through the same route/driver used by the application test.','Server, authorization ID and session ID are returned.','Compare with application logs and expected group/role mapping.','Disconnect; never echo credentials into transcript.')],example:'An application connects but cannot see an expected role. `SESSION_USER` confirms authentication succeeded; group resolution/effective authorization is a different step. Preserve both server plugin evidence and database grant evidence.',expected:'Login identity, session identity, OS/provider mapping, and Db2 authorization are evidenced separately.',issues:[{symptom:'SQL30082N authentication failure after directory maintenance.',evidence:'client/server time, plugin logs, identity lookup, provider availability and sanitized db2diag.',cause:'Group/user case mapping, directory outage, credential rotation mismatch, or plugin load issue.',fix:'Restore provider reachability or synchronized credential mapping; test with one safe account.',avoid:'Switching server authentication to a weaker mode during an incident.'},{symptom:'User authenticates on one member but not another.',evidence:'NSS/LDAP lookup and plugin/config values on each host/member.',cause:'Directory/cache/provider or case mapping differs by node.',fix:'Reconcile provider configuration and name lookup before routing users again.',avoid:'Granting broad database privileges to mask an identity failure.'}],lab:'Configure two synthetic identities in a disposable directory/lab model. Trace provider lookup, connection authentication, CURRENT USER/SESSION_USER and group authorization. Failure drill: disable only the test provider route, observe sanitized failure evidence, restore and retest.',question:'Does a successful login prove the user has SELECT on a table?',answer:'No. Authentication establishes identity; authorization and object privileges/roles determine permitted operations. Verify session identity and effective grants independently.',diagram:'flowchart LR\nA[Client identity] --> P[Auth provider/plugin]\nP --> S[Db2 server authentication]\nS --> U[Session authorization IDs]\nU --> G[Groups roles authorities privileges]\nG --> O[Object access]',refs:[['IBM authorization model','https://www.ibm.com/docs/en/db2/12.1.x?topic=model-authorization'],['IBM authentication overview','https://www.ibm.com/docs/en/db2/12.1.x?topic=security-authentication']],related:['D-02','D-03','D-06','A-02'] }),
L({id:'D-02',title:'Authorities, privileges, roles, groups, ownership, and effective access',scope:['SYSADM/SYSCTRL/SYSMAINT/SYSMON boundaries','SECADM/DBADM/DATAACCESS/ACCESSCTRL/SQLADM','database schema and object grants','roles/groups/PUBLIC/ownership/delegation','effective access and grant option','dynamic versus static package checks','least privilege and break glass','Db2 12.1 DBADM default changes'],branches:[['Authority','System/database capability bundle.','DBADM does not imply every data/security privilege in 12.1.'],['Object privilege/role','Grant only the needed action on named objects.','A role/group grant can interact differently with static SQL binding.'],['Ownership/delegation','Object owner and GRANT OPTION control administration.','Avoid changing ownership to solve one missing privilege.']],lifecycle:['Identify authenticated session and SQL execution authorization ID.','List direct, role, group, PUBLIC, authority and ownership grants.','Compare package DYNAMICRULES/bind owner for static SQL.','Grant the narrowest missing privilege with approval.','Retest under the real app identity; audit and expire break-glass access.'],precheck:['Query effective grant sources and the 12.1 authority behavior reference.','Confirm whether command runs as SECADM, DBADM or object owner.','Capture existing grant/revoke statements before change.'],commands:[P('Grant scoped read privilege','GRANT SELECT ON TABLE APP.ORDERS TO ROLE REPORT_READER;','Object owner or ACCESSCTRL authority','APP.ORDERS and role REPORT_READER','Confirm role exists and contains only approved users; ensure schema/table target.','Grant is cataloged.','Reconnect as an intended role member; run allowed SELECT and denied write test.','REVOKE SELECT only if this is the new grant and no dependent workflow relies on it.'),P('Explicit Db2 12.1 DBADM choice','GRANT DBADM ON DATABASE TO USER DBA_OPS WITHOUT DATAACCESS WITHOUT ACCESSCTRL;','SECADM','One database and DBA_OPS principal','Db2 12.1.0 behavior; verify exact grant syntax and approved scope.','DBADM is granted without implicitly adding data or access-control authority.','Inspect database authority catalog and test object/security administration separately.','REVOKE DBADM from this newly granted principal after confirming no broader assignment.')],example:'After a 12.1 migration, a DBA with DBADM can perform administration but lacks DATAACCESS and ACCESSCTRL by default unless explicitly granted. A failed SELECT or GRANT is not corrected by assuming legacy bundled authority; add only what the role needs.',expected:'The principal’s access is derived from authenticated ID, group/role membership, authority, privilege, ownership, package rules and RCAC/LBAC.',issues:[{symptom:'DBA can manage objects but cannot query protected table.',evidence:'12.1 grant semantics, DBADM/DATAACCESS catalogs, RCAC/LBAC policy and session identity.',cause:'DBADM no longer automatically includes DATAACCESS in Db2 12.1.',fix:'Use a separately approved DATAACCESS or object-level grant; test under intended identity.',avoid:'Setting an alternate global authorization behavior solely to preserve legacy assumptions.'},{symptom:'Dynamic query succeeds but static package fails authorization.',evidence:'package owner/bind options, group memberships at bind/runtime and effective privilege.',cause:'Static SQL privilege checking follows package binding rules; group grants may differ.',fix:'Correct the package owner/grants and rebind only affected package after review.',avoid:'Granting DATAACCESS to PUBLIC.'}],lab:'Create a reader role, grant SELECT on one synthetic table, assign one test group/user, and verify allowed/denied operations. Then model Db2 12.1 DBADM without DATAACCESS/ACCESSCTRL. Cleanup: revoke only lab grants and drop role after removing memberships.',question:'In Db2 12.1, what must be checked before assuming DBADM permits row reads and grant administration?',answer:'Check DATAACCESS and ACCESSCTRL separately because DBADM no longer adds those authorities by default. Confirm direct/effective grants and the exact connected identity.',diagram:'flowchart TD\nI[Authenticated identity] --> E[Effective roles and groups]\nE --> A[System and database authorities]\nE --> P[Schema and object privileges]\nP --> O[Ownership and delegation]\nO --> X[Package bind rules and RCAC LBAC]',refs:[R.auth12,['IBM DBADM authority','https://www.ibm.com/docs/en/db2/12.1.x?topic=authorities-database-administration-authority-dbadm'],['IBM authorization and ownership','https://www.ibm.com/docs/en/db2/12.1.x?topic=model-authorization-privileges-object-ownership']],related:['D-01','D-05','C-02','I-01'] }),
L({id:'D-03',title:'Client catalogs, aliases, drivers, connection configuration, and reroute',scope:['TCPIP node/database catalog and alias','uncatalog and cache behavior','wrong-target guard','CLI ODBC JDBC .NET levels','db2dsdriver.cfg and db2cli.ini','driver/client trace','pool keepalive and client reroute','SQL1013N and SQL30081N layers'],branches:[['Cataloged CLI client','Use catalog entries for node/service/database alias mapping.','Alias is local client metadata, not a database name guarantee.'],['Driver config','Use documented driver-specific settings and match client level.','A JDBC URL is not controlled by a CLI catalog in every application.'],['Reroute/pooling','Use only after primary/alternate host and transaction behavior are tested.','Reroute does not make an in-flight transaction replay safe.']],lifecycle:['Identify application driver/version and runtime host.','Resolve alias/DSN/URL to endpoint/database and TLS settings.','Check listener reachability then authenticate and verify server identity.','Exercise failover/reroute in a client test harness.','Check pooled connections and application transaction retry policy.'],precheck:['Obtain sanitized effective client configuration and driver build.','Protect credentials in configuration/trace; redact before sharing.','Use a distinct test alias so production routing is not modified.'],commands:[P('Catalog a test TCP node/database','CATALOG TCPIP NODE LABNODE REMOTE db2host.example.net SERVER 50000; CATALOG DATABASE SAMPLE AS LABDB AT NODE LABNODE AUTHENTICATION SERVER','Client administrator / Db2 client user','One isolated client catalog','Host/port/database verified; no password is included.','Node and database alias catalog entries are added.','`LIST NODE DIRECTORY`, `LIST DATABASE DIRECTORY`, then connect and query CURRENT SERVER.','Uncatalog only LABDB/LABNODE after confirming no other alias depends on LABNODE.'),P('Validate CLI driver','db2cli validate -dsn LABDB -connect','Client operator','CLI/ODBC driver on application test host','CLI driver installed; use secure credential prompt/config for authentication.','Validation prints driver configuration and successful connection or layer-specific failure.','Compare with application’s actual driver/version and database server identity.','No server change; remove only temporary test catalog entries.')],example:'`SQL1013N` indicates the requested alias is not found in the local catalog, while a `SQL30081N` reports a communication protocol error. Check client catalog first for the former; for the latter inspect endpoint, port, TLS and client/server traces.',expected:'A client connects to the intended server/database with a compatible driver and verified TLS/reroute behavior.',issues:[{symptom:'SQL1013N for an alias used by the application.',evidence:'effective process user, DB2INSTANCE/client profile and database directory listing.',cause:'Alias is absent in that user’s client catalog or app uses another config file.',fix:'Catalog the intended alias for the actual runtime identity and test target name.',avoid:'Cataloging an unverified server under the production alias.'},{symptom:'Failover reconnect works but transaction is duplicated.',evidence:'application idempotency key, commit outcome and client retry log.',cause:'Driver/pool retries connection without business-level outcome check.',fix:'Reconcile outcome by idempotency key and implement bounded transaction-aware retry.',avoid:'Assuming client reroute safely replays SQL.'}],lab:'Create an isolated alias to SAMPLE, test with db2cli validate, then change its host to a closed test port and capture the error layer. Restore correct host, connect and confirm CURRENT SERVER. Cleanup: uncatalog only the test alias/node.',question:'What does client reroute not prove?',answer:'It does not prove the database role changed, transaction outcome is known, or the application can safely replay a non-idempotent UOW. Verify server role and business request outcome.',diagram:'flowchart LR\nA[App driver and pool] --> C[Effective client catalog or URL]\nC --> N[Node host service port]\nN --> T[TLS and credentials]\nT --> D[Database alias and server identity]\nD --> R[Client reroute and retry behavior]',refs:[['IBM cataloging TCP/IP nodes','https://www.ibm.com/docs/en/db2/12.1.x?topic=clients-cataloging-tcpip-node'],['IBM client reroute','https://www.ibm.com/docs/en/db2/12.1.x?topic=parameters-alternate-server-database-parameter']],related:['A-05','D-01','D-04','D-06','J-03'] }),
L({id:'D-04',title:'TLS, certificates, keystores, native database encryption, and backup encryption',scope:['TLS server keydb/stash/certificate label/listener','DB2COMM TCPIP and SSL ports/restart','client trust and certificate rotation','Db2 native encryption DEK/MK/keystore','database-at-rest encryption versus encrypted backup','LOAD copy/log encryption','HADR key synchronization','key custody/restore drill'],branches:[['TLS in transit','Encrypts client/server or supported HADR network traffic.','TLS does not encrypt data files or backups at rest.'],['Native database encryption','Encrypts database files/logs using DEK protected by master key.','Keystore/key availability is required for restore and restart.'],['Encrypted backup','Encrypts image even when source database is not encrypted.','Compression/dedup after encryption is ineffective; key label must be recoverable.']],lifecycle:['Inventory data paths, backup paths, network paths and key owners.','Create/manage certificate or keystore with protected permissions.','Configure TLS listener and client trust; restart only as documented.','Test database/backups with keys in approved recovery location.','Rotate certificates/keys with overlap, restore proof and custody evidence.'],precheck:['Confirm release and GSKit/driver compatibility; inspect cipher/protocol policy.','Back up keystore/stash securely and prove access as Db2 service identity.','Schedule listener port cutover and test a rollback client.'],commands:[P('Enable server TLS listener','db2 update dbm cfg using SSL_SVR_KEYDB /secure/keystore/server.p12; db2 update dbm cfg using SSL_SVR_STASH /secure/keystore/server.sth; db2 update dbm cfg using SSL_SVCENAME 25001; db2set DB2COMM=SSL,TCPIP; db2stop; db2start','Instance owner/Db2 security administrator','Db2 server instance','Keystore/cert label provisioned; SSL and TCP use distinct ports; restart planned.','Instance starts with TLS and TCP/IP listeners configured.','Use a TLS client with approved CA; inspect connection and server diagnostics; confirm plaintext port policy.','Restore captured DBM CFG/DB2COMM and prior certificate only under change plan; no password is printed.'),P('Create encrypted backup','BACKUP DATABASE SAMPLE ENCRYPT TO /db2backup/enc','Backup authority; instance/DBA context','SAMPLE backup image at private destination','Native encryption configured and key is backed up/custodied.','Encrypted backup image is produced.','`db2ckbkp -h` validates image structure, then restore in isolated host proves key availability.','Retain image and key together under custody controls; delete only by retention policy.')],example:'A TLS handshake succeeds but a backup file is exposed on removable media. TLS cannot address that at-rest risk. Use backup encryption or protected media; separately retain the required master-key label/keystore for recovery.',expected:'Transport encryption, database encryption, backup encryption, key custody and restore are tested as independent controls.',issues:[{symptom:'Db2 will not start after SSL config change.',evidence:'db2diag, keydb/stash paths, owner permissions, label, SSL_SVCENAME/SVCENAME and port binding.',cause:'Unreadable keystore/stash, invalid label or conflicting listener ports.',fix:'Restore previous DBM CFG/DB2COMM and valid certificate; restart and retest baseline before retry.',avoid:'Disabling TLS globally without incident/change approval.'},{symptom:'Encrypted image cannot be restored on DR host.',evidence:'master key label, keystore type, key-manager reachability, image header and audit trail.',cause:'Recovery environment lacks correct key or key service/identity.',fix:'Retrieve the authorized key through custody process and test restore in isolated environment.',avoid:'Copying stash/password material into logs or ticket text.'},{symptom:'TLS validation fails after certificate rotation.',evidence:'client trust chain, SAN, time, driver TLS support and server label.',cause:'Missing CA chain, mismatched hostname, expired cert or downlevel client.',fix:'Install approved chain/route by DNS name and stage client support; verify both ends.',avoid:'Setting trust-all/hostname-ignore options.'}],lab:'In a disposable pair, create a local test certificate, configure a second TLS port, connect with trusted and untrusted clients, and restore an encrypted backup using a separately custodied test key. Cleanup certificates/images with secure deletion procedure; never reuse key material.',question:'What must a restore rehearsal prove beyond `db2ckbkp`?',answer:'That the destination can locate/authorize the encryption key and that Db2 can restore/open and validate the data. Image header integrity is not proof of key availability or successful recovery.',diagram:'flowchart TD\nC[Client TLS certificate trust] --> N[Encrypted network listener]\nN --> D[Db2 data and logs]\nD --> K[Native DEK protected by keystore MK]\nD --> B[Encrypted backup image]\nK --> R[Recovery host key custody and restore proof]',refs:[R.tls,R.encryption,['IBM encrypted backups','https://www.ibm.com/docs/en/db2/12.1.x?topic=encryption-encrypted-backups'],R.backup],related:['D-03','F-02','F-03','F-05','G-02'] }),
L({id:'D-05',title:'Auditing, RCAC, masks, LBAC, and sensitive-data controls',scope:['instance versus database audit logs','SECADM audit policy create/apply/archive/extract','RCAC row permission and column mask activation','LBAC component policy label/grant','audit data retention and privacy','utility/application access under controls','policy test identities and negative tests'],branches:[['Audit','Records selected events for accountability and evidence.','Audit collection is not itself access prevention.'],['RCAC','Filters rows and masks column values for SQL access.','Create controls before activation; no-data can be intended policy behavior.'],['LBAC','Uses security labels/components and rules to protect rows/columns.','LBAC labels are not roles or ordinary grants.']],lifecycle:['Classify the sensitive data and threat/access case.','Design role/user test matrix and expected visible rows/columns.','Create audit policy, row permissions/masks or LBAC components/labels.','Activate/associate policy and commit; test positive and negative identities.','Archive/extract audit evidence; review retention, storage and break-glass.'],precheck:['Use SECADM or approved delegated authority; never use SYSADM as a substitute for policy design.','Copy DDL and test query outputs for every identity.','Review package invalidation, utility behavior and data access by DBADM/DATAACCESS.'],commands:[P('Apply an audit policy','CREATE AUDIT POLICY APP_AUDIT CATEGORIES EXECUTE STATUS BOTH, CONTEXT STATUS BOTH ERROR TYPE NORMAL; AUDIT DATABASE USING POLICY APP_AUDIT; COMMIT;','SECADM','One disposable database','Confirm exact 12.1 SQL syntax/category intent; set log retention and privacy controls first.','Policy is committed and associated with the database.','Query SYSCAT.AUDITPOLICIES/AUDITUSE and generate a controlled audited event; archive/extract and inspect records.', 'Remove policy association and policy only after preserving required lab audit evidence.'),P('Row and column policy pattern','CREATE PERMISSION APP.REGION_ROWS ON APP.CUSTOMER FOR ROWS WHERE REGION = SESSION_USER ENFORCED FOR ALL ACCESS ENABLE; ALTER TABLE APP.CUSTOMER ACTIVATE ROW ACCESS CONTROL;','SECADM','Synthetic table with matching REGION identity values','This is a design pattern: validate exact Db2 LUW statement semantics and ensure no default-deny outage before activation.','Enabled permission filters visible rows after activation and commit.','Test as two distinct users, query row counts and inspect control catalog; test utilities/app packages too.','Deactivate row access control only through approved rollback after restoring expected least-privilege grants.'),P('LBAC label verification','SELECT A.grantee, B.secpolicyname, C.seclabelname FROM syscat.securitylabelaccess A JOIN syscat.securitypolicies B ON A.secpolicyid=B.secpolicyid JOIN syscat.securitylabels C ON A.seclabelid=C.seclabelid','SECADM/security auditor','LBAC grants in current database','Read-only catalog check; labels require complete component/policy design.','Granted security labels map to principals/policies.','Run read/write tests as authorized and unauthorized identities; verify data is blocked/visible as designed.','Revoke only lab security-label grants after documenting test evidence.')],example:'A user can query a protected table and receives fewer rows without an error; that can be correct RCAC behavior. Compare expected row set as both permitted and restricted identities. Separately verify audit policy produced evidence for the operation.',expected:'Control is activated, positive and negative tests match policy, and evidence is archived with least-privilege custody.',issues:[{symptom:'Users see zero rows after activating row access control.',evidence:'policy expression, session identity/group/role, commit state and per-role expected data.',cause:'Filter expression or identity mapping excludes all rows; activation may have occurred before a valid permission.',fix:'Pause release; use SECADM to correct/test policy on a copy, then reapply with staged activation.',avoid:'Deactivating controls as a production workaround without security approval.'},{symptom:'Audit is configured but no records are available.',evidence:'SYSCAT.AUDITUSE, policy scope/status, commit, event category, db2audit logs and retention destination.',cause:'Policy was not associated/committed, event category did not cover action or archive was not run.',fix:'Generate a controlled event and validate collection/archive/extract lifecycle.',avoid:'Assuming policy creation alone means auditing is active.'},{symptom:'Sensitive result differs between application and DBA query.',evidence:'SESSION_USER, RCAC expression, LBAC credentials, package identity and client role.',cause:'Data-centric filters apply to all access and identities differ.',fix:'Run controlled queries under same app identity and inspect policy path.',avoid:'Granting broad exemptions merely to make result sets match.'}],lab:'Create a three-row customer table with two regions and a masked test column. Build row permission and mask in a disposable database; test as two app users and SECADM. Add an audit policy, execute one SELECT and extract a record. Separately draw LBAC component/policy/label steps. Cleanup only lab objects and audit logs.',question:'What is the difference between audit and RCAC?',answer:'Audit produces evidence of selected activity; RCAC changes which rows/column values a session can see or modify. A system can need both, each independently tested.',diagram:'flowchart TD\nI[Identity and policy intent] --> A[Audit policy and association]\nI --> R[RCAC permissions and masks]\nI --> L[LBAC components policy labels grants]\nR --> T[Positive and negative query tests]\nL --> T\nA --> E[Archive and retain audit evidence]',refs:[['IBM audit facility','https://www.ibm.com/docs/en/db2/12.1.x?topic=activities-introduction-db2-audit-facility'],['IBM RCAC overview','https://www.ibm.com/docs/en/db2/12.1.x?topic=security-row-column-access-control-rcac'],['IBM LBAC labels','https://www.ibm.com/docs/en/db2/12.1.x?topic=lbac-security-labels'],['IBM authorization model','https://www.ibm.com/docs/en/db2/12.1.x?topic=model-authorization']],related:['D-02','D-04','D-06','E-05'] }),
L({id:'D-06',title:'Layer-by-layer security and connectivity failure diagnosis',scope:['client config and DNS','network/firewall/listener','TLS certificate trust','authentication provider','database alias and authorization','SQLCODE/SQLSTATE/client OS evidence','trace/privacy/evidence package'],branches:[['Name/route/port','Test before credentials to isolate reachability.','Ping/ICMP does not prove Db2 listener.'],['TLS/authentication','Test certificate chain and provider identity after TCP.','Do not bypass TLS or lower authentication.'],['Database/authorization','Verify CURRENT SERVER/USER and object access.','Successful connect does not prove grant or RCAC visibility.']],lifecycle:['Start from exact client symptom and timestamp.','Map client driver/config and DNS to endpoint.','Test TCP listener then TLS handshake.','Test authentication then database alias and CURRENT USER/SERVER.','Test one least-privilege SQL operation and capture sanitized diagnostics.'],precheck:['Use one reproducible client and test identity.','Collect client driver, OS, server Db2 level, resolved IP/port and UTC timestamps.','Redact statements, user names, tokens and certificates before sharing.'],commands:[P('Client endpoint resolution and route','Resolve-DnsName db2host.example.net; Test-NetConnection db2host.example.net -Port 50000','Windows client operator','Application client host','PowerShell on Windows; Linux uses getent/nc; use agreed host and port.','DNS address and TCP test result are displayed.','Pair with server listener and firewall counters; do not conclude TLS/auth from TCP alone.','Read-only.'),P('Server log evidence','db2pd -db SAMPLE -connections; db2pd -db SAMPLE -applications','Instance owner','Current instance diagnostic log','Read-only filter; exact `db2diag` options vary by Db2 release—confirm installed help.','Recent severe diagnostic records are selected.','Correlate record timestamp/EDUID/member with same client retry and server listener evidence.','Do not edit or truncate diagnostic logs.')],example:'A client gets SQL30081N reason `10061` on Windows. Treat the client OS value as a transport clue; check listener bind and port first, then server-side firewall/network. Do not jump to password reset or alias change.',expected:'The earliest failing layer is named and corrected, then the full path is retested through SQL and application behavior.',issues:[{symptom:'SQL30081N transport error.',evidence:'client protocol reason, DNS answer, TCP probe, listener, firewall and paired db2diag.',cause:'Port blocked/unbound, endpoint stale, network reset, or TLS listener mismatch.',fix:'Repair the earliest network/listener layer and repeat a controlled port then Db2 connection test.',avoid:'Opening all ports or rotating credentials without auth evidence.'},{symptom:'Connection succeeds but query returns no protected rows.',evidence:'CURRENT SERVER/USER, role, RCAC/LBAC and audit controls.',cause:'Authorization/data filter is active, or connected database differs.',fix:'Confirm target then evaluate policy with an approved test identity.',avoid:'Weakening RCAC to diagnose a connection issue.'}],lab:'Walk four intentionally distinct cases on a test pair: wrong alias, blocked test port, untrusted CA and valid connection with missing SELECT. For each record symptom, proof, owner and layer-specific fix. Cleanup: restore aliases/firewall test rule/certificate and remove test grants.',question:'Why diagnose connectivity in order?',answer:'Testing each layer in sequence prevents a later-layer guess from obscuring the first failure. A TCP success only advances the investigation to TLS/authentication/catalog/authorization.',diagram:'flowchart LR\nC[Driver and client catalog] --> D[DNS] --> R[Route firewall NAT] --> L[Listener]\nL --> T[TLS trust] --> A[Authentication]\nA --> B[Alias and database]\nB --> Z[Authorization RCAC LBAC]',refs:[['IBM troubleshooting Db2 servers','https://www.ibm.com/docs/en/db2/12.1.x?topic=techniques-troubleshooting-db2-servers'],R.tls,R.auth12],related:['A-05','D-01','D-02','D-03','D-04'] })
);

lessons.push(
L({id:'E-01',title:'Incident scope, timeline, baseline, and evidence quality',scope:['impact and scope boundary','UTC timeline and clock skew','baseline and comparison window','evidence chain and reproducible commands','customer/privacy redaction','hypothesis log and stop criteria'],branches:[['Service restoration','Prioritize customer impact and reversible restoration step.','Do not destroy evidence when a safe copy is possible.'],['Root-cause analysis','Compare event against known-good interval and change history.','A single coincident event is not causation.'],['Escalation','Package enough timestamped evidence for next owner/support.','Avoid broad FODC collection unless resource/storage planned.']],lifecycle:['Establish incident lead, impact, start and current state.','Name affected database/instance/member/application/site.','Capture time-aligned baseline and recent changes.','Write hypotheses with evidence that would disprove them.','Mitigate safely, verify service/data, and preserve final timeline.'],precheck:['Synchronize UTC timestamps and record any clock offset.','Use read-only commands first; record command, host, user and return code.','Redact secrets and minimize customer data in captures.'],commands:[P('Incident context bundle','Get-Date -Format o; hostname; whoami; db2level; db2 get instance','On-call DBA/host operator','Client or server as noted per command','PowerShell example; Linux uses `date -Is`, `hostname`, `id`; capture target explicitly.','Timestamp, host, actor, Db2 release and instance are recorded.','Compare with application/OS clocks and verify database alias/server separately.','Read-only; preserve original output and copy before redaction.'),P('Bounded baseline sample','db2pd -db SAMPLE -applications; db2pd -db SAMPLE -transactions','Instance owner','SAMPLE current member','Read-only, bounded one-time snapshot; do not run broad loops without interval limit.','Application and transaction states are emitted.','Capture again at a known interval and compare handles/states.','Read-only; stop collection if it materially affects an unhealthy server.')],example:'At 10:04 UTC users report timeout. Host clock is 90 seconds ahead of app logs. Record the offset before ordering events. The timeline can then align listener restart, client retry and Db2 diagnostic records without falsely reversing cause/effect.',expected:'An incident packet has impact, target, timeline, baseline, hypothesis evidence and safe escalation boundary.',issues:[{symptom:'Different teams report events in an impossible order.',evidence:'NTP status, timezone, log timestamp fields and collector clock.',cause:'Host/client clock drift or local timezone conversion.',fix:'Normalize to UTC and preserve original timestamp plus measured offset.',avoid:'Editing original diagnostic timestamps.'},{symptom:'Evidence bundle contains credentials or customer rows.',evidence:'Search filenames/output for tokens, authorization IDs and data values.',cause:'Unfiltered trace/export or shell history included secrets.',fix:'Restrict access, redact a working copy and follow security retention/incident policy.',avoid:'Sending raw package to broad ticket or email distribution.'}],lab:'Create a timeline for a fictional connectivity outage with client, firewall, listener and db2diag times across three timezones. Normalize to UTC and mark uncertainty. Cleanup: redact invented user identifiers in the report.',question:'What makes a baseline useful?',answer:'It matches the same workload and scope, includes units/time window, and can be compared with a known-good state; a random snapshot is context, not a baseline.',diagram:'flowchart TD\nI[Impact and scope] --> T[UTC timeline and changes]\nT --> B[Known-good baseline]\nB --> H[Hypotheses and disproving evidence]\nH --> M[Safe mitigation]\nM --> V[Service data and recovery proof]',refs:[R.diagnostic,R.monitor],related:['E-02','E-03','E-06','I-01','K-01'] }),
L({id:'E-02',title:'db2diag.log, notification logs, diagnostic signatures, and FODC',scope:['diagnostic path/rotation/diagsize','db2diag filters and record fields','notification log correlation','EDUID/member/timestamp/signature','FODC trigger/collection size','db2support package and privacy','evidence preservation'],branches:[['Log read','Use db2diag filters around a precise time/EDUID.','Do not grep a whole huge rotated tree without bounds.'],['FODC','Collect first-occurrence evidence when a specific hang/crash scenario fits.','FODC may gather large sensitive files.'],['db2support','Package evidence for IBM support after scoped collection.','Review contents and remove secrets only via approved process.']],lifecycle:['Resolve `DIAGPATH` and log rotation settings.','Filter logs by incident time, level, component, EDUID/member and database.','Correlate notification entries with OS/app evidence.','Choose FODC type based on symptom and IBM instruction.','Run db2support and review/transfer by secure support channel.'],precheck:['Record exact `db2level`, instance, DIAGPATH and log size.','Check disk capacity before support capture.','Do not alter diagsize or remove FODC/log directories during incident.'],commands:[P('Filter recent severe records','db2diag -g "LEVEL: Severe" -H 2d','Instance owner','Current diagnostic log plus rotation policy','Use installed command help to verify option syntax; capture original unfiltered file separately.','Filtered records include timestamp, process/EDUID, database/member and message tokens.','Correlate matching interval with application and OS log.','Read-only; preserve copies and avoid truncation.'),P('Support data collection','db2support /secure/case/CASE-2026-001 -d SAMPLE -c','Instance owner/authorized support collector','SAMPLE and local instance evidence','Check capacity/privacy and IBM case scope first; use exact installed syntax.','Support package is created with collection summary.','Inspect file list, size and sensitive fields; verify upload destination and case access.','Remove local copy only under retention policy after confirmed secure transfer.')],example:'Repeated `ADM` records with the same EDUID and database context narrow an engine symptom. A matching kernel I/O error at the same UTC minute points to the host/storage layer; preserve both before asking for restart.',expected:'A concise evidence bundle points to the first known failure and can be securely reviewed by support.',issues:[{symptom:'db2diag.log appears incomplete after a long incident.',evidence:'diagsize, rotated file names, DIAGPATH and FODC directory timestamps.',cause:'Rotation removed logs outside configured span or evidence is in another instance path.',fix:'Collect all relevant rotated files and support data before changing log retention.',avoid:'Increasing DIAGSIZE during a full filesystem without capacity plan.'},{symptom:'FODC collection consumes unexpected disk or contains sensitive material.',evidence:'collector status, destination size, file list and access controls.',cause:'Capture scope is wider than incident need or retained trace includes values.',fix:'Stop only via documented collector control, secure destination, inspect and minimize transfer.',avoid:'Uploading an unreviewed package to an unrestricted location.'}],lab:'Use a sample diagnostic log from IBM documentation or a disposable instance. Filter a known timestamp/signature, map EDUID/member, and create an evidence checklist. Simulate low disk by quota planning only; do not fill production logs.',question:'Why is db2support not the first reflex for every incident?',answer:'The package can be large and sensitive; choose FODC/support collection based on a concrete failure signature and capacity/privacy plan.',diagram:'flowchart LR\nD[db2diag rotated files] --> F[Time EDUID member filters]\nN[Notification records] --> F\nO[OS and application logs] --> F\nF --> X{Need FODC?}\nX -->|yes| C[Bounded capture]\nX -->|no| E[Preserve selected evidence]\nC --> S[Review db2support package]',refs:[R.diagnostic,R.fodc,['IBM db2support tool','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-db2support']],related:['E-01','E-03','K-01','K-02'] }),
L({id:'E-03',title:'db2pd, monitor table functions, and snapshots',scope:['point-in-time db2pd','current MON_GET functions','legacy SNAP_GET monitoring','scope/member selectors','counter deltas and resets','monitor privileges','low-overhead and empty-result interpretation'],branches:[['db2pd','Use engine-oriented local evidence without SQL connection for many options.','Member-local unless global/member scope is requested.'],['MON_GET','Use SQL reporting for current database metrics.','MON routines generally report connected database; specify columns.'],['SNAP_GET','Retain for legacy scripts that require it.','Older infrastructure; migrate where possible.']],lifecycle:['Choose point-in-time, SQL metric, or historical event evidence.','Select host/database/member and collector identity.','Record timestamp, units and exact filters.','Repeat for rates/counters and handle resets.','Store result with scope and collection overhead.'],precheck:['Check command scope in DPF/pureScale; avoid assuming one member is cluster-wide.','Use least-privilege monitor role and named output columns.','Set interval and count to bound repeated collection.'],commands:[P('Local engine snapshot','db2pd -db SAMPLE -applications -transactions','Instance owner','Active SAMPLE local member','Read-only; first command can run without a database connection for many db2pd options; verify option support.','Current application and transaction view is printed.','Compare with MON_GET_CONNECTION and host process evidence.','Read-only; do not poll aggressively on stressed engine.'),P('SQL monitor sample','SELECT application_handle, client_applname, client_hostname FROM TABLE(mon_get_connection(NULL,-2)) AS c','Database user with monitor privilege','Connected database; all supported member scope for -2','Name columns explicitly; current database must be connected.','Current connection rows are returned.','Take two timestamped samples or join to unit-of-work/lock functions for context.','Read-only; migrate SNAP_GET consumers after comparing scope/privileges.')],example:'`db2pd -db SAMPLE -applications` on one DPF host is local evidence. MON_GET with member selector `-2` can provide broader current database scope. Compare member columns and do not sum duplicate global metrics.',expected:'A metric is tagged as current gauge, cumulative counter, or delta and has explicit database/member/time scope.',issues:[{symptom:'db2pd says database is not active on local member.',evidence:'local catalog, active member list, command host and `db2instance -list`.',cause:'Wrong host/member or database not active in local scope.',fix:'Run on correct host/member or use documented global scope; verify activation.',avoid:'Assuming an empty/local error means whole database is down.'},{symptom:'Monitor SQL returns an authorization error.',evidence:'connected ID, monitor authority, function scope and SQLSTATE.',cause:'Query identity lacks required monitor privilege or view access.',fix:'Use least-privilege monitor privilege approved for target; retest with explicit columns.',avoid:'Granting DBADM to monitoring service.'}],lab:'Collect a one-time db2pd sample and a MON_GET_CONNECTION sample against disposable SAMPLE. Add second samples five seconds apart, classify counters/gauges, and document member scope. Cleanup: disconnect test session.',question:'When should legacy snapshots be retained?',answer:'Only where an existing integration still depends on them or the migrated monitoring interface does not answer a needed scope; document older infrastructure and comparison.',diagram:'flowchart TD\nQ[Operational question] --> P[db2pd point-in-time engine view]\nQ --> M[MON_GET SQL metrics]\nQ --> S[SNAP_GET legacy interface]\nP --> T[Host/member scope]\nM --> D[Connected database scope]\nS --> V[Migration and parity check]',refs:[R.monitor,R.mon,['IBM db2pd reference','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-db2pd-monitor-troubleshoot-db2-engine-activities']],related:['E-04','E-05','E-06','C-03'] }),
L({id:'E-04',title:'Connections, applications, agents, transactions, and long-running work',scope:['application handles and client identity','agent/EDU state','UOW start and log usage','active statement and package','blocking and transaction age','cancellation/force consequences','pool cleanup and request proof'],branches:[['Idle connection','Inspect last activity and client pool owner.','Do not force every idle pooled session.'],['Long active UOW','Review statement, locks, log use and commit boundary.','Age alone does not prove a hung transaction.'],['Intervention','Prefer app cancel/transaction-safe action; force only after impact review.','Force can trigger rollback and hold resources.']],lifecycle:['Find handle and client identity.','Inspect EDU/statement/UOW and lock chain.','Ask owner whether request is live and whether cancellation is safe.','If approved, cancel/force the specific handle and monitor rollback.','Verify application recovery and commit/data outcome.'],precheck:['Capture handle, member, auth ID, client host, app name and UOW start.','Check whether application owns a larger transaction or connection pool.','Estimate rollback time/log consequence before forced action.'],commands:[P('Find applications and transactions','db2pd -db SAMPLE -applications -transactions; db2 list applications show detail','Instance owner','SAMPLE active member','Read-only; choose database/member and capture UTC.','Application handles, status, UOW and client details are shown.','Correlate with MON_GET_ACTIVITY/UNIT_OF_WORK and application owner.','No state change; preserve output before intervention.'),P('Force one approved handle','FORCE APPLICATION (12345)','Instance owner/authorized administrator','Application handle 12345 in verified database','Example handle is synthetic; recheck handle/member/owner immediately before action and obtain incident authorization.','Connection is terminated and rollback begins; client receives disconnect.','Watch transaction/log/lock state until rollback completes; ask app owner to verify outcome.', 'Force is not reversible. If commit outcome is uncertain, reconcile by request key; do not force additional handles to clear symptoms.')],example:'A 90-minute UOW blocks a batch. The session owner confirms it is abandoned and idempotent. Record handle and key, stop the worker at its source, then force that one handle and watch rollback; only close incident after locks/log space recover.',expected:'The active request is identified by handle and owner; cancellation decision accounts for rollback and business commit outcome.',issues:[{symptom:'`FORCE APPLICATION` returns but lock waits remain.',evidence:'rollback state, other blocker handles, lock tree and transaction age.',cause:'Forced unit is rolling back or a different blocker remains.',fix:'Track rollback to completion and identify current root blocker before another action.',avoid:'Repeatedly forcing waiters instead of the owner.'},{symptom:'Aged transaction belongs to a connection pool and app denies ownership.',evidence:'client metadata, app deployment/host, connection pool and request correlation ID.',cause:'Missing client attribution or leaked connection/work unit.',fix:'Use app logs and pool admin to locate owner; preserve state until cancellation is approved.',avoid:'Killing the whole Db2 instance to remove one unknown transaction.'}],lab:'Create two lab sessions: one holds a row lock and one waits. Observe handles/UOWs, cancel the waiter, then use a second disposable run to terminate only the blocker and watch rollback. Verify no open test locks remain.',question:'What should be checked after forcing an application?',answer:'Rollback completion, released locks/log space, client pool state, and business outcome keyed to the request. A force return alone does not prove transaction resolution.',diagram:'flowchart TD\nC[Connection handle and client] --> A[Agent EDU activity]\nA --> U[UOW age log usage commit state]\nU --> L[Lock chain and blocker]\nL --> D{Owner approves cancel?}\nD -->|yes| X[Cancel or force one target]\nX --> R[Rollback and application outcome]',refs:[R.mon,R.diagnostic],related:['B-05','H-05','K-01'] }),
L({id:'E-05',title:'Event-monitor families, targets, lifecycle, storage, and interpretation',scope:['database/table/connection/statement/transaction/activity/statistics events','lock/deadlock/threshold/package-cache/change-history families','table/unformatted/file/pipe targets','create activate flush/deactivate/drop lifecycle','storage overhead/privacy and retention','no-data and lost-event causes'],branches:[['Point-in-time','MON/`db2pd` answers what is happening now.','Cannot reconstruct an event that already ended.'],['Event monitor','Captures selected event history at configured detail.','Requires event type, target, activation scope and retention.'],['Lock event monitor','Captures waits/timeouts/deadlocks with participants and activities.','SQL history/values increase overhead and privacy exposure.']],lifecycle:['Define question and event type/detail threshold.','Choose output target and size/retention plan.','Create monitor, activate collection at database/workload scope.','Generate controlled event and verify output.','Deactivate/flush, interpret, archive/prune and drop object/table only if approved.'],precheck:['Check target table space/file capacity and protected access.','Avoid collecting statement values unless needed and privacy-approved.','Confirm correct workload/database scope and member coverage.'],commands:[P('Create a lock event monitor','CREATE EVENT MONITOR LOCKLAB FOR LOCKING WRITE TO TABLE; SET EVENT MONITOR LOCKLAB STATE 1;','DBADM or SQLADM','Current database, lock events','Create only in disposable database; configure needed workload/database event scope and retention.','Lock event output tables exist and monitor is active.','Generate one test lock event, query output/control rows, and verify timestamp/participants.','Deactivate with `SET EVENT MONITOR LOCKLAB STATE 0`; drop monitor and associated tables only after export/retention check.'),P('Create statement event monitor to file','CREATE EVENT MONITOR STMTLAB FOR STATEMENTS WRITE TO FILE \'/db2diag/evmon\'; SET EVENT MONITOR STMTLAB STATE 1;','DBADM or SQLADM','Current database and server output directory','Confirm file target syntax/path, owner permission, disk quota and privacy before activation.','Event files created on events; monitor status active.','Generate one known statement and verify event output with formatter; compare file count/bytes.','Deactivate and flush using documented family lifecycle; preserve/rotate files before cleanup.')],example:'A lock event monitor created successfully but outputs no data because the capture setting/workload scope was not enabled or no qualifying lock event occurred. Test lifecycle with a deliberate lock in a lab before treating empty tables as failure.',expected:'Monitor definition, event type, output target, activation state, event capture scope and retention are all known.',issues:[{symptom:'Event tables are empty although the event monitor is active.',evidence:'SYSCAT.EVENTMONITORS, SET EVENT MONITOR state, workload/database capture parameters, target/member.',cause:'Monitor exists but capture was not enabled at required scope or event threshold was not met.',fix:'Enable the specific event data source and trigger a controlled qualifying event.',avoid:'Broadly enabling statement values on every workload.'},{symptom:'Event monitor stops or misses events as disk fills.',evidence:'file/table-space capacity, PCTDEACTIVATE/target status, overflow records.',cause:'Output target full or storage growth unbounded.',fix:'Deactivate/rotate/export then prune according to retention and increase bounded capacity.',avoid:'Dropping output tables before preserving evidence.'}],lab:'Create a lock event monitor in a lab, activate capture, induce a short lock wait and one deadlock between test sessions, then query formatted events. Deactivate and archive outputs. Cleanup monitor plus only its lab tables/files.',question:'Why are event monitors not a replacement for MON_GET?',answer:'MON_GET is a current database observation; event monitors capture selected events over time. Their scopes, storage, overhead and lifecycle differ.',diagram:'flowchart LR\nQ[Historical question] --> F[Choose event family and detail]\nF --> T[Choose table UE file or pipe target]\nT --> C[Create and activate at scope]\nC --> E[Event occurs]\nE --> X[Format inspect archive prune]\nN[Current state] --> M[MON_GET or db2pd]',refs:[R.evmon,R.locks,R.monitor],related:['E-03','E-06','D-05','H-05'] }),
L({id:'E-06',title:'Db2/OS observability, metric definitions, alerts, and operational reporting',scope:['counter/gauge/rate/histogram definitions','database/member/host dimensions','CPU memory I/O network log space metrics','sampling/reset and source freshness','alert thresholds seasonality and baseline','dashboard data lineage','false-positive/no-data detection','symptom to runbook mapping'],branches:[['Gauge','Measure current value such as bytes used or active connections.','Threshold should consider capacity and duration.'],['Counter/rate','Use interval delta or monotonic rate.','Handle reset, restart, wrap and member scope.'],['Histogram/latency','Report percentiles from request-level samples.','Average latency hides tail behavior.']],lifecycle:['Define SLI/SLO and exact metric name/unit/scope.','Collect aligned host/Db2/application samples.','Set threshold duration, reset and no-data semantics.','Route alert to a runbook and accountable owner.','Review false positives and outcome after each incident.'],precheck:['Inventory source, exporter version, scrape interval and labels.','Confirm sample freshness and metric reset behavior.','Avoid combining host and member series without dimensions.'],commands:[P('Host interval telemetry','sar -u 1 5; sar -r 1 5; sar -d 1 5','Linux observability operator','One host over five seconds','sysstat installed; align sample with Db2 dashboard window.','CPU, memory and device samples appear with interval data.','Compare exporter series, units and timestamp; check gaps.','Read-only; no alert threshold edits from a single sample.'),P('Db2 log metric query','SELECT member, total_log_used, total_log_available FROM TABLE(mon_get_transaction_log(-2)) AS l','Database monitor user','Current database member scope','Column/function signature should be confirmed on installed fix pack.','Current log usage/available metrics by member are returned.','Compute percent used with units and compare log filesystem/active UOWs.','Read-only; do not alert on total bytes without capacity denominator.')],example:'An alert fires when log usage exceeds 85%. Validate whether it is a gauge sampled every 30 seconds, whether delayed-member data is stale, and whether the denominator is per member. A single stale series should trigger a telemetry-health alert, not a log-full incident.',expected:'Every alert has metric definition, unit, scope, window, threshold rationale, owner, and runbook.',issues:[{symptom:'Dashboard appears normal but Db2 is slow.',evidence:'scrape freshness, exporter errors, member labels and app latency source.',cause:'Telemetry gap or aggregation hid a hot member/tail latency.',fix:'Repair collection and compare raw per-member/per-host series; preserve app timing.',avoid:'Raising thresholds to silence missing-data symptoms.'},{symptom:'Alert storms on a counter reset after restart.',evidence:'process restart, counter monotonicity and scrape timestamps.',cause:'Counter reset interpreted as a negative/huge rate.',fix:'Apply reset-aware rate calculation and test restart boundary.',avoid:'Treating lifetime counter as instantaneous load.'}],lab:'Define an alert for log capacity and one for query latency. For each write unit, scope, sampling interval, sustained threshold, reset/no-data condition, owner and response. Feed synthetic reset and missing data into a spreadsheet/test harness; do not change production alert routes.',question:'What is the difference between a zero metric and no metric?',answer:'Zero is a measured value; no metric may indicate missing collection, scope mismatch or an inactive series. Alerting must distinguish them.',diagram:'flowchart TD\nS[Source Db2 OS app] --> M[Metric definition unit scope]\nM --> C[Collector interval freshness]\nC --> A[Alert window threshold no-data]\nA --> R[Owner and runbook]\nR --> E[Incident outcome feedback]',refs:[R.mon,R.monitor,['Linux sar manual','https://man7.org/linux/man-pages/man1/sar.1.html']],related:['E-01','E-03','E-05','I-01','J-05'] })
);

lessons.push(
L({id:'C-01',title:'SQL, transactions, isolation, SQLCODE, and SQLSTATE fundamentals',scope:['read-only SELECT and parameter markers','INSERT UPDATE DELETE guardrails','COMMIT ROLLBACK SAVEPOINT and autocommit','isolation levels and anomalies','cursor locks and transaction boundaries','SQLCODE SQLSTATE and token interpretation'],branches:[['Read-only query','Use a bounded predicate and explicit columns.','Avoid unbounded scans on shared systems.'],['Transactional DML','Use a transaction boundary and verify affected rows before commit.','Autocommit can commit each statement before a later check.'],['Isolation','Choose based on consistency requirement and wait risk.','Do not reduce isolation to hide a data race.']],lifecycle:['Prepare a statement and identify target rows.','Begin or verify transaction mode.','Execute one scoped unit of work.','Check row count and concurrent effects.','Commit only on expected result; otherwise rollback/savepoint.'],precheck:['Use synthetic schema/table and bind parameter types explicitly.','Check autocommit and isolation in the actual client/driver.','Capture before-row count or primary-key values.'],commands:[P('Bounded change with verification','UPDATE APP.INVENTORY SET quantity = quantity - 2 WHERE sku = 70021 AND quantity >= 2; SELECT sku, quantity FROM APP.INVENTORY WHERE sku = 70021;','Authorized application/database user','One synthetic inventory row','Confirm primary key and expected quantity; use an explicit transaction with autocommit disabled.','One row changes only if stock is sufficient; the SELECT returns the resulting quantity.','Compare row count and data with the request before COMMIT; otherwise ROLLBACK.','Rollback the open UOW; after commit, use a reviewed compensating transaction, not assumed undo.'),P('Transaction checkpoint','SAVEPOINT before_edit ON ROLLBACK RETAIN CURSORS; ROLLBACK TO SAVEPOINT before_edit','Database user in active transaction','Current lab unit of work','Use only in a session that owns the savepoint; verify client syntax/driver behavior.','Changes after the savepoint are undone while earlier work remains.','Requery rows and confirm expected pre-savepoint values.','Rollback the full transaction if state is uncertain.')],example:'A guarded UPDATE affects zero rows. That is a meaningful outcome: the row may be absent or quantity may already be below the requested decrement. Read the key row and stop rather than remove the predicate.',expected:'Transaction boundary, row count, isolation, SQLCODE and SQLSTATE are interpreted together.',issues:[{symptom:'SQL0911N after a statement.',evidence:'SQLSTATE, reason code/token, deadlock/timeout event, transaction age and blocker.',cause:'Statement was selected as a deadlock victim or timed out waiting for a lock.',fix:'Retry only the complete idempotent business unit after resolving contention; verify commit outcome.',avoid:'Blindly retrying a non-idempotent update after an ambiguous client timeout.'},{symptom:'SQL0803N unique-key violation on insert.',evidence:'SQLCODE/SQLSTATE, constraint/index name, key values and existing row.',cause:'Duplicate key or application retry repeated a successful insert.',fix:'Read by business key, reconcile request outcome and use idempotency key.',avoid:'Dropping the unique index to make the insert pass.'}],lab:'Create a lab inventory row and run a guarded decrement with autocommit off. Induce an insufficient-stock zero-row update; test COMMIT and ROLLBACK separately. Cleanup: restore or delete only the synthetic row.',question:'Why is a client timeout an ambiguous transaction outcome?',answer:'The server may have committed before the client lost its response. Reconnect and query by a stable business/idempotency key before retrying.',diagram:'flowchart TD\nQ[Prepare and validate target rows] --> T[Begin UOW and set isolation]\nT --> D[Execute scoped DML]\nD --> R{Row count and SQLSTATE expected?}\nR -->|yes| C[Commit and verify]\nR -->|no| B[Rollback or savepoint]',refs:[R.mon],related:['H-05','D-03','J-03'] }),
L({id:'C-02',title:'Schemas, tables, data types, indexes, constraints, and dependencies',scope:['schema/authorization boundaries','data types null/default identity/generated columns','PK unique FK check constraints','composite/unique/partitioned index tradeoffs','views aliases MQTs triggers routines packages','dependency inspection and DDL rollback','LOB XML temporal and organized-table restrictions'],branches:[['Table definition','Choose types/nullability/key rules from business semantics.','Changing a type may rewrite data and invalidate dependents.'],['Index design','Key order follows predicate, join and ordering patterns.','Every index consumes storage and adds write/maintenance cost.'],['Dependencies','Capture object graph before DDL and deploy in dependency order.','Drop/recreate is not a safe rollback if data or grants are lost.']],lifecycle:['Model keys and domain values.','Create schema/table and integrity rules.','Add only justified indexes and dependent objects.','Inspect catalog and explain dependencies.','Deploy change in a transaction/change window and validate applications.'],precheck:['Export DDL and grants before change.','Check object owner, dependent packages/views/triggers and row count.','Review special types and table organization limitations for target Db2 level.'],commands:[P('Create a keyed object','CREATE TABLE APP.ORDER_LINE (order_id BIGINT NOT NULL, line_no SMALLINT NOT NULL, sku INTEGER NOT NULL, quantity DECIMAL(9,2) NOT NULL CHECK (quantity > 0), PRIMARY KEY (order_id, line_no));','Authorized schema owner','APP schema in disposable database','Schema exists; choose numeric precision from domain rules.','Table and PK/check constraints are created.','Inspect SYSCAT.TABLES, SYSCAT.COLUMNS, SYSCAT.TABCONST and insert valid/invalid lab rows.','Drop only the empty lab table after checking dependents.'),P('Index and dependency capture','CREATE INDEX APP.IX_ORDER_LINE_SKU ON APP.ORDER_LINE (sku, order_id);\nSELECT tabschema, tabname, type FROM syscat.tables WHERE tabschema = \'APP\' ORDER BY tabname;','Schema owner and catalog reader','APP.ORDER_LINE','Use plan evidence to justify key order; SQL query is read-only.','Index exists; catalog inventory lists objects in APP.','Explain representative query and compare index usage after workload sample.','Drop only the index if plan/workload proof shows it is unnecessary.')],example:'For `WHERE sku=? AND order_id=?`, a `(sku, order_id)` index may filter efficiently, while a primary key `(order_id, line_no)` serves a different access path. Measure reads and writes before retaining both.',expected:'Object DDL, type/null semantics, constraints, grants, indexes, and dependent objects are captured and verified.',issues:[{symptom:'Application insert fails after adding NOT NULL column.',evidence:'SQLCODE/STATE, deploy order, default/generated behavior and application binds.',cause:'Existing rows or insert statements do not provide a legal value.',fix:'Use a staged migration: compatible default/backfill, deploy app, then enforce constraint after validation.',avoid:'Adding NOT NULL with an arbitrary value that misrepresents existing data.'},{symptom:'New index does not appear in chosen plan.',evidence:'statistics timestamp/cardinality, predicates/types and EXPLAIN output.',cause:'Stale/missing stats, incompatible expression/type, or cost favors another access path.',fix:'Update relevant statistics and inspect estimates; test rewrite/index only in workload replay.',avoid:'Forcing an index before understanding plan estimates.'}],lab:'Build APP.ORDER_LINE with a primary key, check constraint and secondary index. Attempt one invalid row, read the exact SQLSTATE, then explain a filter on sku. Cleanup in dependency order: remove dependents, index and table.',question:'Why can adding an index reduce overall throughput?',answer:'It adds storage, logging and maintenance to inserts/updates/deletes, plus backup and REORG work. Compare total workload benefit against write cost.',diagram:'flowchart TD\nS[Schema and authorization] --> T[Table columns and constraints]\nT --> I[Index access paths]\nT --> D[Views triggers routines packages]\nD --> A[Application bind and deploy order]',refs:[R.monitor,['IBM Db2 catalog views','https://www.ibm.com/docs/en/db2/12.1.x?topic=views-catalog-views']],related:['C-03','C-07','H-02','H-04','I-04'] }),
L({id:'C-03',title:'Db2 catalogs, administrative views, monitor functions, and snapshots',scope:['SYSCAT metadata versus SYSIBM internals','read-only inventory queries','administrative views','MON_GET current measures','legacy SNAP_GET and cumulative counters','db2pd engine evidence','catalog/version/privilege/no-data interpretation'],branches:[['Catalog query','Use for stable object definitions and privileges.','Catalog metadata is not a live workload sample.'],['MON table function','Use for current or cumulative database metrics with member scope.','Counter totals need interval deltas; newer output columns can be added.'],['db2pd/snapshot','Use engine-level or legacy evidence where it adds value.','Snapshot monitor is older and no longer enhanced.']],lifecycle:['Ask whether the question is metadata or runtime behavior.','Select catalog, MON function, db2pd or event evidence.','Name columns explicitly and specify scope/member.','Take two samples when rate/delta is required.','Explain empty result, privileges and data freshness.'],precheck:['Capture release and privileges of the querying identity.','Avoid SELECT * from monitor functions; future versions can add columns.','Record sample timestamps and member IDs.'],commands:[P('Object inventory','SELECT tabschema, tabname, type, create_time FROM syscat.tables WHERE tabschema = \'APP\' ORDER BY tabname;','Catalog reader','Current connected database catalog','Read-only SELECT; schema is a synthetic filter.','APP object names/types/timestamps are listed.','Compare object count with DDL/deployment inventory.','Read-only; grant minimum catalog access if rows are hidden.'),P('Live connection sample','SELECT application_handle, client_hostname, client_applname FROM TABLE(mon_get_connection(NULL,-2)) AS c','User with monitor authority','Connected database member scope','MON_GET is for connected database; specify needed columns.','Current connections, clients and application names appear.','Repeat after interval for state change; compare with db2pd on member.','Read-only; event/statement text collection has privacy and overhead implications.')],example:'A query against SYSCAT.TABLES returns all tables, while MON_GET_CONNECTION returns no rows. These outputs answer different questions; if the database has no connections besides the observer, empty runtime data can be correct.',expected:'Every result has a defined scope, timestamp and metric meaning; catalog inventory is not mistaken for performance telemetry.',issues:[{symptom:'Monitor query returns no rows while users report active sessions.',evidence:'connection alias, monitor privilege, member scope and server identity.',cause:'Connected to wrong database/member or monitor function scope/privilege mismatch.',fix:'Verify current server/user and query supported member scope; compare db2pd on correct host.',avoid:'Assuming empty means no activity.'},{symptom:'Counter increased but team calls it a rate.',evidence:'two timestamped samples, database/member resets, metric definition.',cause:'Cumulative counter interpreted without a time interval.',fix:'Compute delta per elapsed seconds and handle reset/wrap semantics.',avoid:'Alerting on lifetime totals as if they were per-second metrics.'}],lab:'Run an object catalog query and a MON_GET_TABLESPACE query at two timestamps. Label which fields are definitions, gauges, or cumulative counters; explain why a zero-row monitor result can be valid.',question:'Why should queries name columns rather than use `SELECT *` on MON routines?',answer:'IBM can add output columns in later releases; explicit projection keeps scripts stable and documents which metrics matter.',diagram:'flowchart LR\nQ[Question] --> M{Definition or live state?}\nM -->|Definition| C[SYSCAT metadata]\nM -->|Live| N[MON table functions]\nM -->|Engine detail| P[db2pd]\nN --> T[Timestamp and scope] --> R[Delta or interpretation]',refs:[R.monitor,R.mon],related:['E-03','E-05','E-06','C-02'] }),
L({id:'C-04',title:'Tablespaces, storage groups, containers, AUTORESIZE, and space reclamation',scope:['regular/large/temp/system spaces','automatic storage versus DMS/SMS legacy','page extent and bufferpool mapping','storage groups and containers','AUTORESIZE and MAXSIZE','add drop extend rebalance','tablespace state and high-water reclaim','SQL0289N blocks/inodes versus logical capacity'],branches:[['Automatic storage','Prefer managed paths and controlled growth where supported.','Growth still needs filesystem capacity and max limits.'],['DMS containers','Use when explicit container layout/legacy compatibility is required.','AUTORESIZE has restrictions, including raw devices.'],['Reclaimable storage','Lower high-water mark or reduce containers after data is eligible.','Free extents inside a table space do not automatically free OS blocks.']],lifecycle:['Identify table-space type and storage group/container paths.','Measure utilization, high-water mark, filesystem blocks and inodes.','Choose grow, rebalance, reclaim or data movement.','Run the state-changing operation with enough path headroom.','Monitor extent movement and recheck table-space plus OS capacity.'],precheck:['List tablespaces, containers, buffer pools, `AUTORESIZE`, MAXSIZE and pending state.','Confirm every storage path has capacity, permission and redundancy.','Check active backup/restore/rebalance conflicts.'],commands:[P('Table-space monitor','SELECT tbsp_name, tbsp_type, tbsp_state, tbsp_utilization_percent FROM TABLE(mon_get_tablespace(NULL,-2)) AS t','Monitor-authorized database user','All visible table spaces in current member scope','Column names are explicit; verify function columns in installed level.','Table space type, state and utilization are returned.','Compare Db2 usage/high-water with filesystem `df` and container paths.','Read-only; do not reclaim before eligibility and free-space estimate.'),P('Bounded automatic growth','ALTER TABLESPACE APPDATA AUTORESIZE YES INCREASESIZE 256 M MAXSIZE 40 G','Tablespace administrator/DBA','APPDATA automatic-storage/DMS eligible table space','Confirm exact type, supported options, disk headroom and change window.','Growth policy and maximum are updated at catalog level.','Read current table-space attributes and test controlled growth in lab.','Restore captured AUTORESIZE/INCREASESIZE/MAXSIZE values if no growth operation has begun; once extended, data movement/reclaim may be required.')],example:'The Db2 space alert is 98%, but filesystem has 60% free and AUTORESIZE is disabled. If the table space is eligible, enable bounded growth after confirming its path, max size and planned capacity; do not resize the filesystem as a substitute for logical-space diagnosis.',expected:'Logical table-space utilization, containers/storage groups, Db2 high-water and OS capacity are distinguished.',issues:[{symptom:'SQL0289N reports no space available.',evidence:'table-space state/utilization, max size, container and `df -h`/`df -i`.',cause:'Logical maximum, filesystem block/inode exhaustion or container path permission.',fix:'Add capacity in the correct layer, then rerun a bounded transaction and verify table-space state.',avoid:'Dropping an arbitrary container while it may hold extents.'},{symptom:'Db2 frees extents but OS usage does not drop.',evidence:'table-space HWM, container size, storage type and MON_GET_EXTENT_MOVEMENT_STATUS.',cause:'Space is available inside container but not released from container/filesystem.',fix:'Use supported reclaim/reduce after eligible extents consolidate; verify both Db2 and OS.',avoid:'Claiming REORG always returns blocks to the operating system.'}],lab:'Create an automatic-storage tablespace in a disposable database with a small bounded maximum. Observe initial allocation and monitor view. Use documentation to compare `LOWER HIGH WATER MARK` and `REDUCE`; do not fill disks intentionally. Cleanup: drop lab tablespace only after checking it contains no other objects.',question:'What does `LOWER HIGH WATER MARK` prove?',answer:'It attempts to lower the table-space high-water mark by moving extents; it does not by itself prove the storage container/file was physically reduced. Check the selected `REDUCE` behavior and OS path.',diagram:'flowchart TD\nO[Object page demand] --> T[Db2 table-space capacity and max]\nT --> C[Container or automatic-storage path]\nC --> F[Filesystem blocks and inodes]\nF --> D[Device volume and latency]\nT --> H[High-water and reclaim eligibility]',refs:[R.tablespace,R.space,R.reclaim],related:['A-04','C-06','F-08','K-01'] }),
L({id:'C-05',title:'EXPORT, IMPORT, LOAD, INGEST, db2move, and db2look',scope:['EXPORT formats consistency and hidden columns','IMPORT insert/replace commit/restart','LOAD phases copy/constraints/restart/terminate','INGEST merge/update and restart keys','db2move scale and staging files','db2look DDL capture not data','reject/message files and post-load verification'],branches:[['EXPORT','SQL SELECT into DEL or IXF; rows honor authorization/RCAC.','Export overwrites existing file; protect sensitive output.'],['IMPORT','SQL-level insertion/update workflows with constraints/triggers behavior.','Usually slower than LOAD; understand commit and restart.'],['LOAD','High-volume utility with phases, access restrictions and recovery states.','COPY/LOGGING and pending-state consequences must be designed.'],['INGEST','SQL-driven incremental insert/update/merge with restart semantics.','Not a synonym for LOAD; syntax and restart table differ.'],['db2move/db2look','Move many tables or extract DDL/statistics information.','Neither alone is a complete cross-version migration/reconciliation.']],lifecycle:['Define source consistency, target object, volume and allowed outage.','Choose utility based on transactional semantics, constraints, triggers and recovery.','Precheck file encoding, code page, columns, keys, logging and copy path.','Run scoped utility and retain message/reject/exception files.','Validate rows, keys, dependent objects, statistics and backup/recoverability.'],precheck:['Compare table DDL on source/target and test representative data types.','Check remaining table-space/log capacity and all required paths.','Record counts/checksums and decide whether concurrent writes are allowed.'],commands:[P('Delimited export','EXPORT TO /tmp/items.del OF DEL MESSAGES /tmp/items.exp.msg SELECT item_id, description FROM APP.ITEMS WHERE active = 1','Database user with SELECT/DATAACCESS','Source SAMPLE database; file written on server host for direct engine utility','Ensure output path is private and does not exist if overwrite is unsafe.','Selected rows are written in DEL format; messages describe warnings/errors.','Count and checksum output; compare selected source rows and protect sensitive data.','Remove only this lab export after verifying path and retention.'),P('Transactional import','IMPORT FROM /tmp/items.del OF DEL COMMITCOUNT 500 INSERT INTO APP.ITEMS_STG','Database user with required insert privileges','Disposable staging table on target','Staging table empty; validate input and use a private message file.','Rows insert in commit batches; warning/reject counts appear.','Compare source and target counts/keys; inspect import messages before promotion.','If partial commits occurred, truncate only the disposable staging table after confirmation.'),P('Bulk LOAD with copy','LOAD FROM /tmp/items.del OF DEL INSERT INTO APP.ITEMS_STG COPY YES TO /db2backup/loadcopy MESSAGES /tmp/items.load.msg','Instance/database utility authority','Server-side target staging table','Archive logging/copy destination/storage and table constraints checked.','LOAD completes through utility phases; copy image and message file are produced.','Check LOAD status, table access/pending state, counts, indexes, constraints, and later backup chain.','Failed job: use documented LOAD RESTART or TERMINATE based on phase; do not blindly rerun.'),P('Restartable INGEST','INGEST FROM FILE /tmp/items.del FORMAT DELIMITED RESTART NEW \'items-load-20261027\' INSERT INTO APP.ITEMS_STG;','Authorized database user','Server-side APP.ITEMS_STG','Restart name unique; input schema and SQL types are reviewed; quote `$field` names if shell command.','INGEST records a restart identity and inserts according to SQL semantics.','Check command output, target keys/count and restart metadata; test RESTART CONTINUE in lab only.','Use RESTART TERMINATE for the intended failed job if abandoning; do not reuse an active restart token.'),P('Schema movement and DDL capture','db2move SAMPLE EXPORT -sn APP; db2look -d SAMPLE -e -z APP -o /tmp/app.ddl','Instance owner / schema reader','Source database APP schema','Run on server with db2move installed; secure files may include business schema.','db2move stages selected data; db2look writes DDL to output file.','Review object dependencies and compare data separately on destination.','Delete generated files only after release evidence and retention review.')],example:'For a high-volume initial load, LOAD may be chosen, but only after a recovery copy/pending-state plan is set. For daily keyed merges, INGEST or SQL may better preserve row-level semantics. The source file size alone does not decide.',expected:'The chosen utility, target access state, restart path, message outputs, row reconciliation and post-operation maintenance are explicit.',issues:[{symptom:'LOAD ends but target is read access only or load pending.',evidence:'LOAD messages/status, `ADMIN_GET_TAB_INFO`, utility history and recovery log config.',cause:'Failed/interrupted LOAD or recovery-copy/logging condition.',fix:'Choose LOAD RESTART/TERMINATE and table-state completion action from the documented current phase.',avoid:'Issuing a new LOAD INSERT over the unfinished operation.'},{symptom:'EXPORT/IMPORT totals differ or data is truncated.',evidence:'message files, code page/file modifiers, hidden columns, delimiters and key-level reconciliation.',cause:'Format/encoding/column order loss or warning rows excluded from db2move list.',fix:'Correct format or mapping and reload into a clean staging target; reconcile every key.',avoid:'Treating a zero process code as proof of semantic equality.'},{symptom:'INGEST retry duplicates or refuses restart.',evidence:'restart name state, target key counts and original job message.',cause:'New restart identity used instead of CONTINUE, or original job already committed rows.',fix:'Inspect restart metadata; resume exact job or terminate and reconcile target before a new identity.',avoid:'Deleting restart metadata without reconciling committed rows.'}],lab:'Prepare a small synthetic input with one valid row, one duplicate key and one malformed numeric field. Run each utility separately against disposable staging tables. Compare triggers/constraints, messages and restart behavior. Cleanup each staging table and remove only the generated lab files.',question:'Which utilities can preserve row-level SQL semantics and which optimize bulk movement?',answer:'IMPORT/INGEST execute SQL-oriented row semantics; LOAD uses high-throughput utility phases with distinct constraint, trigger, copy and table-state behavior. EXPORT, db2move and db2look solve extraction/movement/DDL capture tasks, not full integrity proof.',diagram:'flowchart LR\nS[Source consistency and format] --> D{Required semantics?}\nD -->|extract| E[EXPORT]\nD -->|row SQL behavior| I[IMPORT or INGEST]\nD -->|bulk throughput| L[LOAD]\nD -->|many objects| M[db2move]\nM --> Q[db2look DDL plus data reconciliation]',refs:[R.export,R.load,R.ingest,R.move,['IBM IMPORT command','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-import'],['IBM db2look command','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-db2look']],related:['C-02','C-07','F-03','F-04','I-04'] }),
L({id:'C-06',title:'RUNSTATS, REORGCHK, table REORG, index REORG, types, phases, and monitoring',scope:['RUNSTATS table/index/column/distribution/column groups/profiles','REORGCHK formulas and limitations','CLASSIC offline shadow-copy table REORG','INPLACE FULL and CLEANUP OVERFLOWS','RECLAIM EXTENTS eligible table types','index REBUILD/CLEANUP PAGES/CLEANUP ALL/RECLAIM EXTENTS','phases progress pause/resume/stop and OLR state','partition scope temp/log/space/resource/post-RUNSTATS'],branches:[['RUNSTATS','Refresh optimizer statistics after meaningful data change.','It changes statistics, not row layout.'],['CLASSIC table REORG','Choose for predictable offline window and best reclustering.','Requires shadow/temporary space and has access/locking phases; not pause/resume.'],['INPLACE FULL','Choose when online access matters and table is eligible.','Slower; default truncate phase takes an S lock; partitioned table requires ON DATA PARTITION.'],['CLEANUP OVERFLOWS','Convert pointer/overflow rows without full reclustering.','Does not shrink table size.'],['RECLAIM EXTENTS','Use only supported MDC/ITC/column-organized table types.','Does not mean a general table REORG.'],['Index REORG','REBUILD rebuilds tree; cleanup modes remove pseudo-deleted/empty pages; reclaim releases eligible extents.','Cleanup-only progress may not appear in db2pd reorg list.']],lifecycle:['Collect table/index stats with RUNSTATS and interpret REORGCHK as advice, not a mandate.','Choose table or index operation by goal, access mode, eligibility and resource budget.','Precheck free pages, temporary space, active log, old scanners, partition and recovery.','Start one utility; monitor phase/count/access and resource use.','Pause/resume/stop only online operation using supported state; do not remove `.OLR`.','Run appropriate RUNSTATS/plan checks and verify object/table-space/OS space result.'],precheck:['Use current `REORG TABLE`, `REORG INDEXES`, `REORGCHK` and db2pd docs for exact level.','Check table organization, append mode, XML/extended/expression indexes and partitioning restrictions.','Estimate shadow/temp space for CLASSIC and active-log usage; online access does not mean zero impact.','Capture current table statistics, index design, workload and table-space high-water.'],commands:[P('Statistics by workload-relevant columns','RUNSTATS ON TABLE APP.ORDERS WITH DISTRIBUTION ON COLUMNS (STATUS, REGION) AND DETAILED INDEXES ALL','Database maintenance authority/table control','APP.ORDERS current database partition scope','Confirm schema and cardinality objective; schedule resource window.','Catalog statistics refresh for selected columns and indexes.','Inspect SYSCAT.TABLES/SYSCAT.COLUMNS stats timestamps and compare EXPLAIN estimates.','Statistics are not transactionally rolled back; restore by rerunning the former statistics profile/data state only if justified.'),P('Evaluate reorganization evidence','REORGCHK CURRENT STATISTICS ON TABLE APP.ORDERS','DBA with required authority','APP.ORDERS current partition','Ensure statistics are current; prefer no UPDATE STATISTICS side effect during diagnosis.','Formula output flags possible table/index reorganization benefit.','Inspect table/index pages, overflow, clustering and measured query plans before action.','Read-only decision; do not launch REORG from a formula flag alone.'),P('CLASSIC offline table reorganization','REORG TABLE APP.ORDERS CLASSIC','DBA / table control authority','APP.ORDERS (scope follows database partition group; data partition clause as applicable)','Plan access window, shadow/temp and active log capacity; confirm applications are quiesced or read-only behavior acceptable.','Shadow copy is built and original replaced; indexes are recreated; utility terminates complete.','Use LIST UTILITIES, db2pd -reorgs, catalog data and application smoke test; check table-space use.','CLASSIC cannot be paused/resumed. On interruption use documented recovery/REORG state path; do not delete shadow files.'),P('INPLACE FULL online table REORG','REORG TABLE APP.ORDERS INPLACE FULL ALLOW WRITE ACCESS','DBA / table control authority','Eligible non-append non-MDC/non-ITC non-expression/XML-index table; partitioned requires ON DATA PARTITION','Check eligibility; budget runtime, logs and concurrent DML. Default truncation causes S-lock pause in updates.','Rows move through selected range, vacate, fill and default truncate phases; table stays available except truncate interval.','Monitor `db2pd -db SAMPLE -reorgs`; table info status; sample blocked old scanners and verify physical/plan outcomes.','PAUSE/RESUME/STOP only for in-place work. RESUME must restate important options; preserve `.OLR` files.'),P('INPLACE cleanup and extent reclamation','REORG TABLE APP.ORDERS INPLACE CLEANUP OVERFLOWS; REORG TABLE APP.CUBE_FACT RECLAIM EXTENTS','DBA / table control authority','Eligible APP.ORDERS plus supported MDC/ITC/column-organized CUBE_FACT','Confirm separate eligibility: cleanup converts pointer/overflow records; table RECLAIM EXTENTS is restricted.','First operation cleans overflows; second consolidates/reclaims extents; neither is general classic reclustering.','Check table status, extent movement and measured table-space/file sizes independently.','Stop only according to that operation docs; do not assume cleanup shrinks OS file.'),P('Index rebuild and cleanup choices','REORG INDEXES ALL FOR TABLE APP.ORDERS ALLOW WRITE ACCESS; REORG INDEXES ALL FOR TABLE APP.ORDERS ALLOW WRITE ACCESS CLEANUP PAGES','DBA / table control authority','Indexes on APP.ORDERS','Check access-mode lock impact and select all versus named index; CLEANUP PAGES is not REBUILD.','REBUILD creates new index trees; CLEANUP PAGES removes eligible pseudo-deleted pages.','Monitor rebuild with `db2pd -db SAMPLE -reorgs index`; cleanup-only can have no running entry; check index pages/plan.','Do not issue a second index REORG concurrently on same index; stop/recovery follows selected operation docs.')],example:'An APP.ORDERS table has fresh statistics but poor clustering. REORGCHK is only a signal. Compare a representative access plan and workload, then select classic for offline predictable reclustering or eligible inplace full for access continuity. Separately use cleanup overflows when pointer records are the problem; use extent reclaim only for supported organizations. Recheck statistics and space at each layer.',expected:'The selected command maps to the stated objective and eligible table/index type; post-check distinguishes statistics, row organization, table-space high-water and OS release.',checks:['Capture `LIST UTILITIES SHOW DETAIL` and `db2pd -reorgs` at fixed intervals; phase-specific progress counters are not comparable across phases.','Check table state via `ADMIN_GET_TAB_INFO`, current statistics, representative EXPLAIN, application access and actual space returned.','Do not infer shrinkage from utility completion; compare table space and filesystem separately.'],issues:[{symptom:'INPLACE REORG is paused/aborted or cannot resume.',evidence:'table reorg status, db2pd, diagnostic log, `.OLR` file existence and table life LSN.',cause:'State file deleted/corrupt or table state/LSN changed; resume options may differ.',fix:'Preserve all REORG files; follow IBM recovery path for SQL2219N/state mismatch, then restart only after approved plan.',avoid:'Deleting `.OLR` or copying an unrelated state file.'},{symptom:'Classic REORG runs out of temp/log space or blocks users at replacement.',evidence:'phase, temporary tablespace, log utilization, active scanners and application waits.',cause:'Shadow copy/log capacity inadequate or replacement access boundary not scheduled.',fix:'Stop new work, preserve evidence and follow interrupted classic REORG recovery; expand/plan capacity before rerun.',avoid:'Treating classic as pausable or killing the engine to clear utility state.'},{symptom:'RECLAIM EXTENTS is rejected or no OS space appears free.',evidence:'table organization, error reason, high-water, container type, filesystem size.',cause:'Unsupported table type or internal reclaimed extents remain inside a container.',fix:'Use only supported table type; if eligible, pair table/extent movement with supported table-space reduce and verify OS size.',avoid:'Running extent reclaim on a regular table or claiming it is a full recluster.'},{symptom:'Index cleanup has no db2pd progress entry.',evidence:'utility return/message, selected cleanup option and index page state.',cause:'Monitoring is documented not to show CLEANUP ONLY operation as running.','fix':'Treat command status and index/table verification as primary; use db2pd progress for rebuild modes.',avoid:'Rerunning cleanup because the monitor list is empty.'}],lab:'In a disposable database, create a table with clustered and non-clustered indexes, update/delete rows, and capture RUNSTATS/REORGCHK. Compare the six distinct operations above by goal and eligible organization. Safe drill: pause/resume an inplace operation while restating options; verify preserved `.OLR`; never use `rm`. Cleanup via documented stop/complete flow, then drop lab objects.',question:'A table needs overflow cleanup but should not be reclustered or shrunk. Which operation fits?',answer:'INPLACE CLEANUP OVERFLOWS addresses pointer/overflow rows; it does not shrink the table. Confirm eligibility and verify overflow status separately from extents.',diagram:'flowchart TD\nS[Fresh RUNSTATS] --> R[REORGCHK evidence]\nR --> Q{Measured objective?}\nQ -->|recluster offline| C[CLASSIC shadow copy phases]\nQ -->|online full| I[INPLACE select vacate fill truncate]\nQ -->|overflow only| O[CLEANUP OVERFLOWS]\nQ -->|supported table extent reclaim| E[RECLAIM EXTENTS]\nQ -->|index tree/pages| X[REBUILD or CLEANUP mode]\nC --> V[Post stats plan and space verification]\nI --> V\nO --> V\nE --> V\nX --> V',refs:[R.runstats,R.reorgchk,R.reorg,R.reorgChoice,R.reorgOnline,R.reorgMon],related:['C-04','E-03','H-03','H-04','K-02'] }),
L({id:'C-07',title:'Integrity, pending states, exception tables, dependencies, and package maintenance',scope:['constraint enablement and check-pending states','SET INTEGRITY immediate checked','exception table inspection','dependent view/routine/package invalidation','revalidation and REBIND','DDL dependency and utility interaction','SQL0668N reason codes/data proof'],branches:[['New constraint','Validate existing rows before enforcing.','Do not assume ALTER statement checks every historical row immediately.'],['Check pending','Use SET INTEGRITY after identifying violations and exception design.','Do not force immediate checked without understanding rejected-row behavior.'],['Package/object invalidation','Revalidate dependent objects and rebind packages after DDL.','Successful SQL prepare in one app does not prove all static packages.']],lifecycle:['Identify pending state and exact reason code.','Inspect constraint, dependent objects, package and data scope.','Correct or quarantine invalid rows into approved exception table.','Run SET INTEGRITY and revalidate dependent objects/packages.','Test application path and confirm state is normal.'],precheck:['Save object DDL/grants and dependent-object list.','Check table state with catalog/admin views and exact SQLCODE/SQLSTATE.','Plan exception table columns and data-retention permissions.'],commands:[P('Check table status','SELECT tabschema, tabname, status, access_mode FROM syscat.tables WHERE tabschema = \'APP\' AND tabname = \'ORDER_LINE\'','Catalog reader','APP.ORDER_LINE','Read-only query; verify catalog column names on installed fix pack.','Catalog status/access mode is displayed if visible.','Cross-check `ADMIN_GET_TAB_INFO` and application error reason code.','Read-only; do not ALTER/DROP constraints as a first action.'),P('Revalidate after data repair','SET INTEGRITY FOR APP.ORDER_LINE IMMEDIATE CHECKED','Table owner/DBA with integrity authority','APP.ORDER_LINE and its check-pending constraints','Repair/reject invalid rows first; review whether exception table is needed.','Db2 validates rows and clears check-pending when all rules pass.','Requery table state, row counts, constraint catalog and app CRUD path.','If violations remain, use exception handling path; preserve source rows before changing the constraint.')],example:'A constraint is enabled and a legacy row violates it. Create a reviewed exception destination, capture invalid rows and key values, repair source data, then set integrity and verify no pending state remains.',expected:'Data and dependent objects are valid, table state is normal, and application packages execute after required rebind/revalidation.',issues:[{symptom:'SQL0668N rejects access after ALTER TABLE.',evidence:'reason code, table state, db2diag and exact ALTER action.',cause:'A pending state requires a documented utility or SET INTEGRITY completion step.',fix:'Use the reason-code-specific resolution, validate data, and recheck state.',avoid:'Dropping the object or repeatedly retrying the application statement.'},{symptom:'Static package fails after object change while dynamic SQL works.',evidence:'package validity, dependency catalog, bind options and SQLCODE.',cause:'Dependent package invalidated or its static section needs rebind.',fix:'Revalidate object dependencies and rebind only the identified packages; test app package path.',avoid:'REBIND ALL on production without scope and performance plan.'}],lab:'In a lab schema, create rows including one constraint violation, add a constraint in a way that creates pending work, capture the reason state, then move/fix invalid rows and validate. Verify package validity after a harmless DDL change. Cleanup in dependency order.',question:'What evidence closes a check-pending incident?',answer:'SET INTEGRITY succeeds, system catalogs/admin view show normal table state, invalid rows are accounted for, constraints are enabled, and the application read/write path passes.',diagram:'flowchart TD\nD[DDL constraint change] --> P[Pending state]\nP --> E[Find violations and dependent objects]\nE --> X[Exception capture or repair]\nX --> S[SET INTEGRITY]\nS --> R[Revalidate packages and app]',refs:[R.monitor,['IBM SET INTEGRITY statement','https://www.ibm.com/docs/en/db2/12.1.x?topic=statements-set-integrity']],related:['C-02','C-05','H-02','I-01'] })
);

lessons.push(
L({id:'B-01',title:'Instances, databases, members, agents, and Db2 request path',scope:['install copy versus instance versus database','instance owner/profile and database directory','member versus DPF partition','client-to-listener-to-agent path','package compiler optimizer and data/log path','configuration/catalog/diagnostic boundaries'],branches:[['Install copy','Contains binaries and tools at one Db2 code level.','Not a running database or isolated data directory by itself.'],['Instance','Owns engine processes and DBM CFG; can manage multiple databases.','DB2INSTANCE must match the target.'],['Database/member','Database owns DB CFG/catalog/data; member or DPF partition changes command scope.','Do not assume every operation runs on one host.']],lifecycle:['Select the Db2 copy and load its profile.','Identify the attached instance and its owner.','Resolve local/remote database alias and active member topology.','Trace client request through listener, EDU, package, bufferpool, log and storage.','Verify the response and state at each boundary.'],precheck:['Run `db2level` and `db2 get instance` in the same shell.','Capture directory and member topology before interpreting a handle.','Confirm whether the target is local catalog, remote alias, DPF or pureScale.'],commands:[P('Release and instance identity','db2level; db2 get instance; db2 list database directory','Instance owner','Current shell, instance and catalog directory','Source the intended copy profile; instance owner identity is confirmed.','Db2 code level, instance name and cataloged databases are printed.','Compare database directory entry with the application alias and server host.','Read-only; stop if release or alias differs from the change ticket.'),P('Request-path activity','db2pd -db SAMPLE -applications','Instance owner','Active SAMPLE database/member','Database is active; select member explicitly for scale-out topology.','Active application handles and states are displayed.','Correlate one handle with client, statement and transaction evidence before action.','Read-only; do not force an application solely from a handle listing.')],example:'A user says “the database is down.” `db2 get instance` shows a different DB2INSTANCE from the expected one, and the alias points to a remote server. Correct the shell/context first; do not start a second engine on the wrong host.',expected:'An operator can name binary copy, instance, database, member, alias, application handle, and data/log owner separately.',issues:[{symptom:'`db2 connect` reaches an unexpected database.',evidence:'db2level, `db2 get instance`, node/database directory and server identity.',cause:'Wrong client copy/profile or alias resolves to a different endpoint.',fix:'Switch to the intended profile and verify alias/host before reconnecting.',avoid:'Changing database content to match an incorrect alias.'},{symptom:'Application is active but returns slowly.',evidence:'application handle, EDU state, package/statement, wait category and data/log path.',cause:'Request path is blocked downstream of listener/agent.',fix:'Follow the same handle through wait and resource evidence.',avoid:'Restarting the instance before identifying the blocked path.'}],lab:'Trace a synthetic SELECT from driver to listener to application handle to table-space read. Mark where database configuration, package cache, bufferpool and log appear. Cleanup: detach/reset only your lab connection.',question:'What is the difference between an instance and a database?',answer:'The instance is the engine environment and instance-wide configuration/process scope; a database is a managed set of catalogs, data, logs, and DB CFG owned by that engine. They have different paths, authorities and lifecycle.',diagram:'flowchart LR\nC[Client driver alias] --> N[Node and database catalog]\nN --> S[Server listener]\nS --> E[Agent EDU and package]\nE --> O[Optimizer and bufferpool]\nO --> T[Tablespace data]\nE --> L[Transaction logs]',refs:[R.install,R.monitor],related:['B-02','B-03','B-05','B-06'] }),
L({id:'B-02',title:'Installation copies, licensing, instance creation, profiles, and service lifecycle',scope:['supported host prerequisites','interactive response file and RPM install paths','multiple copies, license and inventory','install logs and instance create/update/drop','profiles and DB2INSTANCE','service registration/autostart','start stop force and reboot validation','fix-pack and uninstall boundaries'],branches:[['New install copy','Use response-file or supported package method for repeatability.','Do not use `db2_install` expecting it to create users or an instance.'],['Instance create','Use db2icrt with deliberate auth/fenced IDs.','Requires root on Linux/UNIX for root installation; local administrator on Windows.'],['Service lifecycle','Drain applications before planned stop; force only with recovery plan.','`db2stop force` disconnects active applications.']],lifecycle:['Check supported OS, libraries, users/groups, limits, storage and licensing.','Install a new copy or update an existing copy using the supported method.','Review install logs and inventory; register license where required.','Create instance and load correct profile; confirm owner/services.','Start instance and test local/remote connections; document rollback version.'],precheck:['Read the exact Db2 12.1 fix-pack installation notes and OS support matrix.','Inventory existing copies/instances and preserve response files and logs.','Confirm Linux root or Windows Local Administrator, fenced user, ports and data paths.'],commands:[P('Copy inventory','db2ls; db2ilist','Host installer / instance owner','Local Db2 host copies and instances','Commands are read-only; run under a shell with Db2 tools in PATH.','Installed copy paths and instance list are returned.','Compare with `db2level` for each instance and license entitlement.','Read-only; do not remove an unfamiliar copy.'),P('Create a lab instance','/opt/ibm/db2/V12.1/instance/db2icrt -a server -u db2fenc1 db2inst1','root on Linux/UNIX root install; Local Administrator on Windows','New instance owner `db2inst1` on lab host','Install copy exists, users/groups exist, and names are unused.','Instance creation completes and instance profile is installed.','Log in as instance owner; `db2 get instance`, `db2level`, and service status agree.','If creation fails, inspect the generated log and use supported db2idrop only after confirming no database data is attached.')],example:'The binaries are installed but `db2 get instance` returns no instance. That is expected before db2icrt; installation and instance creation are separate lifecycle steps. Keep both installer and instance logs with the build record.',expected:'The intended copy, license entitlement, instance owner, fenced identity, service registration, and startup behavior are all verified.',issues:[{symptom:'Installer returns success but `db2ilist` is empty.',evidence:'install logs, chosen installation method, instance inventory and owner/group setup.',cause:'Binary installation completed but instance creation was not part of that method.',fix:'Create the instance separately using documented db2icrt prerequisites.',avoid:'Rerunning installation blindly over the same copy.'},{symptom:'Instance starts manually but not at boot.',evidence:'service registration, owner profile, mount dependencies, journal/system log.',cause:'Service unit lacks environment or starts before data/log mounts.',fix:'Configure the supported service integration and boot dependency; test reboot in lab.',avoid:'Root-owned cron that launches Db2 without owner context.'}],lab:'Install only in an isolated disposable VM. Compare response-file and package-install paths, create an instance, validate owner and service restart after a planned reboot. Cleanup: archive installation logs; drop only the empty lab instance and remove only its matching copy.',question:'Why might `db2_install` leave no instance behind?',answer:'It deploys product components but does not create users/groups, instance, or configuration. The installation method and instance lifecycle are separate.',diagram:'flowchart TD\nP[Prerequisite and entitlement check] --> I[Install copy]\nI --> L[Inspect install log and inventory]\nL --> X[Create instance]\nX --> S[Register and start service]\nS --> V[Version and connection verification]',refs:[R.install,R.icrt],related:['A-02','B-01','I-02'] }),
L({id:'B-03',title:'Database creation, activation, connections, and configuration scope',scope:['CREATE DATABASE code set territory collation page size and storage','DBM CFG versus DB CFG versus registry/environment','online immediate deferred/reactivate/restart parameter classes','effective values and member scope','activate deactivate connect disconnect','configuration baseline diff and rollback'],branches:[['DBM CFG','Instance-wide defaults, communication and engine resources.','Changing one database setting cannot alter it.'],['DB CFG','Per database resource/recovery behavior; some values activate on reactivation.','A value shown in config may not be effective until the next lifecycle boundary.'],['Registry/environment','Instance or client profile behavior (db2set/shell).','Not SQL configuration; persistence and scope differ.']],lifecycle:['Choose database path, territory/code set, page size, logging/storage and owner.','Create database with explicit choices.','Capture DBM CFG, DB CFG and registry separately.','Classify the selected setting as online, deferred, reactivation or restart.','Apply one scoped change and verify effective value after required boundary.'],precheck:['Check database alias/path and ensure it does not already exist.','Capture `GET DBM CFG SHOW DETAIL`, `GET DB CFG ... SHOW DETAIL`, and `db2set -all`.','Read the selected parameter reference for supported value, propagation class and topology behavior.'],commands:[P('Create isolated sample','db2 create database SAMPLE automatic storage yes using codeset UTF-8 territory US','Instance owner','New single-member lab database SAMPLE','Alias unused; destination has measured capacity; command is for disposable lab only.','CREATE DATABASE completes and catalogs SAMPLE.','List database directory, connect, check code set/page size and database path.','Drop only the newly created empty lab database after independent identity check.'),P('Inspect effective scope','db2 get dbm cfg show detail; db2 get db cfg for SAMPLE show detail; db2set -all','Instance owner','Instance and SAMPLE configuration','No state change; save output with timestamp and release.','Current/deferred values and registry variables are displayed.','Compare current and delayed values; confirm member scope for pureScale/DPF.','Read-only; do not edit Db2 config files directly.')],example:'Before adjusting `LOGPRIMARY`, establish that the property belongs to DB CFG and determine whether it is online for this release. Compare the current and delayed values, assess active-log filesystem headroom, then apply and verify through GET DB CFG and a controlled workload.',expected:'A configuration change is tied to the correct scope and propagation class, with a recorded prior value and safe rollback.',issues:[{symptom:'GET DB CFG shows new value, but behavior does not change.',evidence:'current/delayed values, database activation, all connections, and parameter docs.',cause:'Parameter is deferred until reactivation or requires instance restart.',fix:'Schedule the documented boundary, drain safely, reactivate/restart, and verify effective value.',avoid:'Repeatedly issuing UPDATE DB CFG or editing SQLDBCONF directly.'},{symptom:'A setting differs across members or appears not to persist.',evidence:'member-aware config output, command scope, registry profile and start environment.',cause:'Wrong scope or per-member behavior not included in the change plan.',fix:'Set supported scope explicitly and inspect effective value on each member.',avoid:'Assuming one-member results generalize to DPF or pureScale.'}],lab:'Create SAMPLE and save all three configuration views. Change one documented online parameter in the disposable database, record current/delayed value, and restore the baseline. Cleanup: deactivate/drop SAMPLE only after confirming its path and name.',question:'Why are DBM CFG, DB CFG and db2set separate evidence?',answer:'They affect different scopes and have different storage, persistence and activation behavior. A matching-looking value at one layer does not prove the other layers or effective runtime state.',diagram:'flowchart TD\nE[Shell environment and DB2INSTANCE] --> I[Instance DBM CFG and registry]\nI --> D[Database DB CFG]\nD --> R[Runtime effective value]\nR --> A{Online deferred reactivate or restart?}',refs:[R.config],related:['B-01','B-02','B-04','D-01'] }),
L({id:'B-04',title:'CLP, SQL boundaries, command files, terminators, quoting, and safe workflows',scope:['interactive CLP and connection context','semicolon and alternate terminators','CLP commands versus SQL statements','shell quoting and variable substitution','command-file stop/continue and return codes','secure output and target guard'],branches:[['Interactive CLP','Use for short inspection with explicit connect/reset.','Session context persists; verify database before state change.'],['Command file','Use alternate terminator when SQL contains semicolons or compound blocks.','Do not assume first error stops every command file.'],['Shell wrapper','Use argument-safe invocation and preserve exit status.','Avoid `eval`, secrets in argv, and silent pipeline failures.']],lifecycle:['Set release/profile and a clean CLP session.','Validate database alias and connect identity.','Choose terminator and quoting for SQL and host shell layers.','Run read-only preflight; execute bounded script with captured output/return code.','Reset connection and verify result independently.'],precheck:['Place scripts in a private, version-controlled lab directory.','Use unique lab schema/database and no password literals.','Review every statement for COMMIT, DDL, utility or target change.'],commands:[P('Alternate terminator script','db2 -td@ -vf setup.sql','Instance owner or authorized database user','Database named inside `setup.sql`','File uses `@` terminators; inspect the complete file before execution.','CLP echoes statements, emits messages and returns a process status.','Query the resulting object/data and check shell `$LASTEXITCODE`/`$?` appropriate to host.','Use ROLLBACK only for uncommitted transactional work; DDL/utility effects need their own compensation.'),P('Safe read-only interactive session','db2 connect to SAMPLE; db2 "values current server, current user"; db2 connect reset','Client/instance owner','Cataloged SAMPLE alias','Alias has been independently verified; values are read-only.','Current server and authorization identity are returned.','Confirm server name matches ticket before running any later command.','Connect reset ends the session; no database changes are made.')],example:'A compound SQL procedure has internal semicolons. Running `db2 -tvf` stops at the first semicolon rather than treating the procedure as one statement. Set `@` as terminator and ensure only the file’s outer statements end with `@`.',expected:'The script runs against one verified target, logs stdout/stderr and exit status, and leaves no unintended connection or open unit of work.',issues:[{symptom:'SQL file is split inside a procedure or trigger.',evidence:'CLP echo, file terminators, and parser error line.',cause:'Default semicolon terminator conflicts with SQL compound body.',fix:'Set a deliberate alternate terminator and test in an empty lab schema.',avoid:'Blindly replacing every semicolon in the SQL source.'},{symptom:'Script reports failure but later statements still execute.',evidence:'CLP options, wrapper status handling and final object state.',cause:'Command-file continuation semantics or shell pipeline discarded exit status.',fix:'Use explicit per-command checks and stop logic; inspect partial effects before retry.',avoid:'Re-running non-idempotent DDL/LOAD after a partial failure.'}],lab:'Create a script with a compound SQL body, one deliberate syntax error in a disposable file, and a following marker statement. Observe terminator and continuation behavior; then write a wrapper that stops on failure and prints the command status. Cleanup: drop only the lab routine/table.',question:'Why can a successful shell process still hide a failed Db2 statement?',answer:'A wrapper can discard or overwrite the CLP return code, or continue after an error. Preserve command status and verify expected database state instead of trusting the final shell line.',diagram:'flowchart LR\nS[Shell parser] --> Q[Quoting expansion] --> C[CLP terminator parser] --> SQL[SQL or CLP command]\nSQL --> R[Db2 result and return code]\nR --> V[Independent state verification]',refs:[R.install,R.config],related:['B-03','J-01','J-02'] }),
L({id:'B-05',title:'Agents, EDUs, units of work, and Db2 memory areas',scope:['connection and agent/concentrator models','EDU type and process/thread mapping','unit-of-work age and commit boundary','private/shared memory sets','database and instance memory','bufferpool sort lock/package/utility consumers','saturation evidence'],branches:[['Agent pressure','Separate connected clients from active agents and pool demand.','Connection count alone does not establish agent shortage.'],['Memory consumer','Attribute usage to memory set, database, member and component.','Never increase a heap without checking host and cgroup headroom.'],['UOW duration','Use transaction age and commit boundary to find retained locks/logs.','Do not force an application based only on age.']],lifecycle:['Enumerate connections and active work.','Map application handle to EDU and member.','Inspect transaction age and memory-set consumers.','Compare interval demand with configured/automatic caps and host limits.','Remeasure after a workload or memory-control change.'],precheck:['Use the instance owner and correct database/member.','Capture host memory, Db2 memory sets and connection activity at the same interval.','Name the exact component before changing any parameter.'],commands:[P('EDU and memory inventory','db2pd -db SAMPLE -edus; db2pd -db SAMPLE -memsets','Instance owner','SAMPLE and its active member','Instance/database active; options are read-only.','EDU state and memory-set usage are emitted.','Repeat with MON_GET_AGENT/MON_GET_MEMORY_POOL and compare host committed memory.','Read-only; do not terminate EDUs or raise memory limits from one snapshot.'),P('Long UOW inspection','db2 "select application_handle, uow_start_time, uow_log_space_used from table(mon_get_unit_of_work(null,-2)) as u"','Database user with monitor privileges','Connected SAMPLE member(s)','MON_GET_UNIT_OF_WORK is member-aware; name columns explicitly.','Rows show active unit-of-work start and log usage metrics.','Join handle to application and lock-wait evidence; no rows may mean no current UOWs.','Read-only; data values depend on workload and monitor privileges.')],example:'A high open-connection count with low active-agent count suggests idle pooled sessions, while a few active agents have high sort memory. Tune the active sort workload or concurrency only after measuring spills and host memory; do not reduce connections blindly.',expected:'Connection count, active EDUs, transaction age, and memory consumption are distinct measurements with scope and interval.',issues:[{symptom:'A connection limit alert fires but CPU and active work remain low.',evidence:'agent pool state, connection concentration, app status, and workload classes.',cause:'Many idle persistent sessions rather than executing agent saturation.',fix:'Review pool idle/lifetime settings with the application team and monitor active demand.',avoid:'Increasing AGENT_MAX as a reflex.'},{symptom:'Host begins swapping after a memory parameter increase.',evidence:'Db2 memory set growth, Linux reclaim/swap, cgroup limit and workload concurrency.',cause:'Database allocation exceeded safe physical/container headroom.',fix:'Restore the captured parameter value at its supported propagation boundary; reduce competing demand and remeasure.',avoid:'Changing several memory parameters together.'}],lab:'Use a small synthetic workload with one long transaction and one sort-heavy query. Observe UOW age, EDU states and memory sets in separate snapshots. Commit/rollback only your test work; verify normal memory and connection counts afterward.',question:'Which evidence proves that a connected application is actively consuming an agent?',answer:'An active application/agent state correlated with an EDU and current activity; connected count alone can include idle pooled sessions.',diagram:'flowchart TD\nC[Client connection] --> A[Agent or connection concentration]\nA --> E[EDU activity and UOW]\nE --> M[Memory set component]\nM --> H[Host and cgroup headroom]',refs:[R.mon,['IBM db2pd reference','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-db2pd-monitor-troubleshoot-db2-engine-activities']],related:['B-01','E-03','E-04','H-06'] }),
L({id:'B-06',title:'Standalone, DPF, and pureScale architectures and operational boundaries',scope:['single-member standalone','DPF members/partitions catalog node distribution map FCM','pureScale members CF cluster filesystem interconnect recovery','topology discovery and command scope','member-aware utilities and failure drills'],branches:[['Standalone','One member owns the database engine boundary.','A second instance is not DPF.'],['DPF','Data is distributed across database partitions and partition groups.','Command effects may fan out; catalog partition matters for some recovery tasks.'],['pureScale','Members coordinate through CFs and shared cluster storage.','It is not DPF; member and CF failures use different recovery paths.']],lifecycle:['Discover product feature and topology from supported tools.','Map member/partition identifiers to host and database path.','Classify command scope as local, member, partition or cluster-wide.','Use topology-native monitoring and failure procedures.','Prove data placement and service recovery across the intended scope.'],precheck:['Confirm `db2level`, `db2instance -list` when pureScale, and db2nodes.cfg when DPF.','Record catalog partition/member and cluster manager health.','Do not run a single-member lab command across a multi-host cluster without local runbook review.'],commands:[P('DPF topology inventory','cat $HOME/sqllib/db2nodes.cfg; db2_all "hostname"','Instance owner','All configured DPF partitions','Only on DPF; use bounded host command and validated instance profile.','Node list and one response per participating host are produced.','Compare partition IDs, host list and database partition group distribution.','Read-only; do not edit db2nodes.cfg while instance is running.'),P('pureScale member status','db2instance -list; db2pd -db SAMPLE -members','Instance owner','pureScale cluster and SAMPLE members','Only on pureScale; require cluster health and correct instance.','Member/CF role and database member status are shown.','Compare with cluster manager and CF health, not one Db2 output alone.','Read-only; cluster repair/failover must follow cluster-manager procedure.'),P('Standalone boundary','db2pd -inst; db2 list db directory','Instance owner','One standalone host','Correct instance profile; do not infer topology from catalog entries alone.','One local engine inventory and database directory are returned.','Check host inventory and absence of DPF/pureScale configuration.','Read-only.')],example:'The same backup request needs topology-specific scope: a standalone database has one engine target; DPF requires partition-aware image and restore planning; pureScale uses member/CF awareness and cluster-managed resources. Name that boundary before selecting a utility.',expected:'A topology diagram lists hosts, members/partitions, catalog node, CFs, shared filesystems, and command fan-out.',issues:[{symptom:'Command succeeds on one node but database remains inconsistent across a DPF target.',evidence:'db2nodes.cfg, per-partition utility/status output, and catalog partition role.',cause:'Command was run at the wrong scope or one partition did not participate.',fix:'Use supported partition-wide operation and verify every partition result.',avoid:'Repeating a state-changing command independently on nodes without partition semantics.'},{symptom:'pureScale member failure is mistaken for a partition failure.',evidence:'`db2instance -list`, CF and cluster manager health, member recovery state.',cause:'DPF and pureScale concepts were conflated.',fix:'Follow the pureScale member/CF recovery sequence and verify cluster filesystem/interconnect.',avoid:'Editing db2nodes.cfg or forcing DPF utilities on pureScale.'}],lab:'Draw three separate diagrams: single-member, two-partition DPF, and two-member/two-CF pureScale. For each mark where a backup, `db2pd`, member failure and recovery decision is scoped. Use documentation only; no cluster lab exists here.',question:'What information must be added before turning a standalone command into a DPF runbook?',answer:'Partition list/catalog partition, per-partition data placement and command fan-out, host mapping, consistency behavior, and verification for every participating partition.',diagram:'flowchart LR\nS[Standalone one member] --- D[DPF partitions and distribution] --- P[pureScale members CF shared cluster FS]\nD --> N[Partition scope and catalog node]\nP --> C[CF member and cluster manager scope]',refs:[R.monitor,['IBM Db2 pureScale HADR overview','https://www.ibm.com/docs/en/db2/12.1.x?topic=idpe-high-availability-disaster-recovery-hadr-in-db2-purescale-environments']],related:['G-06','F-03','F-05','E-03'] })
);
